window.__D("text/torat-chaim/c037",{"p":[[2300550818,"תו\"מ שנק' לחם לאכול ובגד ללבוש כנ\"ל (שזהו העולה בבחי' העלאת מ\"ן) כך הוא בבחי' הירידה וההמשכה דחסדי' דאו\"י דמשפיע אל המקבל (בבחי' המשכת מ\"ד בכלל) [כמו] שנמשך מאור הזרוע לצ\"ע שהוא בחי' יסוד למל' שהן כנ\"י למטה, כל ג' אלה הדברים הנ\"ל בבחי' מזון ולבוש ובית כו', והוא כמ\"ש שארה כסותה ועונתה כו' דשארה אלו המזונות שחייב אדם לזון את אשתו וכסותה כמשמעו כו'. וכך הוא למעלה ביח\"ע דקוב\"ה ושכינתי' שנק' כמו יחוד איש ואשתו דהבעל חייב במזונות אשתו<sup data-n=\"8236\">1207</sup> כו', כך נמשך בחי' מזון העליון דחסדי' העליונים שבח\"ע דאור אבא כענין אכלו ריעים כו' (וכסעודה דע\"י בשבת כו' שהוא<sup data-n=\"8237\">1208</sup> אותיות דתשב\"כ) שיורד בבחי' או\"י מלמעלה למטה לבחי' המל' להיות מזון לנשמות בג\"ע, שבא הכל בבחי' פנימי' האור העליון דאצי' כמו שהוא בלי בחי' חיצוני' ופסולת כלל מאחר שאינו בא מכח הבירורים שלמטה כלל, דהיינו מבחי' עה\"ח שלמעלה מעה\"ד טו\"ר שנק' מזונא דח\"ע כמו שהוא בפנימי' אבא ופנימי' ע\"י (כטל תורה שהוא פנימי' העונג העליון שבפנימי' ח\"ע שלא הי' שם שבירה<sup data-n=\"8238\">1209</sup> כלל וכלל כידוע). וכמו לחם הפנים שהגם שנעשה מערכת הלחם הזה בבירורי' דמאכל בחרישה וזריעה עד לישה ואפי' כסדורא דמלאכו' בפת מ\"מ האיר בלחם זה בשבת מפנימי' דח\"ע ופנימי' ע\"י שנק' לחם הפנים שכולו פנימי' בלי חיצוני' כלל וכסעוד' דע\"י ממש. וכמו שהי' בכיוצא בזה במזון דמן דהגם שירד בהגשמה כזרע גד לבן<sup data-n=\"8239\">1210</sup> כו' ודכו [אותו] במדוכה ובשלו בפרור<sup data-n=\"8240\">1211</sup> כו' ומ\"מ לא הי' בו בחי' פסולת כלל שהרי הי' נבלע באברי' כידוע, וזהו לפי שהי' שרשו מעה\"ח<sup data-n=\"8241\">1212</sup> שלמעלה מעה\"ד טו\"ר לגמרי כמ\"ש במ\"א, וזהו בחי' המזונו' העליוני' שירדו לנש\"י במדבר שנק' לחם מן השמים שלא ע\"י אתעדל\"ת כלל בבירורי' דל\"ט מלאכות כתבואות לחם הארץ כו' וד\"ל.\n<b>וזהו</b> שארה אלו המזונות שהי' זן ומפרנס לכנ\"י במדבר לערוך שולחן להם בלחם מן השמים כמזון המן, וכך הוא למעלה גם עכשיו שנמשך מאור הזרוע לצ\"ע בחי' חסדים דח\"ע הפנימי' ועצמי' כמו באור דתורה <span data-k=\"pg\">1264</span> ּ בבחי' הסתים שבה כרזי' וסודות התורה שמתוקי' מדבש כו' כמו במן שאו' והי' טעמו כטעם לשד השמן<sup data-n=\"8242\">1213</sup> וכצפיחי' בדבש<sup data-n=\"8243\">1214</sup>, וגם האותיות דתשב\"כ מאירי' מאור העליון דפנימי' הח\"ע בלי העלם כלל כידוע [כמו בלוחות הראשונות שהיו כתובים ב' עבריהם<sup data-n=\"8244\">1215</sup> ]. והיינו ג\"כ ענין סעודת השבת עכשיו שהן בדוגמא למזונא דח\"ע דמן שהי' במדבר וכלחם הפנים כו', אעפ\"י שבודאי נעשה מלחם ובשר דחי וצומח שמן הארץ שבא מבירורי' דטו\"ר דוקא כנ\"ל אבל מאיר בזה",[["8236","1207","<b>דהבעל חייב במזונות אשתו</b>: כתובות מו, ב. רמב\"ם פי\"ב מהל' אישות ה\"ב (ובנ\"כ)."],["8237","1208","<b>(וכסעודה. . שהוא</b>: יאיז: וכסעודה. . (שהוא."],["8238","1209","<b>שבפנימי' ח\"ע שלא הי' שם שבירה</b>: ראה לעיל פ' יתרו ער, ד ובהנסמן בהערות 73-6. ש\"א מב, א. לעיל פ' שמות מב, ב. בשלח רי, ד."],["8239","1210","<b>דמן. . כזרע גד לבן</b>: בשלח טז, לא."],["8240","1211","<b>ודכו [אותו]. . בפרור</b>: בהעלותך יא, ח."],["8241","1212","<b>דמן. . שרשו מעה\"ח</b>: ראה לעיל פ' בשלח רי, ד."],["8242","1213","<b>והי' טעמו כטעם לשד השמן</b>: בהעלותך יא, ח."],["8243","1214","<b>וכצפיחי' בדבש</b>: בשלח טז, לא."],["8244","1215","<b>בלוחות. . ב' עבריהם</b>: תשא לב, טו. ראה גם לעיל פ' בשלח ריב, א. וש\"נ."]]],[2300550819,"מלמעלה מעה\"ד טו\"ר כמ\"ש וקראת לשבת ענג העליון כמו שהוא בפנימי' דעה\"ח שכולו חיים וטוב בלא חיצוני' כלל, מטעם שבשבת למעלה מן הבירורי' ומפני שכבר הוברר בוי\"מ החול בל\"ט מלאכות (כמשי\"ת). והמדרגה הב' בלבושי' דכנ\"י שנמשך מלמעלה למטה כמו במדבר שהאיר להם מאור ולבוש העליון כמ\"ש שמלתך לא בלתה<sup data-n=\"8245\">1216</sup> כו', וגם עדי ותכשיטי' כמו במ\"ת שקיבלו עדיים<sup data-n=\"8246\">1217</sup> כידוע. וכן כמו בית והיכל בסוכות שישבו בנ\"י במדבר<sup data-n=\"8247\">1218</sup> והוא כמו ענני כבוד<sup data-n=\"8248\">1219</sup> שהקיפם מלמעלה למטה (שזהו בבחי' מקיף למקיף כנ\"ל), וזהו כסותה ועונתה כו' שהוא גוף היחוד שהוא בהיכל ואהל דוקא כמו במשכן דמשה שא' ושכנתי בתוכם, דאעפ\"י שכל מה שנדבו בהבאת המשכן הי' בדרך העלאה ובירור כמו בל\"ט מלאכות כנ\"ל מ\"מ אחר שנעשה המשכן וכליו נמשך בהן יח\"ע דח\"ע דע\"ס דאצי' בג' דברים כמו [ב]שארה כסותה ועונתה כו' דמשפיע למקבל כנ\"ל וד\"ל.\n<b>ובכ\"ז</b> מתורץ לכאורה ענין הקושיא הנ\"ל דלמה הותרה האכילה בשבת אחר שהאכילה זהו ענין בירור בטו\"ר כנ\"ל, דודאי עיקר הבירורי' בל\"ט מלאכות ובפרט במזון דלחם הכל בימות החול דוקא שנק' ו' ימי המעשה שאז דוקא הוא זמן הבירורי' במלאכה ועבודה, כי גם למעלה הרי בכ\"י מחדש מע\"ב מאין ליש כמו בבחי' מלאכה ועבודה כמו כח הפועל בנפעל ממש. ולכך נק' ו' ימי המעשה דוקא כמו וימ\"ב שע\"ז א' ו' ימים תעשה מלאכה תעשה דוקא, להיות כי גם [במה] ש[כבר] ברא אלקי' במע\"ב בוימ\"ב א' לעשות לתקן, כי גם [ב]בחי' מעשה זו שמחדש בחידוש בכ\"י מע\"ב הרי מתקן הוא בבירור טו\"ר ובהבדלה דפנימי' וחיצוני'. ולכך גם בנפש האדם שנעשה בצלם האלקי' ממש צריך שיהי' בוי\"מ החול בבחי' עבודה ומלאכה ברוחני' בתפלה בעבודה שבלב ומוח לברר בין טו\"ר שבנה\"ב, וכן בכל מעשיו אף באכילתו שלא למלאות כריסו כדי שיעלה בחי' הטוב שבמאכל לשובע נפשו לבד כנ\"ל (וכן ביגיעתו במו\"מ להיות בסומ\"ר מגזל כו' ולהעלות הטוב בצדקה וכה\"ג. וכן בלבושי[ו] ודירתו יתקן ויברר הכל שיהי' נקי מכל סיג כו'. אבל לאחר שכבר הוברר בימות החול בג' חלוקו' דמזון ולבוש ובית כו' שכוללי' ל\"ט מלאכות בגשמיות וברוחניות, הרי בהגיע יום השבת צריך לנוח ולשבות מכל מלאכתו אשר עשה ובירר כל וי\"מ החול, כמו שלמעלה בבחי' אדם העליון דאצי' ששובת ונח מכל מלאכתו שעושה ומחדש מע\"ב בכל וי\"מ החול. כי כל שבת הוא כמו שבת בראשית<sup data-n=\"8249\">1220</sup> ממש מאחר שמחדש <span data-k=\"pg\">תרלב</span> ּ בכל יום בדבור ומעשה מאין ליש בעולמות העליונים והתחתונים כידוע. וענין השביתה זהו בחי' ההעלא' שאחר הבירור שהי' בעבודה ומלאכה בחול כמו וירא אלקים את כל אשר עשה והנה טוב",[["8245","1216","<b>שמלתך לא בלתה</b>: עקב ח, ד."],["8246","1217","<b>במ\"ת שקיבלו עדיים</b>: תשא לג, ו."],["8247","1218","<b>בסוכות שישבו בנ\"י במדבר</b>: אמור כג, מג."],["8248","1219","<b>בסוכות. . ענני כבוד</b>: ראה גם לעיל פ' בשלח רלג, ג. רמב, ב ובהנסמן שם."],["8249","1220","<b>כל שבת. . שבת בראשית</b>: נסמן לעיל פ' יתרו רסד, א."]]],[2300550820,"כו', שלאחר המעשה בבירור והבדלה יצא הכל בכי טוב ונקי מכל פסולת [וסיג לגמרי. וזהו כמו שמבררי' האוכל מכל פסולת] שבו, שיוצא הפסולת בפ\"ע והטוב בפ\"ע שאז ראוי הוא להעלות על שולחן מלכים או לבעה\"ב שיאכל כמו שא' מי שטרח בע\"ש כו'<sup data-n=\"8250\">1221</sup>, שבגמר הבירור א\"צ לתקנו עוד רק להעלותו למאכל. והאכילה עצמה אין זה בירור כלל מאחר שכבר הוברר, [וע\"כ] אינו דומה אכילה דשבת לאכילה דחול [דאכילה דחול] גם שמברר בין טו\"ר עדיין צריך בירור בנפש להבדיל חלק הרע שבמאכל כנ\"ל. אבל תבשיל דשבת ממילא הוברר כבר ואינו רק בבחי' הטוב שבו לבד שא\"צ בירור עוד רק לאכול לעונג, שהרי אפי' [לאכול] לתיאבון מותר לאכול בשבת משום דאין בתאוה זו פסולת ורע כמו בחול מטעם שעונג העליון [האלקי] שבשבת בא אחר הבירורי' דחול כמ\"ש והנה טוב מאד כו', ואין בשבת רק בחי' העלאה דטוב לבד כדוגמא שהי' בלחם הפנים ומזון דמן במדבר שלמעלה מעה\"ד טו\"ר כנ\"ל שאין בו פסולת כלל, ולכך יש בכל שבת מיום שכולו שבת שהוא העוה\"ב שלאחר הבירור דעה\"ד טו\"ר לגמרי.\n<b>וזהו</b> שא' ולא פר\"ש שבתכם שבמאכל דשבת אין פר\"ש כלל, וראי' ממה שאו' דא היא סעוד' דע\"י ממש כו' כלחם הפנים שכולו פנימי' כנ\"ל וד\"ל<sup data-n=\"8251\">1222</sup> (ואעפ\"י שבודאי יש חלק הרע שבמאכל גם בתבשיל דשבת שממנו נעשה חום הטבעי בדם ובשר כמו בחול [ל]גשם הגוף כפי הטבע, אבל אינו פועל רע בחום תאוה זרה כלל אלא עולה גם הוא למעלה כחו\"ד דבהמה במזבח כו' (שעונג המורגש שלאחר הבירור דעה\"ד יעלה לעונג העליון האלקי כמו ישבעו ויתענגו<sup data-n=\"8252\">1223</sup> במורגש בלב בשר בתענוג גשמי ממש, ואין בו פירוד כלל [מאלקות (שזהו הטעם שזווגא דחכימין דוקא בשבת<sup data-n=\"8253\">1224</sup> שלא יש בחי' פירוד כ\"כ] באש בתאו' המשגל לק\"נ עד שיכול להמשיך נשמה קדושה אף בחום התאוה. וכמו שהי' הזווג באו\"ח<sup data-n=\"8254\">1225</sup> קודם החטא שעלו למטה ב'<sup data-n=\"8255\">1226</sup> כו' כי לא הרגישו תאו' חומריות בזה כלל ע\"כ לא יתבוששו בהיותם ערומים<sup data-n=\"8256\">1227</sup> כמ\"ש במ\"א) וכך יכול להיות ע[ו]נג הגשמי דמורגש בחום הטבעי ממאכל דשבת ולא יעשה דבר רע כלל בנה\"ב והוא מצד בחי' הנשמה יתירה<sup data-n=\"8257\">1228</sup> שמאיר ביחיד' מאור עונג העליון האלקי בכל איש מישראל (וניכר אפס קצהו אף בחיות המורגש שבדמי') (כמו שהעיד ע\"ז מן גדולי חכ[מי] הרופאי' שבליל שבת ויומו יש שינוי גדול בדפק שביד הישראל מחמת הארת אור<sup data-n=\"8258\">1229</sup> העונג העצמי' דיחידה אעפ\"י שה[ו]א",[["8250","1221","<b>כו'</b>: יאיז: יאכל בשבת."],["8251","1222","<b>וד\"ל</b>: שם: ליתא."],["8252","1223","<b>ישבעו ויתענגו</b>: תפלת העמידה לשבת (ישמחו במלכותך). ראה גם לעיל פ' שמות לג, ג."],["8253","1224","<b>שזווגא דחכימין. . בשבת</b>: ראה זהר בהקדמה יד, סע\"א. תרומה קלו, סע\"א. ויקהל רד, ב."],["8254","1225","<b>באו\"ח</b>: באדם וחוה."],["8255","1226","<b>שעלו למטה ב'</b>: סנהדרין לח, ב."],["8256","1227","<b>לא יתבוששו בהיותם ערומים</b>: בראשית ב, כה. ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' רנט ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670058\" data-slug=\"torat-chaim\" data-id=\"2300670058\">תו\"ח בראשית ל, ג</a> ואילך ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ג ס\"ע א'קיח ואילך."],["8257","1228","<b>דשבת. . הנשמה יתירה</b>: נסמן לעיל שצג, ג."],["8258","1229","<b>אור</b>: ויאיז: ליתא. יב: כבפנים."]]],[2300550821,"בהעלם גדול (וכמו שנעשה שינוי לטוב בדפק מאיזה עונג נפלא מבשורה טובה שתדשן עצם<sup data-n=\"8259\">1230</sup> כמו שהי' בריב\"ז<sup data-n=\"8260\">1231</sup> ). וראי' לכ\"ז מן אש הגיהנם ששובת בשבת<sup data-n=\"8261\">1232</sup> [אעפ\"י] שהוא [בריאה] טבעי' וסמבטיון יוכיח<sup data-n=\"8262\">1233</sup> וכה\"ג, לפי שביום השבת יש בו מעין דעוה\"ב<sup data-n=\"8263\">1234</sup> שאין שליטה לחלק הרע והפסולת וחומריות כלל וכלל כידוע וד\"ל).\n<b>אך</b> הנה עדיין יש להבין האיך הותר האכילה בשבת מאחר שנק' קדש העליון שלמעלה מבחי' הבירורי' לגמרי (וכמו יו\"כ שאין בו או\"ש<sup data-n=\"8264\">1235</sup> כמו העוה\"ב<sup data-n=\"8265\">1236</sup> ממש לפי שנק' שבת שבתון וכך שבת הרי נק' שבת שבתון מטעם הנ\"ל), והאכילה מצד עצמה נק' בירור כנ\"ל (והרי <span data-k=\"pg\">1266</span> ּ א' באתרי' לאו אורחא למיכל<sup data-n=\"8266\">1237</sup> כו' רק באתי לגני [א\"כ<sup data-n=\"8267\">1238</sup> ] אכלתי כו' כמ\"ש בזהר) ואעפ\"י שאו' [בזוהר] דא היא סעודתא דע\"ק כו' היא גופא י\"ל שהרי באתרי' לאו אורחי' למיכל כנ\"ל). ואמנם הנה יש להבין עוד ענין א' שהיא קושיא חזקה יותר בענין השבת והוא מה שהותרו הקרבנות להקריב בשבת כמו בחול, שהרי הל\"ט מלאכות נאסרו בשבת מטעם שהן נעשי' בבחי' הבירורי' כמו להפריד האוכל מפסולת שבו [כ]מלאכות דמזון בזריעה וקצירה עד לישה ואפי' כו'. והרי הקרבנות נעשי' ג\"כ בבחי' הבירורי' שהוא רק העלא' הטוב מן הרע כמו בשחיטה וזריקה דדם והקטר חלבי' וכה\"ג [ו]כידוע. וגם בעצם העלא' דקרבן ע\"ג המזבח [ב]אש כו' [ש]זהו שנק' אכילת מזבח ואכילת אדם כמ\"ש [את קרבני] לחמי לאשי כו', והאכילה הוא ענין בירור מצד עצמו כנ\"ל. ואיך יהי' ענין הבורר בשבת מאחר שנק' קדש העליון שלמעלה מבחי' הבירורים לגמרי כנ\"ל, ואם לפי שכבר הוברר בימות החול בל\"ט מלאכות וא\"צ בשבת לברר כולם<sup data-n=\"8268\">1239</sup>, רק להיות בחי' העלאה שאחר הבירור כנ\"ל. א\"כ אדרבה היא גופא קשיא א\"כ<sup data-n=\"8269\">1240</sup> כבר הוברר בחול למה צריך לברר בשבת מחדש בבחי' האכילה דקרבנות שנעשי' בשבת בדרך בירור ממש שהוא להעלות הטוב מן הרע להיות לריח ניחוח כו'.\n<b>אך</b> הנה לכאורה יש תירוץ לכל הנ\"ל ממה שמצינו שהי' בענין תיקון ובירור ממש אף למעלה מעה\"ד טו\"ר כמו בג\"ע קודם חטא דאדה\"ר שא' ויניחהו בג\"ע לעבדה ולשמרה<sup data-n=\"8270\">1241</sup>, והגם שלא הי' שום שמץ תערובות רע ופסולת בג\"ע כלל א' לעבדה בעבודה ותיקון כמו להשקות מים מנהר שיוצא מעדן להשקות הגן<sup data-n=\"8271\">1242</sup> ולזרוק כל אבן ולעשות תיקוני' לשמרה מכל רע כו'.",[["8259","1230","<b>מבשורה טובה שתדשן עצם</b>: משלי טו, ל."],["8260","1231","<b>כמו שהי' בריב\"ז</b>: גיטין נו, ב. ראה [הנחת כ\"ק אדה\"א ב]מאמרי אדה\"ז תקע\"א ס\"ע קיב ואילך: וכמו בריב\"ז שנתגדל רגלו מן בשורה טובה. ועד\"ז במאמרי אדה\"א דרושי חתונה ח\"א ע' מג. אבל ראה לעיל פ' בשלח קעח, ב. וש\"נ."],["8261","1232","<b>אש הגיהנם ששובת בשבת</b>: ראה סנהדרין סה, ב וברש\"י שם. לעיל שצב, ב. זהר יתרו פח, ב. מאמרי אדה\"א דברים ח\"ג ע' א'קיח. וש\"נ."],["8262","1233","<b>וסמבטיון יוכיח</b>: סנהדרין סה, ב."],["8263","1234","<b>השבת. . מעין דעוה\"ב</b>: ראה מכילתא תשא לא, יג. לעיל פ' שמות לג, ג הערה 315."],["8264","1235","<b>יו\"כ שאין בו או\"ש</b>: יומא רפ\"ח."],["8265","1236","<b>שאין בו או\"ש. . העוה\"ב</b>: ברכות יז, א."],["8266","1237","<b>באתרי' לאו אורחא למיכל</b>: ראה זהר פינחס רמא, סע\"ב."],["8267","1238","<b>א\"כ</b>: יב: אחותי כלה."],["8268","1239","<b>כולם</b>: יאיז: כלום."],["8269","1240","<b>א\"כ</b>: שם: אם."],["8270","1241","<b>ויניחהו בג\"ע לעבדה ולשמרה</b>: בראשית ב, טו."],["8271","1242","<b>מנהר שיוצא מעדן להשקות הגן</b>: בראשית ב, י."]]],[2300550822,"<b>אלא</b> צריך לומר שהי' עבודה ושמירה זו בבחי' הרוחני' הכל בלי צריך בירור בין טו\"ר כלל רק להוסיף אור ברוחניות האור והזיו האלקי (כמו המצו' שמוסיפים אור באצי'<sup data-n=\"8272\">1243</sup> וסומ\"ר דל\"ת למעלה שאין שם רע כלל אינו אלא להבדיל פנימי' מחיצוני' כו', וכך יהי' בימוהמ\"ש אחר הבירור דעה\"ד טו\"ר דאילנא דטו\"ר יתעבר<sup data-n=\"8273\">1245</sup> כו' ויהי' בהמ\"ק עם קרבנות וכמ\"ש הלכתא למשיחא<sup data-n=\"8274\">1246</sup> כו'<sup data-n=\"8275\">1244</sup> (וכמו שאו' והביאנו לציון עירך<sup data-n=\"8276\">1247</sup> כו') ושם דוקא נעשה כמצות רצונך<sup data-n=\"8277\">1248</sup> בקרבנות כו'. וצריך לומר שיהי' אופן הקרבנות אז בבחי' הרוחני' כמו שיהי' אז כל רמ\"ח מ\"ע ושס\"ה ל\"ת הכל בבירור הרוחני האלקי (כמו האבות שקיימו כל המצות ברוחניות<sup data-n=\"8278\">1249</sup> למעלה) כמ\"ש במ\"א, וכמו שמצינו שהקריב אדה\"ר קרבן פר ושור קודם החטא שלא הי' בו רע כלל וכמו שא' שור שהקריב אדה\"ר<sup data-n=\"8279\">1250</sup> כו' ([ו]כך יש קרבנות ברוחניות יותר במזבח העליון דאצי' משור דמרכבה<sup data-n=\"8280\">1251</sup> כו' וגם מנשמות דבריאה כידוע שמיכאל כה\"ר<sup data-n=\"8281\">1252</sup> מקריב נשמות ע\"ג המזבח<sup data-n=\"8282\">1253</sup> [כו'] וכה\"ג).\n<b>וכך</b> יוכל להיות ענין הקרבנות במעלה עליונה יותר מימוהמ\"ש והוא אף בעוה\"ב אחר תחה\"מ שלא יבוטלו הקרבנות גם אז מאחר שאז יהי' בהמ\"ק ויהי' נצחי' כמ\"ש תביא[י]מו כו' <span data-k=\"pg\">תרלג</span> ּ מכון לשבתך פעלת ה' וקאי בבהמ\"ק דלע\"ל<sup data-n=\"8283\">1254</sup> כידוע. ואעפ\"י שהעוה\"ב לא יהי' בו או\"ש כלל (למעלה ממדרג' דאדה\"ר בג\"ע הארץ שהי' אוכל מכל פרי העץ שבגן<sup data-n=\"8284\">1255</sup> ומבשר חי' ובהמ'<sup data-n=\"8285\">1256</sup> רק שהיו מזוככים וטהורים בתכלית מכל רע כו', כמו שיהי' בכה\"ג לאחר הבירור דעה\"ד טו\"ר בתכלית בימוהמ\"ש כידוע בענין אד\"ם אדם דו\"ד משי\"ח<sup data-n=\"8286\">1257</sup> כו', אבל בעוה\"ב אחר תחה\"מ לא יהיו<sup data-n=\"8287\">1258</sup> הגופי' וצומח<sup data-n=\"8288\">1259</sup> וחי כלל רק מאור וחיות אלקות (ועכ\"ז יהי' גם אז בחי' אכילה ברוחני' אלא שלא יהי' בדרך בירור כלל ונק' אכילה פנימי' (מאחר שיהי' להם גופים ממש (כפ\"ד הרמב\"ן<sup data-n=\"8289\">1260</sup> שכן האמת (כדוגמא דעצמות שהחי' יחזקאל שהגופי' בעו\"ב<sup data-n=\"8290\">1261</sup> ועצמות חיו מחיות [ה]רוח אלקי ממש כמ\"ש מד' רוחות בואי הרוח<sup data-n=\"8291\">1262</sup> כו' וכמ\"ש במ\"א) וכמו סעודת לויתן ושור הבר<sup data-n=\"8292\">1263</sup>",[["8272","1243","<b>המצו' שמוסיפים אור באצי'</b>: ראה פע\"ח בהקדמה. לעיל פ' בשלח קנו, ב. וש\"נ."],["8273","1245","<b>דאילנא דטו\"ר יתעבר</b>: ראה זהר (רע\"מ) נשא קכד, ב. קכה, א הובא באגה\"ק סכ\"ו. לעיל כב, ג. וש\"נ."],["8274","1246","<b>הלכתא למשיחא</b>: ראה סנהדרין נא, ב. לעיל פ' שמות כב, ג. הערה 931."],["8275","1244","<b>למעלה. . כו'</b>: יז: כו'."],["8276","1247","<b>והביאנו לציון עירך</b>: מוסף ליו\"ט."],["8277","1248","<b>ושם. . נעשה כמצות רצונך</b>: ראה גם לעיל פ' שמות כב, ג. וש\"נ."],["8278","1249","<b>האבות שקיימו. . ברוחניות</b>: ראה גם לעיל פ' וארא סג, ג ובהערה 171."],["8279","1250","<b>קודם החטא. . שור שהקריב אדה\"ר</b>: שבת כח, ב. ראה לעיל פ' שמות כב, ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680448\" data-slug=\"torat-chaim\" data-id=\"2300680448\">תו\"ח תולדות קס, ג</a> ובהערה 22."],["8280","1251","<b>קרבנות. . משור דמרכבה</b>: ראה גם לעיל פ' יתרו רס, ד."],["8281","1252","<b>שמיכאל כה\"ר</b>: ראה זהר (ס\"ת) לך פ, סע\"א ואילך. הנסמן במאמרי אדה\"א בראשית ע' נו."],["8282","1253","<b>שמיכאל. . מקריב נשמות ע\"ג המזבח</b>: ראה לעיל פ' שמות ה, א. וש\"נ."],["8283","1254","<b>ביהמ\"ק ויהי' נצחי'. . תביא[י]מו. . דלע\"ל</b>: בשלח טו, יז. ראה גם מאמרי אדה\"א בראשית ע' תכז. שמות ח\"א ע' רד. נ\"ך ע' רי."],["8284","1255","<b>דאדה\"ר. . שהי' אוכל מכל פרי העץ שבגן</b>: בראשית א, כט."],["8285","1256","<b>דאדה\"ר. . שהי' אוכל. . ומבשר חי' ובהמ'</b>: ראה סנהדרין נט, ב. תוד\"ה אכל שם נו, ב. עש\"מ מאמר חיקור דין ח\"ג פכ\"א. חידושי אגדות מהר\"ל לסנהדרין נט, ב. תורה שלמה בראשית א, כט אות תתח. לקמן תכט, ג."],["8286","1257","<b>אד\"ם אדם דו\"ד משי\"ח</b>: ראה רקאנטי בראשית א, כו. לעיל פ' שמות מז, ב ובהערה 157."],["8287","1258","<b>יהיו</b>: יאטז: יחיו."],["8288","1259","<b>וצומח</b>: שם: מצומח."],["8289","1260","<b>בעוה\"ב אחר תחה\"מ. . גופים. . הרמב\"ן</b>: בספר תורת האדם בסוף שער הגמול (כתבי הרמב\"ן ח\"ב ע' שט). ראה גם מאמרי אדה\"ז תק\"ע ע' כו. מאמרי אדה\"א ויקרא ח\"א ע' קלה. הנחות תקע\"ז ע' קכה. וש\"נ. שה\"א ס, א. ד\"ה ונגלה כבוד הוי' ש\"פ אחרי תשכ\"ב."],["8290","1261","<b>בעו\"ב</b>: בעור ובשר."],["8291","1262","<b>מד' רוחות בואי הרוח</b>: יחזקאל ז, יט. ראה גם לעיל פ' בשלח קסא, א. ביאוה\"ז קכא, סע\"א ואילך. מאמרי אדה\"א ויקרא שם."],["8292","1263","<b>סעודת לויתן ושור הבר</b>: ראה ב\"ב עד, ב. ויק\"ר פי\"ג, ג. לעיל פ' שמות ו, ד. וש\"נ."]]],[2300550823,"לצדיקי' לע\"ל שיהי' אז בסעודה זו<sup data-n=\"8293\">1265</sup> גם האבות אברהם ויצחק כו' שהרי א' אברהם לא רצה לברך<sup data-n=\"8294\">1264</sup> בהמ\"ז מפני שיצא ממנו כו', שבודאי כמו נשמות האבות שיקומו בגופי' לא יהי' אכילה זו בענין בירור והעלאה כלל ואף לא בהגשמה כלל וכלל. ולא כמזון דמן דגם שהי' שרשו מטל העליון (שיחי' בו המתים) מ\"מ נתגשם ודכו במדוכה כו' וגם לא כלחם פנג שתוציא הארץ גלוסקאות<sup data-n=\"8295\">1266</sup> שלימות שמורה על בחי' שלמות הבירור דעה\"ד אז שלא יצטרכו לזריעה וקצירה כו' כי הארץ עצמה תצמיח לחם אפוי כל צרכו (ואין זה פלא כ\"כ כי בג\"ע הארץ יש ג\"כ צומח כזה בלי זריעה וקצירה כו' כמ\"ש ויצמח ה'<sup data-n=\"8296\">1267</sup> כו', וכ\"ש בעדן עצמו שהוא ארץ החיים דעוה\"ב שעכ\"ז נק' ארץ שתצמיח כל צמח ותבואה בלי זריעה כלל כו'. ואעפ\"י שעוה\"ב אין בו או\"ש כלל, זהו באכילה גשמי' כלחם ובשר גשמי, אבל אכילה רוחני' כלויתן ושור הבר (ולחם פנג<sup data-n=\"8297\">1268</sup> כו') יהי' גם אז, כמו מזון הנשמות בגעה\"ע שלמעלה מגעה\"ת שזהו כמו העוה\"ב שלמעלה מימות המשיח<sup data-n=\"8298\">1269</sup> כמ\"ש במ\"א וד\"ל). אך הנה עכ\"ז אינו מובן כלל איך יהי' קרבנות גם לע\"ל שיהי' לריח ניחוח להוי' כקרבנות שהיו בבהמ\"ק מאחר שהקרבן הוא ענין העלאה בעילוי המדרגה שעולה מלמטה למעלה עכ\"פ, ובעוה\"ב אחר התחי' יהי' בו תכלית העילוי גם בגופי' כמו בנשמו' ויהי' גילוי אלקות למטה כמו למעלה ממש כידוע, ולמה צריך אז לקרבנות להעלות עולה וכה\"ג. וגם איך יתכן אז האכילה אף ברוחני' אחר שיחיו חיי עולם מחיות אלקות ממש כנ\"ל וד\"ל.\n[כג]<b> אך</b> הנה להבין כ\"ז, יש להקדים תחלה ענין א' בבחי' הבירורי' שיש ב' מיני בירורי'<sup data-n=\"8299\">1270</sup>, א' בבירורי' שמתברר ע\"י המשכה מכח העליון מלמעלה למטה שנק' בירור דאו\"י כמו שבחכ' דוקא אתברירו רפ\"ח ניצוצי' דתהו, שזה דוקא בח\"ע שיורד מגבוה לנמוך לברר מה שלמטה הימנו שהוא בבחי' החסדים דוקא שנק' או\"י שהולך מלמעלה למטה. וגם בזה יש ב' אופנים, הא' כמו שבא ונמשך הבירור הזה מכח העליון כמו שהוא בגילוי אור למטה כמו שהוא למעלה ממש (דאור החסד שבחכ' אינו מתעבה<sup data-n=\"8300\">1271</sup> ומתגשם בירידתו למטה (כירידת",[["8293","1265","<b>זו</b>: ויאיז: ליתא. יב: כבפנים."],["8294","1264","<b>סעודת. . לצדיקי'. . אברהם לא רצה לברך</b>: ראה פסחים קיט, ב."],["8295","1266","<b>שתוציא הארץ גלוסקאות</b>: ראה שבת ל, ב. לעיל פ' שמות כג, ב. וש\"נ."],["8296","1267","<b>ויצמח ה'</b>: בראשית ב, ט."],["8297","1268","<b>פנג</b>: ו: פנים. יאיביז: כבפנים."],["8298","1269","<b>העוה\"ב שלמעלה מימות המשיח</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' קמה. ע' רכ. דברים ח\"א ע' עא."],["8299","1270","<b>ב' מיני בירורי'</b>: ראה גם מאמרי אדה\"ז תקס\"ג כאן ע' רלח. תקס\"ד כאן ס\"ע עח ואילך. מאמרי אדה\"א שמות ח\"א ע' קפג. דברים ח\"א ע' ע. וש\"נ."],["8300","1271","<b>דאור החסד. . אינו מתעבה</b>: ראה גם לעיל פ' וארא פה, ג. וש\"נ. וראה גם המשך תרס\"ו ס\"ע שצו."]]],[2300550824,"המן <span data-k=\"pg\">1268</span> ּ מזונא דח\"ע למטה כמו שהוא למעלה, וכמו מוריד הטל דגם דמה שמתלבש בהגשמה כזרע גד לבן כו' לא נתמעט אורו כלל מכמו שהוא למעלה (וכטל שיחי' בו המתים למטה), וכירידת אור דחכ' דתורה למטה כמו למעלה בלי שינוי המהות כלל. ואעפ\"י שנתלבש האור דחכ' דתו' בעה\"ד טו\"ר לברר ולהבדיל בין טו\"ר, זהו כמו מצד האור שדוחה חושך ויאיר גם בחושך לפי שלגבי האור נדחה כל חושך ונראה ונתגלה כל גסות ופסולת אפי' דק ביותר כמו שמבררי' לפני האור הבהיר ביותר). והב' מה שמח\"ע יורד ומתלבש למטה בהעלם בלבוש של דבר המתברר שיהי' בו כח לעלות ולהתברר מצד עצמו עד שנראה כאלו הוא מתברר מאליו, ובאמת אין זה רק מכח העליון הימנו שהמשיך בו כח זה שיוכל להתברר מאליו ולעלות מחושך לאור (ובלשון הזהר זהו אתעדל\"ע שנמשך לעשות אתעדל\"ת<sup data-n=\"8301\">1272</sup> ונק' בע\"ח כח המעלה מ\"ן<sup data-n=\"8302\">1273</sup> כו'). וכהמשכת אה\"ר בהעלם לנש\"י לעורר בהם את האהבה או לעוררם בתשובה שלימה עד שנראה כאלו כח זה מתעורר מעצמם וכענין משכני כו' השיבנו ה' אליך<sup data-n=\"8303\">1274</sup> כו' (וכמשי\"ת). וכמו\"כ יש בחי' המשכת ח\"ע בח\"ת דבחי' המל' שיהי' בהם<sup data-n=\"8304\">1275</sup> כח מעצמה לעלות בבירור כו' וכמ\"ש בזהר ע\"פ חכמות בחוץ כו' ח\"ע דאתמשך בח\"ת<sup data-n=\"8305\">1276</sup> כו' והוא כח יריד[ה ו]המשכה עי\"ז<sup data-n=\"8306\">1277</sup> דתשב\"כ [ב]תשבע\"פ כמ\"ש תנו עוז לאלקי'<sup data-n=\"8307\">1278</sup> וכתי' חגרה בעוז מתני'<sup data-n=\"8308\">1279</sup> וכמ\"כ לבש ה' עוז<sup data-n=\"8309\">1280</sup> עוז והדר לבושה<sup data-n=\"8310\">1281</sup> וכה\"ג).\n<b>והמדרגה</b> הב' בבחי' הבירורי' שעולים מלמטלמ\"ע בבחי' או\"ח דוקא שהוא בבחי' הגבו' דוקא כידוע, והוא שנק' בשם העלאה דוקא דהיינו מה שעולה ונברר מתחתון שיוצא ונפשט מכל פסולת בבירור אחר בירור (כמו בזריעה וקצירה ודישה כו' עד שנעשה לחם ומן הלחם מתברר החיות הרוחני שבו ועולה ללב ומן הלב למוח וכה\"ג) (וזהו שנק' בירור<sup data-n=\"8311\">1282</sup> הטוב גם מן הרע ופסולת, שזהו בחי' בירור הפסולת דמה שיוכל למצוא טוב בהעלם ברע ופסולת יבררו, כמו שלוקחי' הפסולת של הכסף<sup data-n=\"8312\">1283</sup> שנשאר בהיתוך ובירור הראשון מבררי' אותו במצרף גס יותר ומוציאי' ממנו חלק[י] הכסף הטוב, וכן הפסולת הנשאר מזה הבירור שזהו גס יותר [י]בררו גם ממנו כסף טוב עד הפסולת הגס ביותר שיוזרק לחוץ שא\"א להוציא ממנו כסף טוב כלל. וזהו כמו הזדככות החומר ברע דרשעי' גמורי' ימצאו קצת טוב כמו ויתבררו ויתלבנו<sup data-n=\"8313\">1284</sup> כו'. משא\"כ בירור הראשון דאו\"י שמלמעלמ\"ט נק' בירור הנקי כמו שמברר",[["8301","1272","<b>אתעדל\"ע. . אתעדל\"ת</b>: נסמן לעיל פ' תרומה שטז, ג."],["8302","1273","<b>כח המעלה מ\"ן</b>: ראה גם לעיל פ' תצוה שמו, ב. וש\"נ."],["8303","1274","<b>השיבנו ה' אליך</b>: איכה ה, כא."],["8304","1275","<b>בהם</b>: יאיז: בה."],["8305","1276","<b>חכמות בחוץ. . בח\"ת</b>: משלי א, כ. ראה זהר תולדות קמא, ב. מאמרי אדה\"א בראשית ע' קכג. וש\"נ."],["8306","1277","<b>עי\"ז</b>: יאיז: דעו\"ז."],["8307","1278","<b>תנו עוז לאלקי'</b>: נסמן לעיל פ' משפטים רצב, א."],["8308","1279","<b>חגרה בעוז מתני'</b>: משלי לא, יז."],["8309","1280","<b>לבש ה' עוז</b>: תהלים צג, א."],["8310","1281","<b>עוז והדר לבושה</b>: משלי לא, כה."],["8311","1282","<b>בירור</b>: ויאיביז: ביעור."],["8312","1283","<b>שלוקחי' הפסולת של הכסף</b>: ראה גם המשך תרס\"ו ע' שצה. שע\"ת קיט, ב ובהערות 18-19."],["8313","1284","<b>ויתבררו ויתלבנו</b>: דניאל יב, י [ושם: יתבררו — נסמן לעיל ריד, ד]."]]],[2300550825,"לכסף הנקי מן הפסולת שבו בבירור והיתוך כמה פעמים עד שישאר הנקי בתכלית שזהו שנק' הזדככות הצורה גם מן הפסולת הדק ביותר, כמו מי יעלה כו' ובר לבב בתכלית כו' [ו]כענין וסביביו נשערה כו' אפי' כחוט השערה<sup data-n=\"8314\">1285</sup> וכשמים לא זכו בעיניו<sup data-n=\"8315\">1286</sup> וכה\"ג. וזהו בא בב' אופנים א[ם] מצד גילוי אור בהיר ומבהיק לצורה לזכך אותה שעי\"ז ממילא יבורר ויוצא ממנו גם כל פסולת דק שבדקות ביותר (כמו במ\"ת שהאיר ה' פב\"פ<sup data-n=\"8316\">1287</sup> ונזדככו ביותר עד שעכ\"ד פרחה כו' ונפסק מהם הרע דנה\"ק<sup data-n=\"8317\">1288</sup> לגמרי כידוע <span data-k=\"pg\">תרלד</span> ּ וכה\"ג בימוהמ\"ש ועוה\"ב). או שיבא אופן בירור זה כמו במצרף לכסף נקי והן כמו יסורים של אהבה לצ\"ג וכה\"ג. או שיערה עלינו רוח ממרום לעורר את האהבה והתשוקה להתברר מכל סיג ופסולת בצורה דנשמה. ואמנם [גם] מה שיוכל להתברר הטוב מן הרע דחומר הגוף עי\"ז כנ\"ל זהו אתעדל\"ע שעושה לאתעדל\"ת להיות בו כח להתברר מעצמו ה\"ז בירור הטוב מן הרע בבחי' או\"ח אחר שנמשך בו כח העליון מלמעלה (ולא כאור שמאיר גם לחושך הנ\"ל אלא שמתעלם בלבוש המתברר שיוכל להתברר מכח עצמו ממש (כמשי\"ת).\n<b>וגם</b> בבחי' בירור זה דאו\"ח מלמטלמ\"ע יש ב' מדרגות, א' שנק' בירור שהוא מה שיוצא ונבדל ונפרד הטוב מן הרע ופסולת לבד בכמה מיני בירורי' זא\"ז, דמה שיוצא הטוב מן הפסולת בבירור הא' חוזרים ומבררי' אותו פעם ב' ונבדל ממנו גם הפסולת הדק עד בירור האחרון שיוצא נקי לגמרי. וכמו תש\"ת בבירור הרע הגמור חוזר ומתברר גם מפסולת ורע דק ע\"ד<sup data-n=\"8318\">1289</sup> תש\"ע שנק' בר לבב לגמרי כו', וכהזדככות החומר שיהי' בדורו של משיח (וכמו שהי' בגופו של אדה\"ר קודם החטא בעה\"ד [דעקבו<sup data-n=\"8319\">1290</sup> ] כו'). ונמצא דכמו שע\"י בירור דאו\"י בהזדככות הצורה נבדל ממנה כל פסולת דק עד שיברר גם לחומר הגס שיובדל ממנו כל פסולת (כמו שהי' במ\"ת שגם הגופי' שלהם נזדככו בתכלית כנ\"ל). והב' הוא שנק' העלאה בעילוי אחר עילוי עד אין שיעור למעלה ולא [ב]ענין בירור כלל לא בצורה ולא בחומר רק ענין העלאה שעולה כמו שהוא ממדרגה למדרגה העליונה יותר, וכמו עלי' הנשמ' בג\"ע מדי שבת מגעה\"ת לגעה\"ע ועד למעלה מעלה כמו הנשמות הגבוהות כאבות ומשה ואהרן שעולים גם עתה בעילוי אחר עילוי למעלה עד אין שיעור כמו שאו' וקדושי' בכ\"י<sup data-n=\"8320\">1291</sup> יהללוך סלה בלי הפסק<sup data-n=\"8321\">1292</sup> כלל, שאין בזה ענין בירור כלל רק בחי'",[["8314","1285","<b>וסביביו נשערה. . השערה</b>: תהלים נ, ג. יבמות קכא, ב. ראה גם מאמרי אדה\"א קונטרסים ע' שג. וש\"נ. לעיל פ' בשלח רטו, א."],["8315","1286","<b>וכשמים לא זכו בעיניו</b>: איוב טו, טו."],["8316","1287","<b>במ\"ת. . פב\"פ</b>: ואתחנן ה, ד."],["8317","1288","<b>דנה\"ק</b>: יב: דנחה\"ק דנחש הקדמוני. ויאיז: דנה\"ב. וראה סה\"מ תרס\"ו ע' שצו: וכמו במ\"ת. . כי נפסקה זוהמתן. נפסק מהם הרע דנה\"ק לגמרי."],["8318","1289","<b>ע\"ד</b>: ויאיב: עד."],["8319","1290","<b>אדה\"ר. . דעקבו</b>: ראה ויק\"ר פ\"כ, ב. זהר (רע\"מ) קדושים פג, ב. לעיל פ' שמות מ, ב הערה 137."],["8320","1291","<b>כאבות ומשה ואהרן. . וקדושי' בכ\"י</b>: ראה גם לעיל פ' שמות ד, ג. וש\"נ."],["8321","1292","<b>וקדושים בכ\"י יהללוך סלה בלי הפסק</b>: ברכת אתה קדוש. ערובין נד, א."]]],[2300550826,"העלאה מדרגא לדרגא כמו ילכו מחיל אל חיל כו' (ועכ\"ז נק' בירור שני ושלישי (כמשי\"ת).\n<b>והנה</b> להבין ביאור כ\"ז בפרטות, הנה תחלה י\"ל מה שבא כח המשכה מעליון לתחתון שיוכל להתברר ולעלות כנ\"ל, הנה יש בזה ב' משלים<sup data-n=\"8322\">1293</sup>, הא' כמו התינוק הקטן שא\"י לילך מכח עצמו אבל ע\"י הגדול כאביו שעומד מאחוריו ודוחפו שמכח זה ילך ונדמה לתינוק שהולך מכח עצמו, שזהו בבחי' ההעלם שבא כח העליון למטה לעשות בו כח הילוך במה שעוזרו בדחיפה מאחוריו לבד כו'. וכך יש עזר וסיוע מלמעלה בהעלם מאחוריו של הנשמה באדם שיתעורר לילך בדרכי הטוב ונדמה לו שהולך מכח עצמו כו', ובאמת ה\"ז רק מכח הא\"מ העליון כענין הבא לטהר הרבה מסייעים אותו<sup data-n=\"8323\">1294</sup> מלמעלה, שסיוע ועזר זה בא מלמעלה בבחי' ההעלם בלתי נודע ממי יבוא לו כח התעוררו' זו כו' וכן יערה עלינו רוח ממרום בהעלם (כמ\"ש במ\"א בפי' אם בשבט יכהו<sup data-n=\"8324\">1295</sup> בשבט דאו\"מ כו'). וכן מ\"ש אך בצלם יתהלך איש בצלם דמקיף דמזלי' שמעוררו בהעלם מחמת הב\"ק שמכריז למעלה<sup data-n=\"8325\">1296</sup> כו' וכה\"ג, וזהו כשבא לטהר או לקדש עצמו<sup data-n=\"8326\">1297</sup> <span data-k=\"pg\">1270</span> ּ מעט שמסייעי' אותו כו'. אבל יש עוד עזר מלמעלה שבא בגילוי גמור למטה והוא, כשאין כח ההילוך כלל בקטן או שנופל לארץ ולא יוכל לקום מכח עצמו שיבא הגדול כאביו ויקימנו מנפילתו ומוליכו על רגליו כו', או שאם קטן הוא ביותר שא\"י לילך כלל ברגליו ויגביהנו האב על כתיפו וישאנו כאשר ישא האומן את היונק כו' שאז צריך האב להשפיל א\"ע למקום הנמוך לעלות את בנו על כתפו כו'<sup data-n=\"8327\">1298</sup> (וכמו ביצ\"מ במסעות שבמדבר שא' ישאהו על אברתו<sup data-n=\"8328\">1299</sup> כו' וא' כאשר ישא האומן<sup data-n=\"8329\">1300</sup> כו' וכתי' אנכי תרגלתי לאפרים קחם על זרועותי<sup data-n=\"8330\">1301</sup> כו', שתרגלתי היינו שהשפיל א\"ע למקום ומדרג' דקטנות דנש\"י כמו שהן למטה ממש בבחי' רגלי השכינה<sup data-n=\"8331\">1302</sup> כמ\"ש והארץ הדום רגלי<sup data-n=\"8332\">1303</sup> כו' והעלם למעלה מזרועותיו הגבה למעלה, שזהו כננס שעומד ע\"ג כתפיו של הענק<sup data-n=\"8333\">1304</sup> שרואה למרחוק ביותר והולך בכח וגבורה גדולה שאין זה מכח עצמו כלל וכלל רק מפני שהוגבה למעלה עד ראש הגדול יכול לראות כמוהו ולילך בדרכ[י]ו ממש כו'. וכך<sup data-n=\"8334\">1305</sup> הי' סיבת כח ההילוך בדרכי ה' בתו\"מ ואוי\"ר בכל עילוי המדרגות שהי' להם במדבר כמו שניזוני'",[["8322","1293","<b>ב' משלים</b>: ויאיביז: משלים. להבא לקמן ראה גם המשך תרס\"ו ע' שצח — תד בהוספות ושינויים."],["8323","1294","<b>הבא לטהר. . מסייעים אותו</b>: ראה יומא לח, סע\"ב. מאמרי אדה\"א דברים ח\"ד ע' א'תקב (ובהנסמן בריש המאמר שם). נ\"ך ע' שמח ואילך (ובהנסמן שם). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680307\" data-slug=\"torat-chaim\" data-id=\"2300680307\">תו\"ח תולדות קנד, א</a>."],["8324","1295","<b>אם בשבט יכהו</b>: ראה משפטים כא, כ. לעיל פ' משפטים רצג, א. וש\"נ."],["8325","1296","<b>הב\"ק שמכריז למעלה</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ר\"ע תרב וע' תתלג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380334\" data-slug=\"likkutei-torah\" data-id=\"4001380334\">לקו\"ת במדבר ו, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380497\" data-slug=\"likkutei-torah\" data-id=\"4001380497\">שלח מו, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380864\" data-slug=\"likkutei-torah\" data-id=\"4001380864\">תצא לו, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381225\" data-slug=\"likkutei-torah\" data-id=\"4001381225\">שה\"ש כד, א</a> (מכתב י\"ב טבת תשי\"ב נדפס באג\"ק ח\"ה ע' קלד)."],["8326","1297","<b>כשבא. . לקדש עצמו</b>: ראה יומא לט, א."],["8327","1298","<b>כו'</b>: ראה המשך תרס\"ו כאן ע' ת."],["8328","1299","<b>ישאהו על אברתו</b>: האזינו לב, יא."],["8329","1300","<b>כאשר ישא האומן</b>: בהעלותך יא, יב."],["8330","1301","<b>אנכי תרגלתי. . זרועותי</b>: הושע יא, ג [ושם: ואנכי (וכ\"ה בתרס\"ו כאן ע' ת). . זרועתיו — ראה הנסמן לעיל פ' בא פט, ב הערה 114]."],["8331","1302","<b>רגלי השכינה</b>: נסמן לעיל פ' תצוה שכח, א."],["8332","1303","<b>והארץ הדום רגלי</b>: ישעי' סו, א."],["8333","1304","<b>כננס. . של הענק</b>: ראה גם לעיל פ' בא קל, ב. וש\"נ."],["8334","1305","<b>וכך</b>: ויאיז: וגם. יב: ובהמשך תרס\"ו כאן ע' ת כבפנים."]]],[2300550827,"במזון דמן והיו זכאי'<sup data-n=\"8335\">1306</sup> והי' ראי' שכלם והשגתם בכבוד דהוי' שנגלה להם פב\"פ כמו במ\"ת וכה\"ג, הכל לא מכח עצמם כלל רק כאשר ישא האומן את היונק שמגביהו על כתפו כו' ו[לכך] ניצלו מגקה\"ט דנחש שרף ועקרב<sup data-n=\"8336\">1307</sup> שבמדבר הגדול והנורא<sup data-n=\"8337\">1308</sup> כו' והכניעו אותם במסעות שלהם כמ\"ש משה קומה הוי' ויפוצו<sup data-n=\"8338\">1309</sup> כו' (כמ\"ש במ\"א). וגם יש עד\"ז בבחי' או\"י ביריד' דוקא מגבוה לנמוך כמו בזמן הגלות שאל מסתתר בתכלית כידוע [ו]עכ\"ז עוזר ומושיע לנש\"י בהעלם אף שמחיצה ש\"ב מפסקת<sup data-n=\"8339\">1310</sup> כו', כמ\"ש<sup data-n=\"8340\">1311</sup> משגיח מן החלונו\"ת<sup data-n=\"8341\">1312</sup> מציץ כו' לפי שעומד אחר כתלינ\"ו ממש עד שבכל צרתם לו צר<sup data-n=\"8342\">1313</sup> ממש כו'). וכן בנפילת כנ\"י למטה ממש שיקימנה כמ\"ש מקימי מעפר דל<sup data-n=\"8343\">1314</sup> שהיא השכינה שבגלות כו' שהקמה זו בהעלם בלי נודע לנופל שקדמה<sup data-n=\"8344\">1315</sup> לו שקם מעצמו כו'. וכן בהתעוררות תשובה בעי\"ת מצד שהוא ית' מקרוב ממש למטה כמ\"ש קראוהו בהיותו קרוב<sup data-n=\"8345\">1316</sup> כעומד אחר כתלינו הנ\"ל וממילא ימשוך לבו<sup data-n=\"8346\">1317</sup> כל א' שיתעורר בתשו' שלימה שזהו ג\"כ בהעלם כמו שהי' מקרוב ממש בגילוי במ\"ת שעכ\"ד כו'. וכך יש ג\"כ בשמירה דאו\"מ העליון ששומר למשתמר בלי נודע לו מאין ישתמר שנק' שמירה בהעלם, וכמו על גוזליו ירחף<sup data-n=\"8347\">1318</sup> כו' בזמן הגלות שיפרוס סוכת שלומו ויגן בהעלם לבטל כל גזירה כו' וכמו לא ינום כו' שומר ישראל<sup data-n=\"8348\">1319</sup> כידוע.\n<b>והנה</b> לפי המובן ממשל הנ\"ל בהגבהת האב לתינוק על כתיפו הרי יש תחלה ירידה להשפיל א\"ע למטה כמו אנכי תרגלתי לאפרים ואח\"כ ההעלאה קחם על כו' כאשר ישא האומן כו', וכך יובן שיש ב' אופנים בבחי' כח הבירור שנמשך מעליון לתחתון ביותר הא' מה שיורד ונשפל מגבוה לנמוך להתלבש בלבוש של המתברר דוקא וליתן בו כח ועוז בהעלם דוקא שיוכל להתברר [ו]לעלות מכח עצמו כנ\"ל. ויובן <span data-k=\"pg\">תרלה</span> ּ זה עד\"מ אחר כמו הרב שמשפיע שכל וסברא לתלמיד הקטן שצריך להשפיל א\"ע להתלבש במהות ואופן השכל והשגה המצומצמת של התלמיד להסביר לו אופן אמיתי' אור השכל וסברא זו ולהעמידו על בוריו לפי אופן השגתו המצומצם, שמלביש הדבר במשלים ודמיונות כפי השגתו וענינו בקטנות הדעת עד שמעצמו וכח שכלו לא יטה ימין ושמאל מאמיתי' השכל והדין וההלכה שיוצא",[["8335","1306","<b>והיו זכאי'</b>: ויאיביז: ליתא."],["8336","1307","<b>מגקה\"ט דנחש שרף ועקרב</b>: ראה גם לעיל פ' בשלח קלז, ד. וש\"נ."],["8337","1308","<b>דנחש. . שבמדבר הגדול והנורא</b>: עקב ח, טו."],["8338","1309","<b>קומה הוי' ויפוצו</b>: בהעלותך י, לה. ראה גם מאמרי אדה\"ז תקע\"א ע' רכז. לקו\"ת ד\"ה אלה מסעי הב' והג'. מאמרי אדה\"א במדבר ח\"ה ע' א'תתעג."],["8339","1310","<b>שמחיצה ש\"ב מפסקת</b>: נסמן לעיל פ' תצוה שנו, ב."],["8340","1311","<b>כמ\"ש</b>: בתרס\"ו כאן: מ\"מ כתי'."],["8341","1312","<b>משגיח מן החלונו\"ת</b>: שה\"ש ב, ט."],["8342","1313","<b>שבכל צרתם לו צר</b>: ישעי' סג, ט. ראה לעיל פ' וארא נא, ד."],["8343","1314","<b>מקימי מעפר דל</b>: תהלים קיג, ז. ראה גם לעיל פ' וארא סד, ב. וש\"נ."],["8344","1315","<b>שקדמה</b>: יאיז: שנדמה."],["8345","1316","<b>בעי\"ת. . קראוהו בהיותו קרוב</b>: ישעי' נה, ו. ר\"ה יח, א."],["8346","1317","<b>לבו</b>: יאיז: לב."],["8347","1318","<b>על גוזליו ירחף</b>: האזינו לב, יא."],["8348","1319","<b>לא ינום. . ישראל</b>: תהלים קכא, ד."]]],[2300550828,"מסברא [זו]. וכמו שא' לעולם ישנה אדם לתלמידו דרך קצרה<sup data-n=\"8349\">1320</sup>, שהכוונה הוא שאם יאריך לו בדברי עומק השכל בפלפולי' שונים לא יוכל לקבל אמיתי' הדבר מתוך ריבוי ההסבר באופנים שונים עד שיוכל לנטות מדרך נקודת האמת מהיפוך להיפוך, כמו שא' הזהרו בדבריכם שלא ישתו התלמידים<sup data-n=\"8350\">1321</sup> כו' שלא יקלטו הפסולת והשקר<sup data-n=\"8351\">1322</sup> וטעות כו'. אלא ילמד לו דרך קצרה שבדבורים הקצרים הללו יכילו כל אור נקוד' האמת של ההלכה כמו בדברים קצרים שבמשנה שכוללי' כל הפרטים בהעלם באופן שלא יוכל לנטות מנקוד' האמת, ולא מצד השכלתו וסברתו, אלא מכח הגנוז בהעלם [ב]תוך דברי הקיצור ותמצית ששונה לו שבהם יתנהג וילך ביושר ולא יוכל לנטות ימין ושמאל. ואע\"פ שאינו משיג ומבין הטעם למה לא יהי' השכל וסברא להיפוך אלא רק מצד אמיתי' הדבר שנמסר לו בדברים קצרים וכוללי' הללו לא יטה ימין ושמאל. ונמצא סיבת עמידתו על האמת ויושר בהשכלה זו לא ידע התלמיד מאין בא לו זאת ועכ\"ז נדמה לו שמכח עצמו' שכלו מבין ומשיג האמת כשלומד הקיצור, ובאמת זהו רק מכח שפע זאת התמצית שהשפיע הרב בדברים קצרים הללו שמחמתם יבא על האמת מכח עצמו (וכמו שהי' הרב מנהיגו ומנהלו מעט מעט בדברים ברורי' בטעמם באמיתי' ההשכלה מן הצד עד שממילא ישכיל התלמיד ויעמוד על אמיתי' השכל באופן שלא ידע וירגיש כלל סיבת עמידתו על האמת כי נעלם מן התלמיד עומק הכוונה בכל מה שמסבב לו הרב בדברים הברורי' לרב שמהם ועל ידם יבא אור השכל וההלכה לאמיתתו כו') (וכמו המשנה שמדברת בדברים קצרים כוללי' כל הפרטי' שמבארי' ומפלפלי' בתלמוד, וכל מה שיקשו קושיות בתלמוד לנגד האמת והדין שבמשנה לא יוכל להתקבל מצד שלא יוסבל בדברי המשנה ששנה רבי בדרך קצרה<sup data-n=\"8352\">1323</sup> להעמיד הכל על האמת ונעלם בקיצור זה כל מה שיוצא אחר העיון הגדול בפלפול רב תוכן האמת לאמיתתו כו'. כמו שא' בזוגו' שנק' אשכולו'<sup data-n=\"8353\">1324</sup> איש שהכל בו<sup data-n=\"8354\">1325</sup> שהיו מכוונין בקיצור ותמצית לאמיתי' ההלכה בכל פרטי' בלא פלפול<sup data-n=\"8355\">1326</sup> ויגיעה בעיון כלל, ואח\"כ בחורבן הב\"ש נתרבו מחלוקת והוצרך לבא בירור זה [דאו\"י] ע\"י פלפול גדול כהויות דאביי ורבא<sup data-n=\"8356\">1327</sup> (בבחי' או\"ח) (ויובן מזה בדרך כלל ג\"כ עד\"ז בהפרש שבין תשב\"כ לתשבע\"פ בכלל דתושב\"כ בחי' משפיע ותשבע\"פ בחי' מקבל מתושב\"כ כידוע ונק' פנים מאירות באותיות דתשב\"כ שנמשך ומאיר לתושבע\"פ שנק' פנים מסבירות<sup data-n=\"8357\">1328</sup> ). ואע\"פ",[["8349","1320","<b>לעולם. . דרך קצרה</b>: פסחים ג, ב. ראה גם הנסמן לעיל פ' שמות מח, א הערה 192."],["8350","1321","<b>הזהרו בדבריכם שלא ישתו התלמידים</b>: ע\"פ אבות פ\"א, מי\"א."],["8351","1322","<b>והשקר</b>: ויאיז: מהשגה. יב: ובתרס\"ו כאן ע' תא כבפנים."],["8352","1323","<b>המשנה ששנה רבי בדרך קצרה</b>: ראה הקדמת הרמב\"ם לפיה\"מ ד\"ה אחר כן ראה."],["8353","1324","<b>בזוגו' שנק' אשכולו'</b>: סוטה מז, א (במשנה)."],["8354","1325","<b>אשכולו' איש שהכל בו</b>: סוטה מז, סע\"ב."],["8355","1326","<b>בזוגו'. . בלא פלפול</b>: ראה גם לעיל פ' שמות טו, ב. וש\"נ."],["8356","1327","<b>כהויות דאביי ורבא</b>: סוכה כח, א."],["8357","1328","<b>פנים מאירות. . דתשב\"כ. . לתושבע\"פ שנק' פנים מסבירות</b>: ראה גם לעיל פ' שמות יא, ב. וש\"נ."]]],[2300550829,"ש[ב]תשבע\"פ נתרבו הדינים וההלכות בכפלי כפליים לאין שיעור ובתשב\"כ נכתב הכל בקיצור כמו וקשרתם כו' נתרבה כל ה' תפילין<sup data-n=\"8358\">1329</sup> וכן <span data-k=\"pg\">1272</span> ּ בסוכות תשבו כל מס' סוכה<sup data-n=\"8359\">1330</sup> וכה\"ג כידוע, ה\"ז כמשל הנ\"ל בשונה לתלמיד דרך קצרה [כ]משנה לגבי התלמוד כנ\"ל שבדברים הקצרים שבתשב\"כ נכלל כל נקודת אור האמת דכל ה' סוכה ותפילין במעט תיבות הללו, עד שכל מה שמלמדים בתשבע\"פ [מ]הם כל פרטי הדינים וההלכות בטעמים ופלפולים רבים לא יצא חוץ<sup data-n=\"8360\">1331</sup> לנקודת האמת רק מצד הכח דח\"ע דמשפיע שנמשך באותיות דתשב\"כ בקיצור ותמצית. ואע\"פ שנראה לחכמי התשבע\"פ שמחדשים דינים רבים מכח עצמם, אבל באמת הכל הוא מהעלם דחכמה דאותיות<sup data-n=\"8361\">1332</sup> דתשב\"כ רק שיצא לגילוי מן ההעלם בתשבע\"פ שנק' פנים מסבירות שיהי' בהם כח לברר מכח עצמ[ן] בלי נטי' ימין ושמאל מכפי האמת שבתשב\"כ דוקא וזהו שהמברר מתלבש בהעלם לפ\"ע המתברר שיוכל לברר מכח עצמו כנ\"ל וד\"ל).\n[כד]<b> והנה</b> יש עוד אופן אחר במשל הנ\"ל בשפע הרב לתלמיד שיובן מזה ענין הנ\"ל במה שמכח [ה]משפיע יומשך למקבל שיוכל לברר עצמו כו', והוא כמו בעומק שכל וסבר\"א שמשפיע הרב לתלמיד שכדי שלא יפול התלמיד באיזה טעות דק ביותר שמחמתו יטה מדרך האמת ולא ינצל ממנו לפ\"ע כלי קבלתו המצומצם, אז[י] משפיע לתלמיד כח ושפע חכמה יתירה שנוספת על קבלת התלמיד עד שמחמתה יוכל התלמיד להרגיש בכח חכמתו בעצמו על הטעות הדק ויוצא לאור האמת מכל המבוכה ובלבול שיהי' לו בזה, עד שתהי' הסברא והשכל זך ונקי וברור מכל סיג לתכלית אמיתתו כמו שהי' אצל הרב המשפיע בלי נטי' לימין ושמאל (וכמו ביהושע שא' איש אשר רוח בו<sup data-n=\"8362\">1333</sup> רוחו של משה שסמך ידיו על[יו]<sup data-n=\"8363\">1334</sup> שיוכל מכח חכמת עצמו לברר כל ספק לאור האמת [מפני שקיבל אור האמת] במעלה יתירה על עצם חכמת\"ו) וכמו<sup data-n=\"8364\">1335</sup> פני לבנה<sup data-n=\"8365\">1336</sup> שמקבלת מאור השמש שאז תאיר אור עצמה<sup data-n=\"8366\">1337</sup> וכאשה שתקבל כח המוליד ממ\"ד שאז תזריע ותלד מכח המ\"ן שלה<sup data-n=\"8367\">1338</sup> (וזהו מה שהמקבל יוכל בכח עצמו לברר שהוא בא<sup data-n=\"8368\">1339</sup> מכח המשפיע שהשפיע ונתן בו כחו<sup data-n=\"8369\">1340</sup> שיוכל לבא מעצמו על בירור אמיתית הדבר (ודוגמא לזה הוא מה שאמר דלא קאים אינש אדעתי' דרבי' עד מ' שנין<sup data-n=\"8370\">1341</sup> דהיינו שקודם מ' שנין אין התלמיד קאי אדעתי' דרבי' ממש, שאע\"פ שמבין ומשיג בכי טוב לדבר השכל ו[ה]חכמה",[["8358","1329","<b>וקשרתם. . כל ה' תפילין</b>: ואתחנן ו, ח. עקב יא, יח. ראה גם מאמרי אדה\"א בראשית ע' תקנט. דברים ח\"ד ע' א'תנד. תו\"ח ח\"ש קלח, ד. ויצא קעג, ג. וישלח קצד, ג."],["8359","1330","<b>בסוכות תשבו כל מס' סוכה</b>: אמור כג, מב. ראה גם מאמרי אדה\"א בראשית ע' תקי, וש\"נ. וראה גם לקמן תלט, ד."],["8360","1331","<b>חוץ</b>: ויאיז: סוף. יב: כבפנים."],["8361","1332","<b>דאותיות</b>: שם: ליתא."],["8362","1333","<b>איש אשר רוח בו</b>: פינחס כז, יח."],["8363","1334","<b>משה שסמך ידיו על[יו]</b>: פינחס שם, כג."],["8364","1335","<b>חכמת\"ו) וכמו</b>: יאיביז: חכמתו (וכמו."],["8365","1336","<b>ביהושע. . פני לבנה</b>: ב\"ב עה, א."],["8366","1337","<b>לבנה שמקבלת. . תאיר אור עצמה</b>: ראה גם שע\"ת יח, ב ובהערה 14."],["8367","1338","<b>וכאשה שתקבל. . ותלד מכח המ\"ן שלה</b>: ראה הנסמן בסמוך בהערה 1346."],["8368","1339","<b>בא</b>: ויאיז: ליתא. יב: כבפנים."],["8369","1340","<b>שהשפיע. . כחו</b>: ויאיז: שהמשפיע נותן בו כח. יב: כבפנים."],["8370","1341","<b>דלא קאים. . מ' שנין</b>: ראה ע\"ז ה, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תמד. וש\"נ. הנחות תקע\"ז ע' קמג. וש\"נ. שער האמונה צב, ב."]]],[2300550830,"שלמד וקיבל מרבו זהו רק חיצוני' השכל כמו שמושג במושכל והשקפה<sup data-n=\"8371\">1342</sup> ראשונה ויוכל ליפול בטעות דק שיוצא מן נקוד' אמיתתו. אבל<sup data-n=\"8372\">1343</sup> לאחר מ' שני' הוא דקאי אדעתי' דרבי' כמו שהוא בעומק של השכל הזה שגנוז ונעלם בדברים הללו שלא קם התלמיד ולא עמד על העומק הזה שהי' בדעת רבו בשפע זו, שאחר דקאים אדעתי' דרבי' יוכל לבא מכח עצמ[ו]' חכמתו לברר ולהוציא לאור כל טעות דק עד שיהי' השכל זך ובהיר לעומקו כמו שהי' במשפיע והרבה יותר מזה כמו (ויהי' נא פי שנ[י]ם ברוחך<sup data-n=\"8373\">1344</sup> כו') (וכמו שא' דבינה יתירה ניתנה באשה כו', וראי' מהעיבור בט\"ח שמגדלת הולד ברמ\"ח אברי' בריבוי<sup data-n=\"8374\">1345</sup> גדול ובהבדלה בין פנימי' לחיצוני', ובהגדלה המוחי' ביניקה <span data-k=\"pg\">תרלו</span> ּ וגדלות. וגם בעיקר התולדה א' אשה כי תזריע<sup data-n=\"8375\">1346</sup> במ\"ן שלה דוקא וילדה כו' רק שניתן לה כח המוליד הזה ממ\"ד, אבל בטפה דדכורא לא הי' רק בהעלם [גדול] רק כחות הרוחניות דולד ונעשה חידוש ממש במ\"ן דנוק' בציור כל האברים, ולא מהעלם לגילוי בלבד כו' שהרי טפת הדכר נסרחת<sup data-n=\"8376\">1347</sup> ונרקב[ת כ]גרעין הנזרע שנרקב<sup data-n=\"8377\">1348</sup> והי' כלא הי' ממש ואח\"כ בצמיחה צומח חטים חדשות לגמרי, וכך הולד שנוצר בבטן הנוק' אחר הזריעה דמ\"ד בא בחידוש גמור ובריבוי גדול כו' (וכן הלבנה תאיר אור עצמה דוקא על הארץ אחר שקיבלה אור השמש, ומ\"ש בזהר דסיהרא לית לה מגרמה כלום היינו שאין לה כח המשפיע להאיר אור בלתי<sup data-n=\"8378\">1349</sup> קבלתה בעצמה אור השמש תחלה כו' כמ\"ש במ\"א.\n<b>ולזאת</b> יובן שיש מעלה יתירה בתשבע\"פ שמקבל מתשב\"כ אע\"פ שכל מה שיש בכח חכמי תושבע\"פ לברר בעה\"ד טו\"ר בדינים והלכות דכשר פסול בפרטי פרטות זהו הכל מכח דח\"ע דתשב\"כ שהוא בא בקיצור ותמצית כנ\"ל, אין זה נק' מן ההעלם לגילוי בלבד שאין כל חדש בזה כלל. אלא זהו רק כמו טפת מ\"ד שנותן כח במ\"ן שתזריע שתלד מכח עצמה דוקא כנ\"ל, כך כשמגיע האור דאותיות דתשב\"כ בתשבע\"פ [יש בה] מכח עצמה דוקא להיות התחדשות ממש בהלכות ודינים רבים הרבה יותר ממה שנמשך מתשב\"כ. וז\"ש דבינה יתירה ניתנה באשה יתירה על המשפיע וכמו שלע\"ל אמר א\"ח עט\"ב<sup data-n=\"8379\">1350</sup> וכצמיח' החטים בריבוי יותר מהזריעה לאין שיעור כלל ובחידוש גמור כנ\"ל וד\"ל (ואע\"פ שא' חכמות בחוץ ח\"ע דאתמשך בח\"ת כו' וכן תנו עוז לאלקי' שהיא ח\"ת בחי' ב\"ן דתשבע\"פ, גם זה אמת דכח ועוז נמשך לח\"ת מח\"ע אבל בהגיע",[["8371","1342","<b>והשקפה</b>: יא: והשגה."],["8372","1343","<b>אבל</b>: יאיביז: אך."],["8373","1344","<b>ויהי' נא פי שנ[י]ם ברוחך</b>: מל\"ב ב, ט [ושם: ויהי — וכ\"ה ביב]. ראה המשך תרס\"ו כאן ע' תג."],["8374","1345","<b>ברמ\"ח אברי' בריבוי</b>: יאיז: ברחם בריבוי אברי'. יב: ברח\"ם אברי' בריבוי."],["8375","1346","<b>אשה כי תזריע</b>: תזריע יב, ב. ראה גם לעיל פ' שמות ט, ג. וש\"נ."],["8376","1347","<b>טפת הדכר נסרחת</b>: ראה גם לעיל פ' תצוה שכ, ג. וש\"נ."],["8377","1348","<b>כ]גרעין הנזרע שנרקב</b>: ראה אגה\"ק ס\"ח (קיג, א). לעיל פ' שמות ב, ג. וש\"נ."],["8378","1349","<b>בלתי</b>: ויביז: בלעדי. יא: בלעדה."],["8379","1350","<b>א\"ח עט\"ב</b>: משלי יב, ד."]]],[2300550831,"הכח ועוז לח\"ת בחי' מקבל יש בה יתרון אור וכח רב מן המשפיע כמו הצמיחה בריבוי דגם שא\"א בלי זריעה [ו]עכ\"ז הריבוי בא בחידוש גמור מכח הארץ עצמ[ה] כמו במ\"ן דנוק' כנ\"ל וד\"ל. וכך הוא בנש\"י שנק' ג\"כ בחי' מקבל כאשה כידוע שמקבלים אור הוי' בנשמתם ונק' ברוכי הוי'<sup data-n=\"8380\">1351</sup> או נר הוי' כו' ומתבררים בנפשם מכל סיג ופסולת בחכ' שבנה\"א דבחכ' אתברירו כמו בק\"ש במס\"נ באחד ע\"י השג[ה] והתבוננו' ביחו\"ע ויחו\"ת כידוע. אך מאין יש להם כח ועוז לעמוד בנפשם האלקי' לבא לידי בירור זה עד שבאי' לציור שלם ברמ\"ח אברים שהן רמ\"ח מ\"ע<sup data-n=\"8381\">1352</sup> ובהבדלה בין פנימי' לחיצוני' בסומ\"ר וע\"ט ובגדלות המוחין ומדות דאוי\"ר שכלי' כו', הכל הוא בא מכח חכ' עילאה דאצי' שמשם שרש הראשון לתולדות הנשמות כידוע. ואמנם עכ\"ז עיקר הכח הזה [הוא מעצמם דוקא, שהרי] מה שמבררי' בעצמם באוי\"ר ובחו\"ב גם בתו\"מ זהו בא בחידוש גמור ובריבוי גדול לאין שיעור כלל כנ\"ל בתושבע\"פ (שא' ועלמות אין מספר<sup data-n=\"8382\">1353</sup> שהן חידושי ההלכות, ואעפ\"י שנק'<sup data-n=\"8383\">1354</sup> מלכות שהן [ס' מסכתו' ופ' ברייתות<sup data-n=\"8384\">1356</sup> ] נגד ו' מדות<sup data-n=\"8385\">1355</sup> לבד כו' ששרשם ס\"ר אותיות דתשב\"כ כו' כך ס\"ר נש\"י שקשורים בס\"ר <span data-k=\"pg\">1274</span> ּ אותיות דתשב\"כ במקורם למעלה, אבל למטה<sup data-n=\"8386\">1357</sup> נעשי' בריבוי גדול לאין שיעור כמ\"ש הגדיל ה' לעשות עם אלה<sup data-n=\"8387\">1358</sup> וכתי' והי' מספר כו' אשר לא ימד<sup data-n=\"8388\">1359</sup> והוא כשעושין רש\"מ בחידוש מאין ליש כצמיחה ותולדה שאחר הזריעה וכמ\"ש וזרעתי' בארץ<sup data-n=\"8389\">1360</sup> כו' וכן זרעו לכם כו' וקצרו<sup data-n=\"8390\">1361</sup> כו' כמ\"ש במ\"א).\n<b>והנה</b> עכ\"פ מובן מכ\"ז שיש כאן ב' דברים, א' כח המברר דמשפיע עצמו דוקא והוא מה שהמשפיע ממשיך למקבל כח ועוז שיוכל להתברר מכח עצמו, כמו שהרב משפיע לתלמיד אופן השכל וסברא בהעלם ותמצית שמזה יוכל התלמיד לעמוד מעצמו על אמיתי' הדבר דמה שהתלמיד יוכל בכח עצמו לעמוד על בירור הדבר זהו בא מכח המשפיע כנ\"ל. והב' מה שבא מכח המתברר עצמו שהוא עצמו הבירור והתיקון שעולה הדבר ברור מכל סיג ופסולת אפי' דק שבדקות, כמו הטעות הדק או קושיות וסתירות שניתקן הטעות והוברר והועלה השכל בתכלית הבירור והעילוי להיות הסברא ברה וזכה ונקי' באופן שלא יוסתר אורה מכל קושיא וטעות אפי' דק שבדקות כו'. וכך הוא בשאר שפע דמקבל שנתברר אצלו לאחר שנתן בה כח עצמ[ו] לבררה בתכלית (כולד שנברא<sup data-n=\"8391\">1362</sup> בתכלית בבטן אמו",[["8380","1351","<b>ברוכי הוי'</b>: ישעי' סה, כג."],["8381","1352","<b>ברמ\"ח אברים שהן רמ\"ח מ\"ע</b>: מכות כג, סע\"ב."],["8382","1353","<b>ועלמות אין מספר</b>: שה\"ש ו, ח. נסמן לעיל שצ, ב הערה 194."],["8383","1354","<b>שנק'</b>: יאיז: שס'."],["8384","1356","<b>ופ' ברייתות</b>: ראה גם לעיל פ' שמות ט, ב. וש\"נ."],["8385","1355","<b>ס' מסכתו'. . ו' מדות</b>: ראה פע\"ח (שער הנהגת הלימוד) שי\"ז. לקמן תמ, א. מאמרי אדה\"א בראשית ע' לא. וש\"נ. שמות ח\"ב ע' תנח."],["8386","1357","<b>למטה</b>: יאיביז: ליתא."],["8387","1358","<b>הגדיל ה' לעשות עם אלה</b>: תהלים קכו, ב."],["8388","1359","<b>והי' מספר. . לא ימד</b>: הושע ב, א. יומא כב, ב."],["8389","1360","<b>וזרעתי' בארץ</b>: הושע ב, כה [ושם: לי בארץ — ראה מאמרי אדה\"א במדבר ח\"ג ע' תתפא]. ראה גם לעיל פ' בשלח קלג, ג (ובהנסמן בריש המאמר שם)."],["8390","1361","<b>זרעו לכם. . וקצרו</b>: הושע י, יב [ושם: קצרו — נסמן לעיל פ' וארא פב, א]. ראה גם לעיל פ' שמות ח, ג. משפטים רצה, ד."],["8391","1362","<b>שנברא</b>: יאיז: שנברר."]]],[2300550832,"כנ\"ל) (ולפ\"ז יש כאן הפרש בין בחי' בירור לבחי' העלאה דבחי' הבירור זהו כמו שהדבר עדיין בלתי מבורר ומעורב עם הפסולת ועומד להתברר שכל זמן שלא יצא עדיין מבורר לגמרי צריך הוא לבא בבחי' הבירור דחכ' דבחכמה אתברירו דוקא כמברר אוכל מן הפסולת כו' כנ\"ל. אך לאחר שנברר כ\"צ<sup data-n=\"8392\">1363</sup> וזרק מתוכו כל הפסולת אפי' הדק ביותר א\"צ בירור עוד רק שיעלו אותו על השולחן לאכול, וזהו שנק' העלאה שאחר הבירור שהוא בא מכח המקבל השפע שמברר בעצמו (כמו שמברר התלמיד השפע שכל שמקבל עד שתהי' זכה ונקי' כו' או כולד שיוצא מבורר וכחטה שצומחת כו') (וכלחם שנאפה ובשר שנתבשל שיבורר בבישול כ\"צ עד שראוי לאכול וכה\"ג זהו שנק' העלאה שאחר הבירור).\n<b>ועפ\"י</b> כ\"ז יובן ג\"כ למעלה בבחי' כח ההמשכה וההשפעה מלמעלה למטה ליתן כח ועוז במל' שהן כנ\"י<sup data-n=\"8393\">1364</sup> שיוכלו לברר בעה\"ד טו\"ר, היינו מה שנמשך כח ועוז מעצמות אוא\"ס ב\"ה בח\"ע וח\"ת דכנ\"י שיוכלו לברר ולהבדיל בין טו\"ר שהוא להחיות<sup data-n=\"8394\">1365</sup> סומ\"ר וע\"ט באוי\"ר שכליי' כנ\"ל. ואמנם אע\"פ שכח ועוז זה נמשך מלמעלה דוקא כמו תנו עוז לאלקי' שהוא ש' ב\"ן כנ\"ל וכתי' ה' עוז לעמו יתן<sup data-n=\"8395\">1366</sup> ואין עוז אלא תורה<sup data-n=\"8396\">1367</sup> דבח\"ע אתברירו והוא באותיות דתשב\"כ שאדם קורא כו' נותן כח ועוז בנשמתו שיברר בכח עצמו דוקא, והוא מה שיוכל לעמוד בנפשו האלקי' לבא למס\"נ באחד ביחו\"ע ויחו\"ת ע\"י כח החכ' שבנה\"א שמשיג אלקות מפריד הרע מן הטוב בתכלית עד שיכול לברר גם כל<sup data-n=\"8397\">1368</sup> היום בכל [דרכיו ו]מעשיו וגם במזונו ומלבושיו ודירתו שיהי' הכל בתכלית הבירור כנ\"ל. אך כ\"ז אינו כ\"א<sup data-n=\"8398\">1369</sup> בחי' הכנה לבד שהוא כמו שמתקנים דבר מה ומבררים אותו שיהי' ראוי לאכילה, אבל עיקר <span data-k=\"pg\">תרלז</span> ּ ענין הבירור השלם אינו רק לאחר ש[כבר] הוברר כל חלקי הרע מן הטוב ולא נשאר רק הברור בתכלית אזי עולה הכל לה' אחד (כמו במס\"נ שהוא הנק' העלאה שבאה אחר הבירור בעצמו מכל סיג דק יעלה נפשו במס\"נ באחד כמו מי יעלה כו' ובר לבב אשר לא נשא לשוא נפשו שאין בו [שום] תערובות רצון והתקשרות זרה שלא לה' כו' וכן אליך ה' נפשי אשא נפש זכה וטהורה מכל סיג כו') (וזהו כמשל התינוק שאחר הבירור<sup data-n=\"8399\">1370</sup> של הטעות הדק אז יעלה השכל והסברא נקי' מכל סיג כו'). אך א\"א למתברר להתברר כ\"כ עד שראוי לעלות למעלה כ\"א כאשר יהי' לו כח ועוז מתחלה להתברר מעצמו ולעלות, והוא ע\"י המשכות העליונות שבא מח\"ע דמשפיע שנמשך משם בהעלם בתוך המתברר כפי המובן מכל המשלים הנ\"ל בגדול שעוזר",[["8392","1363","<b>כ\"צ</b>: כל צרכו."],["8393","1364","<b>במל' שהן כנ\"י</b>: ראה זהר בלק קצז, א."],["8394","1365","<b>להחיות</b>: יאיז: להיות."],["8395","1366","<b>ה' עוז לעמו יתן</b>: תהלים כט, יא."],["8396","1367","<b>ואין עוז אלא תורה</b>: ראה ספרי ברכה לג, ב. הנסמן לעיל פ' בשלח קפג, ג."],["8397","1368","<b>כל</b>: ו: ניתוסף בין השיטין בחצאי עיגול. יאיז: ליתא. יב: כבפנים."],["8398","1369","<b>כ\"א</b>: יאיביז: ליתא."],["8399","1370","<b>התינוק שאחר הבירור</b>: ויאיביז: לאחר התיקון."]]],[2300550833,"לקטן לילך או רב לתלמיד שעוזרו שיוכל להתברר מעצמו כנ\"ל וד\"ל.\n<b>והנה</b> כמו שמבואר למעלה בענין המשכת כח המשפיע למקבל שיוכל לברר א\"ע ע\"י בחי' החכ' לפי שבחכ' דוקא אתברירו כמו שמברר חכמת דבר מה בדין והלכה מטעות וסיג או במדות שבלב לברר בין טו\"ר עד שנק' בר לבב כנ\"ל בענין מס\"נ בק\"ש באהבה שבלב כו', כך נמשך כח ועוז מן המשפיע למקבל ע\"י המשכת אור האה\"ר העליונה האלקי' שיורדת ונמשכת מלמעלה למטה בלב כנ\"י שיתעוררו עי\"ז כמים הפא\"פ<sup data-n=\"8400\">1371</sup> כו' גם<sup data-n=\"8401\">1372</sup> באה\"ר ותשוקה נפלאה כענין שאו' אה\"ע ואה\"ר [אהבתנו]<sup data-n=\"8402\">1373</sup> כו' עד הבוחר בעמו ישראל באהבה, שזהו אה\"ר העליונה שנמשכת מעצמות אוא\"ס ממש בפנימי' ועצמי' כאב את בן ירצה<sup data-n=\"8403\">1374</sup> באה\"ר, ויכול להיות כח ועו\"ז באה\"ר זאת עד שתתן תוס' כח ועוז בנש\"י שיוכלו להתברר בעצמם בין טו\"ר שבנפשם והוא לעלות נפשם במס\"נ בק\"ש בבחי' בר לבב כו' כענין לב אחד לאביהם שבשמים<sup data-n=\"8404\">1375</sup> (ולא ב' לבבות כו' וכמו ואהבת בכל לבבך בב' יצריך כו'). וכמו שהי' נמשך אה\"ר בנש\"י מרב חסד העצמי' כנ\"ל ע\"י אהרן כה\"ר בא' לו בהעלותך את הנרות כו' אל מול פני כו', שזהו [כמו] כח המעלה לנש\"י שנק' נרות הוי' ע\"י המשכת כח ועוז מאה\"ר העליונה שמושך לב בנ\"י להתעורר ולעלות למעלה מעלה להיות מאירי' נרות ה' שהן נשמתם אל מול פני המנורה<sup data-n=\"8405\">1376</sup> כו' ליכלל בעצמו' א\"ס ממש במס\"נ באחד אחר תכלית הבירור שנק' זה בחי' העלאה שלאחר הבירור בתכלית כנ\"ל (וכך הי' במ\"ת שהי' כפה<sup data-n=\"8406\">1377</sup> עליהם הר כגיגית<sup data-n=\"8407\">1378</sup> כו' שזהו הי' המשכת עוז האה\"ר העליונה העצמי' שהקיפם לנש\"י מלמעלה להיות בהן כח ועוז להתעורר ולעלות לקבל התו' פב\"פ כו', וזהו מימינו אש<sup data-n=\"8408\">1379</sup> כו' מימינ\"ו דוקא, והיינו כמ\"ש וימינ\"ו תחבקני<sup data-n=\"8409\">1380</sup> כחיבוק ביד הימין שמחבק האב לבנו מאחוריו ומחברו ומצמידו אליו לבלתי יוכל להפריד<sup data-n=\"8410\">1381</sup>, ובחיבוק זה הוא שמעורר בו את האה\"ר הגנוזה בלב בהעלם שתצא לגילוי וכאדם שמחבק לאשתו שמעורר בה את האהבה שתומשך אחריו תמיד ולא [ת]תפרד ממנו ליתן עיני' באיש אחר כו' כידוע. כך בחי' ימין דרב חסד העליון <span data-k=\"pg\">1276</span> ּ שהוא בחי' מקיף דאה\"ר העצמי' דא\"ס ב\"ה לנש\"י שהן בבחי' פנימי' ועצמי' כאב לבן ממש כמ\"ש כי בנים אתם<sup data-n=\"8411\">1382</sup> כו' מחבק בימינו למטה בנש\"י שבגופים לעורר בהם האה\"ר כנ\"ל לבלי יוכלו להפרד ממנו לעולם אף בהיותם טרודים מאד בצרכי גופם כו'. והעיקר הוא מה שחיבוק זה דאה\"ר העליונה גם שבאה בהעלם בבחי' מקיף על נשמתם נותנת תוס' כח ועוז בעצמות דנש\"י",[["8400","1371","<b>כמים הפא\"פ</b>: ע\"פ משלי כז, יט."],["8401","1372","<b>גם</b>: יאיז: ג\"כ."],["8402","1373","<b>שאו' אה\"ע ואה\"ר [אהבתנו]</b>: ברכת ק\"ש שחרית (נוסח אשכנז וספרד)."],["8403","1374","<b>כאב את בן ירצה</b>: ע\"פ משלי ג, יב."],["8404","1375","<b>לב אחד לאביהם שבשמים</b>: ברכות נז, א. ראה גם מאמרי אדה\"א שמות ח\"ב ע' שפ וע' תעד. ש\"א לו, ב."],["8405","1376","<b>המנורה</b>: יאיז: ליתא."],["8406","1377","<b>שהי' כפה</b>: שם: שכפה."],["8407","1378","<b>שכפה עליהם הר כגיגית</b>: ראה גם לעיל פ' משפטים רצז, ג. וש\"נ."],["8408","1379","<b>מימינו אש</b>: ברכה לג, ב."],["8409","1380","<b>וימינ\"ו תחבקני</b>: שה\"ש ב, ו. ח, ג."],["8410","1381","<b>להפריד</b>: יא: להפסיק. יז: להפרד."],["8411","1382","<b>כי בנים אתם</b>: פ' ראה יד, א [בהוספת תיבת: כי — נסמן לעיל פ' וארא פה, ג הערה 840]."]]],[2300550834,"שיהי' בהם כח להתברר ולעלות לה' במס\"נ ביחו\"ע ויחו\"ת בק\"ש ולהפריד ולהפשיט<sup data-n=\"8412\">1383</sup> א\"ע מכל רצון זר הנפרד מאלקות שנק' ב\"ר לב\"ב בתכלית כנ\"ל וד\"ל (וזהו בא בב' אופנים א' בענין חיבוק כנ\"ל שנותן בו כח להתעורר באה\"ר או בתשובה שלימה כמו השיבנו ה' אליך כמו בחיבוק דמקיף הנ\"ל, או שיערה עלינו רוח ממרום יהי'<sup data-n=\"8413\">1384</sup> התעוררות ונשובה ממילא בתש\"ע, וכן א' משכני בחבלי עבותות אה\"ר [העליונה] כנ\"ל באהרן כה\"ג וכמו שאו' אה\"ע אהבתנו וכה\"ג ואז אחריך נרוצה מכח עצמינו כניצוץ שרץ ונכלל מעצמו בשלהבת שכל דבר נמשך למקורו כו'. והב' כענין הנ\"ל במ\"ש אנכי תרגלתי לאפרים כו' כאב המשפיל ידיו למטה מטה ומגביהו למעלה<sup data-n=\"8414\">1385</sup> לתינוק על כתיפו שהעלא' זו אינו מכח התינוק כלל, וכך הי' ביצ\"מ שנשא אותם כאשר ישא האומן כו' כנ\"ל וכמ\"ש ואשא אתכם על כנפי נשרים<sup data-n=\"8415\">1386</sup> כו' וכן ישאהו על אברתו (ויש עוד אופן ג' שלא ע\"י בחי' מקיף מרחוק כנ\"ל, אלא שכח או\"מ<sup data-n=\"8416\">1387</sup> זה דאה\"ר העצמו' הנ\"ל הוא שנכנס ונתקשר בתוך כלי המקבל בבחי' פנימי' ועצמיות ממש כאשה שכורתת ברית לבעלה<sup data-n=\"8417\">1388</sup> בביאה ראשונה כו' שנק' רוחא דשביק בגווה<sup data-n=\"8418\">1389</sup> כידוע. וזה הי' ג\"כ במ\"ת מצד ששמעו קול ה' מדבר מתוך האש<sup data-n=\"8419\">1390</sup> כו' שנמשך בנשמתם עי\"ז<sup data-n=\"8420\">1391</sup> התקשרות אה\"ר ונפלאה בבחי' פנימי' ועצמיות שנק' כריתות ברית כאשה לבעלה כו' ברוחא דשביק בגווה בהעלם שלא יוכלו להפרד לעולם, ומכח זה יש כח ועוז בנש\"י בכל הדורות להתעורר באה\"ר תמיד עד שיעלו במס\"נ באחד בבירור בתכלית כנ\"ל כמו שיש כח [ה]זה מן המשפיע בבחי' או\"מ הנ\"ל ויותר ממנו הרבה (כמ\"ש במ\"א) וד\"ל.\n[כה]<b> והנה</b> אחר הקדמה זו יובן ג\"כ עד\"ז בשרש ענין ל\"ט מלאכות שנאסרו בשבת וילפינן להו ממלאכות שהיו במשכן כמו שרמז בא' אלה הדברים אשר צוה כו' כנ\"ל ו[כ]מבואר בדרז\"ל, דהנה ענין הל\"ט מלאכות שנחלקו בג' חילוקים דמזון ולבוש ובית כנ\"ל הוא שנעשו בימות החול דוקא [ו]כמ\"ש וי\"ו ימים תעשה מלאכה כו' שמלאכה זו כוללת ל\"ט מלאכות הנ\"ל וקאי אדסמיך לי' שא' אלה הדברים כו'. והענין הוא כמו שבגשמיות ענין המלאכות הללו<sup data-n=\"8421\">1392</sup> הן רק בחי' ירידה והמשכה בדילוג הערך מעצמות האדם שהוא בר דעת ותבונה בכל חכ', ומדות שבלב המה נמשכים רק מן החו\"ב ודעת שבראש לעצמו כמו שהוא, והוא משפיל ומוריד ומצמצם א\"ע להוריד שפע חכ' ומדות שלו במעשה ומלאכה שה[ו]א כח היגיעה והעמל בפעולה בידיו ו[ב]רגליו כמו לחרוש האדמה ולזרוע כו' עד שיעשה הפת בלישה <span data-k=\"pg\">תרלח</span> ּ ואפי' שיהי' ראוי למאכל אדם. וכן ביגיעתו במלאכות השייכ[י]' ללבוש כט[ו]וה ואורג כו', וכן במלאכות שבבנין בית וכה\"ג, כ\"ז אינו רק גודל עוצם",[["8412","1383","<b>ולהפשיט</b>: יאיז: ליתא."],["8413","1384","<b>יהי'</b>: יאיז: להיות."],["8414","1385","<b>ומגביהו למעלה</b>: שם: ומגביה ומעלה."],["8415","1386","<b>ואשא. . כנפי נשרים</b>: יתרו יט, ד."],["8416","1387","<b>או\"מ</b>: יאיז: אור."],["8417","1388","<b>כאשה שכורתת ברית לבעלה</b>: ראה סנהדרין כב, ב."],["8418","1389","<b>רוחא דשביק בגווה</b>: ראה זהר (סבא) משפטים צט, ב. מאמרי אדה\"א הנחות תקע\"ז ע' צט. וש\"נ. ש\"א כז, ב הערה 30."],["8419","1390","<b>ששמעו קול ה' מדבר מתוך האש</b>: ואתחנן ה, יט-כא."],["8420","1391","<b>עי\"ז</b>: יאיז: עוז."],["8421","1392","<b>הללו</b>: שם: ליתא."]]],[2300550835,"הירידה וצמצום מעצמות חכמתו ומדותיו להתלבש ולהתצמצם כ\"כ במלאכה ומעשה בפועל, דגם שנותן בזה ג\"כ שכלו ומדותיו איך שיוכשר אופן העבודה בכי טוב עד שתצמ[י]ח ותעלה לתכלית הכוונה בתועלת היוצא מזה כמו למזון ולבוש כו'. אך זהו רק צמצום השכל ומדות בדבר מעשה גשמי' שנק' שכל ומדות דעשי' לבד שאין לזה ערך כלל וכלל לעצם החכ' ומדות שבאדם. וזהו כענין הנ\"ל בחכ' דמשפיע שיורד ומתצמצם ומתלבש בערך המקבל כדי שיוכל לברר מכח עצמו כו', כך יורד ומתלבש מעצם החכ' שבראש לחכ' ושכל המצ[ו]מצם למעשה ומלאכה זו שישכיל בה ויצליח לברר היטב בכל המלאכות שבאדמה עד ש[י]ברר המאכל מכל סיג ויהי' ראוי למזון וכן הלבוש והבית, שבחי' כח הבירור הזה בחכ' ומדות שבעשי' זו נמשך רק מכח עצם החכמה ומדות שלו דוקא כידוע. וכמו שנראה בחוש בכל חכם אומן שגם ששכל שבאומנות שלו נק' שכל שבעשי' לתקן דבר מה ולעשות כלי מתוקן כו', מ\"מ תלוי לפ\"ע עצם החכ' שבו דוקא שיוכל להשכיל יותר עד השכל הזה המצומצם כו'. אך אינו בא בחי' המשכה והשפעה זו מעצמות כח חכמתו לשכל זה שבמלאכה או אומנות בגילוי אור שכל גמור רק בבחי' ההעלם שהוא רק הכח ועוז שניתן בהעלם בהתחכמות זו שמתחכם לתקן הדבר בשכל השייך לעשי' זו כו', וע\"ד הנ\"ל בשכל וסברא שנמשך מהרב מעצמות חכמתו לתלמיד הקטן לפ\"ע המצומצם שממשיך בזה כח ועוז בדברי' מן הצד כמו בדרך קיצור [ותמצית] או במשלים ברורים שמזה יהי' כח ועוז בתלמיד לברר השכל מעצמו ולעמוד על אמיתתו כו' (וכנ\"ל דזהו מ\"ש דח\"ע אתמשך בח\"ת להיות לעזר שיוכל להיות הבירור בח\"ת דתשבע\"פ מכח עצמה כו' ויש בזה כמה אופנים כו' כנ\"ל, וגם מבואר למעלה שבהגיע הכח ועוז הזה מחכ' דמשפיע למקבל ימצא בכח המקבל תוס' כח רב ביתרון מעלה ממה שקיבל להוליד ולהצמיח בריבוי יותר כו' דבינה יתירה ניתנה באשה כו', וזה מעלת תשבע\"פ [ש]מחדש[י'] מאין ליש ממש הלכות לאין שיעור כו').\n<b>והנמשל</b> מכ\"ז יובן ג\"כ בבחי' הרוחני' דל\"ט מלאכות הנ\"ל בב' אופנים, הא' בחיצוני' והוא בוימ\"ב העליונים שהן ששה מדות דאצי' שנמשכו<sup data-n=\"8422\">1393</sup> בוימ\"ב הראשונים שכל יום כולל אלף שנה בזמן ומקום כו' כמ\"ש כי אלף שנה כיום<sup data-n=\"8423\">1394</sup> כו' שהן ו' יומין עילאין דאצי' שנמשכו מבחי' חו\"ב דאצי' להיות מקוריי' לו\"א שני דהוי עלמא, כמו ביום הא' האיר מאור מדת החסד דאצי' וח\"ע דאצי' שבאדם העליון כו'<sup data-n=\"8424\">1395</sup> במאמר יהי אור והוא מקור לכל אלף שנה דבחי' החסד ונעשה מזה כל בחי' התהוות העולמות העליונים ותחתונים הכל בבחי' החסד דוקא [ו]כמו בחי' החסד בפני ארי' להימין ומחנה מיכאל כו'",[["8422","1393","<b>שנמשכו</b>: ויאיז: ליתא. יב: כבפנים."],["8423","1394","<b>כי אלף שנה כיום</b>: נסמן לעיל שצא, ב."],["8424","1395","<b>כו'</b>: יאיז: ליתא."]]],[2300550836,"וכה\"ג, וכמ\"כ ביום הב' במדת הגבו' במא' יהי רקיע וביום הג' בבחי' הת\"ת כו'. וכל מדה כלולה מחברתה עפ\"י החכ' שבמדות דאצי' שיורדי' ומתלבשי' מאצי' לבריאה להיות מקור לעולמות, שזהו ע\"י בחי' המל' שהוא בחי' הדבור<sup data-n=\"8425\">1396</sup> העליון בי\"מ להביא לידי מעשה שנק' <span data-k=\"pg\">1278</span> ּ מלאכה ממש כמו יהי אור ויהי אור בפ\"מ וכן יהי רקיע ויעש את<sup data-n=\"8426\">1397</sup> כו' וכן מא' תדשא הארץ ותוצא הארץ כו' למטה בגשמיות ולמעלה בעולמות הרוחני' כפני ארי' כו' הכל נק' בחי' מעשה ומלאכה כמ\"ש אשר ברא אלקים לעשות<sup data-n=\"8427\">1398</sup> וכתיב ויכל אלקים כו' כל מלאכתו<sup data-n=\"8428\">1399</sup> וכמ\"ש<sup data-n=\"8429\">1400</sup> וישבות מכל מלאכתו<sup data-n=\"8430\">1401</sup> כו' וביום הו' אמר וירא אלקי' את כל אשר עשה כו' ונק' מע\"ב. ולפ\"ז גם בחי' החכ' ומדות שמלובש בבחי' מעשה ומלאכה זו אף להיות התהוות הגעה\"ע ומלאכים וחיות דבריאה ויצי' כו', נק' רק שכל ומדות שבעשי' לבד שנמשך בחכ' ומדות הללו המצומצמי' מחכ' ומדות דאצי' עצמן שנק' חכ' בראש לח\"ת דמל' שנק' חכ' שבדבור ומעשה בכלל. וזהו ענין ו' ימי המעשה למעלה מאצי' לבי\"ע ע\"י בחי' החכ' שבמל' בדו\"מ שנק' בחי' מקבל מחכ' ומדות דאדם העליון דאצי' כידוע, ומובן ממילא דכמו שהמדות דחכ' דאצי' מתחלקי' לו' ימים באצי', כך בחי'<sup data-n=\"8431\">1402</sup> הו' מדות דמל' בבי\"ע מתחלקי' בו\"א שנין דהוי עלמא כו' להוות מאין ליש ע\"ד שבכל יום מחדש מע\"ב כידוע, ונק' כל שבוע וימ\"ב והיינו ו' ימי המעשה בפרט ויום השבת דכל שבוע הוא חלק א' פרט[י] משבת בראשית הכללי כו' וד\"ל.\n<b>אך</b> הנה כתיב אשר ברא אלקי' לעשות שהוא לתקן דוקא כמו ענין ל\"ט מלאכות הנ\"ל שמלאכות דחרישה וזריעה כו' הוא לתקן האדמה ליתן בה תוס' כח ועוז שיצמיח ממנה לחם הנברר למזון וכה\"ג בלבוש כו', וכך הוא למעלה בו' ימי המעשה בראשית העליוני' המקוריי' להעולמות עד עוה\"ז כנ\"ל הן באי' בבחי' הבירור והתיקון דוקא לתקן דבר המקולקל דבחכ' אתברירו כנ\"ל. וכמו ביום הא' שמאיר בחי' חסד שבמל' נמשך בחכ' שבחסד זה ענין תיקון ובירור לכל העולמות שצריך להיות במדרג' דחסד, והוא מה שיב[ו]רר ויעלה מעה\"ד טו\"ר בחי' הטוב מניצוצי הקדושה דבחי' התהו שנפלו למטה בשבה\"כ (ע\"י חטא עה\"ד כידוע), וכך ביום הב' מאיר ונמשך מבחי' הגבורות לתקן ולברר במדה זו בעה\"ד כו' בהיכלות דנוגה דבי\"ע וגם בעצמו' הברואי' [כ]נשמות ומלאכים דבי\"ע שיהי' בהן ביטול הי\"ש לאי\"ן בשירה ועבודה האלקי' בכל יום כו'. וכך בכל ו' ימי המעשה [בכל מה] שברא אלקים מאין ליש הכל לתקן ולברר כו', והוא בחי' ש' ב\"ן דמל' שמברר לעולמות דבי\"ע בחכ' שבדו\"מ כמו משל חכ' שבעשי' שמתקן דבר כמו בכלי אומנות וכמו חרישה",[["8425","1396","<b>המל'. . הדבור</b>: ראה זהר לך פו, ב. לעיל פ' שמות לד, א. וש\"נ."],["8426","1397","<b>ויעש את</b>: בראשית א, ז [בדילוג השם]."],["8427","1398","<b>אשר ברא אלקים לעשות</b>: בראשית ב, ג."],["8428","1399","<b>ויכל. . כל מלאכתו</b>: בראשית ב, ב [בהוספת תיבת כל]."],["8429","1400","<b>וכמ\"ש</b>: יאיז: ליתא."],["8430","1401","<b>וישבות מכל מלאכתו</b>: המשך הכתוב ויכל אלקים [בדילוג]."],["8431","1402","<b>בחי'</b>: יאיז: ליתא."]]],[2300550837,"וזריעה בארץ כו'. ותחלת הבירור הזה הוא בגעה\"ע שא' בה גבי אדה\"ר שהניחו שם לעבד\"ה ולשמר\"ה שזהו בבחי' בירור פנימי' מחיצוני' כעובד אדמה, וכך בגן [זה] דעדן העליון דכתי' ויטע ה' אלקי' גן בעדן מקדם<sup data-n=\"8432\">1403</sup> כו' שצריך בירור ותיקון עכ\"פ. ואעפ\"י שלא שלט שם הרע דתערובות עה\"ד טו\"ר כלל, מ\"מ יש בו בירור ותיקון ועבודה בבחי' הרוחני' עכ\"פ כמו להוסיף בו צמיחה טובה בכל עץ פרי הגן עד שגם הנשמות ישבעו ויתענגו שם מזיו השכינה בפנימי', [ו]צריך ג\"כ תיקון ועבודה להיות תוס' אור התגלות מפנימי' ועצמות העונג העליון שבעדן סתימאה והיינו ע\"י מ\"ע ול\"ת דוקא כמאמר לעבדה זו רמ\"ח מ\"ע ולשמרה זו שס\"ה ל\"ת<sup data-n=\"8433\">1404</sup>. והיינו אופן הב' שבתיקון <span data-k=\"pg\">תרלט</span> ּ ובירור דח\"ע בהתלבשות שלה בח\"ת דמל' דאצי' בגעה\"ע בבחי' פנימי' דוקא שלמעלה מאור ושפע החיצוני' שנמשך למלאכי' דבי\"ע, והיינו מצד מעשה המצות [ש]שרשן בפנימי' ועצמו' התענוג ורצה\"ע שמלובש בפנימי' דח\"ע כו' (וכמשי\"ת) במ\"א<sup data-n=\"8434\">1405</sup>. והנה ע\"ד בירור ותיקון דלעבדה ולשמרה בגעה\"ע, כך יש בחי' עבודה ותיקון גם למטה בגעה\"ת וכל המלאכו'<sup data-n=\"8435\">1406</sup> עד שיבורר גם בעוה\"ז ש[נ]משך מבחי' עה\"ד טו\"ר ממש שנתגשם והי' למדות רעות באדם וגם בבהמה וצומח ודומם כו'. והן הנה ענין ל\"ט מלאכות בכלל<sup data-n=\"8436\">1407</sup> שנחלקו לג' מדרגות במזון ולבוש ודירה, שהוא בבחי' בירור דח\"ת דמל' עד מל' דעשי' בעוה\"ז השפל לתקן ולברר [כמו] המזון שיצא לחם מן הארץ ברור מפסולת, וכן הלבוש והדירה שהן בחי' מקיפי' דנר\"נ שנברר הכל מעמ\"ר<sup data-n=\"8437\">1408</sup> דק\"נ כנ\"ל ובחכ' אתברירו דוקא שהוא ע\"י חכ' שבנה\"א בכלל ובפרט<sup data-n=\"8438\">1409</sup> כנ\"ל. ולמעלה זהו בכללות דחכ' שבמל' דאצי' [שנק' ח\"ת ש]יורד משם השפע האלקי' לברר למטה בבי\"ע בכל ו' ימי המעשה כמו ביום הא' בבחי' חסד כו' כנ\"ל, ובחי' החכ' שבמל' דאצי' מקבל מח\"ע שבראש שמשם נמשך הכח ועוז במל' לברר בירורים דעה\"ד בבי\"ע כמו לעבדה ולשמרה בג\"ע ע\"י מ\"ע ול\"ת שבכל אדם כנ\"ל, והוא שנחלק לג' חלקים בל\"ט מלאכות במזון ולבוש ובית כנ\"ל וד\"ל.\n<b>וכללות</b> כל הענין הזה זהו ממש כמו שמבואר למעלה במשל ירידה וצמצום דאור החכ' ומדות שבאדם, להשפיל א\"ע בשכל ומדות ש[מ]צמצם במלאכ[ה] ועבודה גשמי' כמו לחרוש ולזרוע כו' עד שיברר מכל אשר יעשה להיות מזון דפת וכן בלבוש ובית כנ\"ל, שכ\"ז אינו רק קטנות השכל ומדות שבעשי', ועכ\"ז נמשך בזה כח ועוז מחכ' ומדות העצמיי' שיוכל להשכיל גם בשכל זה שבמלאכה ותיקון כמו חכם בכלי אומנות כנ\"ל. וכך הוא ממש בחכ' ומדות שמלובש במע\"ב שנק' וי\"מ המעשה למעלה שבא[ים] ג\"כ לתקן ולברר לעה\"ד כנ\"ל כמו אור",[["8432","1403","<b>ויטע. . גן בעדן מקדם</b>: בראשית ב, ח."],["8433","1404","<b>לעבדה זו רמ\"ח מ\"ע. . ל\"ת</b>: נסמן לעיל פ' יתרו רסו, ג."],["8434","1405","<b>(וכמשי\"ת) במ\"א</b>: ויאיביז: (כמ\"ש במ\"א)."],["8435","1406","<b>המלאכו'</b>: שם: המלאכי'."],["8436","1407","<b>בכלל</b>: יאיז: ליתא. יב: כבפנים."],["8437","1408","<b>מעמ\"ר</b>: ויא: מע\"ס. יב: מעומק רע. יז: מעשי'."],["8438","1409","<b>בכלל ובפרט</b>: יאיז: בכ\"א בפרט."]]],[2300550838,"החסד ביום הא' כו' כנ\"ל, שבודאי אינו רק כמו שכל המצומצם בעשי' או באומנות כנ\"ל, אך מ\"מ ודאי מלובש בכח זה דחכמה שבדו\"מ דבחי' הנ\"ל<sup data-n=\"8439\">1410</sup> הנק' ח\"ת [מ]המשכת כח ח\"ע שבראש, שנמשך משם כח ועוז בדרך ירידה וצמצום והתלבשות בהעלם שיוכל חכ' דמל' לברר ולתקן שהוא להעלות לרפ\"ח ניצוצי' מק\"נ, שזהו ענין ג' חלוקות דל\"ט מלאכות כחורש וזורע כו' עד שיבורר למטה כל ג' מדרגות הנ\"ל דמזון ולבוש ובית בל\"ט מלאכות הללו להיות עולים למעלה לבחי' האצי' דהיינו להיות בחי' מזון לבוש ובית בבחי' האצי' ממש (כמו שמובן כ\"ז בענין א\"ח עט\"ב כו' שזהו בחי' המל' שם ב\"ן שמבררת בירורי' דרפ\"ח ניצוצו' בהיכלות דנוג\"ה כו' כמו האשה שנק' א\"ח שנושאת ונותנת בתוך הבית שנק' עקרת הבית שעוסקת בכל מיני מסחור בבית ובשדה ועושה כל מלאכה ואומנו' בידיה עד שמרווחת הון רב כו'. כך בענין הבירורי' דרפ\"ח שנפלו בנוגה שיבורר משם ויעלה למעלה זהו הכל ע\"י אשה יראת ה'<sup data-n=\"8440\">1411</sup> היא תתהלל כמ\"ש בסוף תנו לה מפרי ידיה<sup data-n=\"8441\">1412</sup> כו', והזכיר לבוש כמו דרשה צו\"פ כו' ומזון כמו ממרחק תביא לחמ\"ה<sup data-n=\"8442\">1413</sup> שהוא מבירורי' דנוג\"ה וזהו ותקם כו' וזהו<sup data-n=\"8443\">1414</sup> ותתן טרף רפ\"ח <span data-k=\"pg\">1280</span> ּ ע\"ה טר\"ף כידוע, וכן א' וכל ביתה לבוש שנים<sup data-n=\"8444\">1415</sup> מבחי' הגבו' דנוג\"ה באריגה טובה שלא תירא משלג כו' וכה\"ג בכל המלאכות כמו סדין עשתה כו' שמדבר כ\"ז במל' דאצי' שלע\"ל יהי' עלי' המל' למעלה מז\"א. וז\"ש א\"ח עט\"ב משום דבירורי' דמל' ש' ב\"ן הוא שעולה למעלה יותר מן החסדים דמשפיע באו\"י כו', והוא מטעם הנ\"ל שאע\"פ דחכ' דמקבל נמשך בזה עוז וכח מחכ' דמשפיע שיוכל לברר מכח עצמו כנ\"ל אבל בהגיע האור למקבל יש בה תוס' כח ועוז יותר מן המשפיע דבינה יתירה ניתנה באשה כו'. וראי' ממה שממ\"ן שלה נתחדש המציאות של הולד בגילוי צו\"ח<sup data-n=\"8445\">1416</sup> גשמי'<sup data-n=\"8446\">1417</sup> כמו האברים בגידול רב כו' כנ\"ל, וכן בזריעה יצמח מכח הארץ עצמה בריבוי גדול יותר כו'. וכך הוא בתשבע\"פ שמקבל מתשב\"כ [ש]לאחר שנמשך כח ועוז במ\"ת<sup data-n=\"8447\">1418</sup> דתשבע\"פ מח\"ע דתשב\"כ אז יש בה כח גדול מעצמה הרבה יותר לחדש מאי\"ן ליש הלכות ודינים לאין שיעור וכמ\"ש ועלמות אין מספר כנ\"ל<sup data-n=\"8448\">1419</sup>, וכר\"ע שהי' דורש על כל קוץ תלי תלים של הלכות<sup data-n=\"8449\">1420</sup> ולכך גם משה שהי' עיקר המשפיע לתשב\"כ<sup data-n=\"8450\">1421</sup> חלשה דעתי' ממה שר\"ע דורש<sup data-n=\"8451\">1422</sup> כו', והוא מ\"ש א\"ח עט\"ב שהוא תשבע\"פ שמבררת בעה\"ד טו\"ר כמו הצמיחה בארץ שאחר הזריעה מתשב\"כ שיהי' לאין שיעור. וזהו דרשה צו\"פ לעשות לבוש דמצות ולחם דתורה להיות בבחי' מזון ולבוש ובית דאצי' ממש שיעלה למעלה ממזון ולבוש ובית דאצי' עצמו שנמשך באו\"י כמו עוטה אור כשלמה שהוא בחי'",[["8439","1410","<b>הנ\"ל</b>: שם המל'."],["8440","1411","<b>אשה יראת ה'</b>: משלי לא, ל."],["8441","1412","<b>תנו לה מפרי ידיה</b>: משלי שם, לא."],["8442","1413","<b>ממרחק תביא לחמ\"ה</b>: משלי שם, יד."],["8443","1414","<b>וזהו</b>: יאיזי: ליתא."],["8444","1415","<b>וכל ביתה לבוש שנים</b>: משלי לא, כא [ושם: כי כל]."],["8445","1416","<b>צו\"ח</b>: צורה וחומר."],["8446","1417","<b>גשמי'</b>: יאיז: ליתא."],["8447","1418","<b>במ\"ת</b>: שם: בח\"ת."],["8448","1419","<b>כנ\"ל</b>: שם: כו'."],["8449","1420","<b>וכר\"ע. . תלי תלים של הלכות</b>: ראה מנחות כט, ב."],["8450","1421","<b>משה שהי' עיקר המשפיע לתשב\"כ</b>: ראה גם לעיל פ' תצוה שסב, סע\"ב ואילך."],["8451","1422","<b>משה. . חלשה דעתי' ממה שר\"ע דורש</b>: ראה מנחות שם."]]],[2300550839,"חשמ\"ל העליון, וכן לחם מן השמים וכה\"ג כמו אכלו ריעים כו' לפי שבירור דחשמ\"ל התחתון ומזון מן הארץ עולה למעלה יותר מטעם שבירורי' דנוג\"ה שבא בבחי' או\"ח מלמטה למעלה ע\"י בירור דח\"ת דמל' בתשבע\"פ שנק' א\"ח כו' עולה למעלה מאו\"י דח\"ע וחסד העליון במקיף דלבוש ובית (וראי' מבהמ\"ק שא[יזה] בית<sup data-n=\"8452\">1423</sup> כו' השמים ושה\"ש<sup data-n=\"8453\">1424</sup> כו' ועכ\"ז צמצם שכינתו בין שני בדי ארון שבהיכל ק\"ק דוקא, וזהו ענין המשכן דמשה שנק' אהל מועד דבחי'<sup data-n=\"8454\">1425</sup> ועשו לי מקדש ושכנתי כו' שיהי' לו דירה ובית למטה דוקא שלמעלה יותר מהיכל ובית העליון כו').\n<b>והנה</b> עכ\"פ יובן מכל הנ\"ל בענין ו' ימי המעשה בבחי' הבירורי' דנוג\"ה לתקן בעה\"ד טו\"ר כו' שהוא ענין הל\"ט מלאכות בג' מדרגות הנ\"ל, שיש הפרש בזה בין בחי' העבודה והמלאכה שמתקן ומברר להבדיל הפסולת מן האוכל עד שיצא נקי וראוי כו' כמו [גם] בגעה\"ע לעבד\"ה ולשמר\"ה כנ\"ל, ובין לאחר הבירור בגמר המלאכה והעבודה לתכליתו שזהו לאחר וי\"ו ימי החול שכבר הוברר הכל לתכליתם (כמו וירא אלקי' את כל אשר עשה והנה טוב מאד), שאז אינו מחוסר רק ההעלאה שיתעלה כל הנברר בבחי' הטוב בתכלית למעלה לה' אחד כמו להיות לו בבחי' מזון ולבוש והיכל בבחי' האצי' ממש (וכמו אפריון עשה לו המלך שלמה כו' וכמו אכלתי יערי עם דבשי כו' וכמו וע\"י יתיב לבושי' כתלג כו'). וזהו ענין העליות שעולים העולמות והמלאכי' בשבת מתחתון לעליון כמו מגעה\"ת לגעה\"ע מיצי' לבריאה ומבריאה לאצי' (כידוע בענין [ג\"פ] הב\"ו<sup data-n=\"8455\">1426</sup> ), שכ\"ז אינו רק מכל הבירורי' דו' ימות החול לאחר <span data-k=\"pg\">תרמ</span> ּ שלימות הבירורים עי\"ז יש עלי' בשבת כמו מי שטרח בע\"ש יאכל בשבת דהעלאת מ\"ן מבירורי' דל\"ט מלאכות בחול הוא עצמו שעולה בהעלאה בשבת, וכמו המאכל שכבר נברר בכי טוב גם בלישה ואפי' שאז עולה על ש\"מ<sup data-n=\"8456\">1427</sup> לאכילה וכן בענין הלבוש ודירה כו'. ולכך סעודות השבת הן בתכלית הבירור מעה\"ד ולכך א' ולא פר\"ש שבתכם שאין בו פסולת כלל כמו המן<sup data-n=\"8457\">1428</sup>, וז\"ש דא היא סעודתא דע\"י כו' וכן בלבוש דשבת ובהיכל שלא יצא איש ממקומו<sup data-n=\"8458\">1429</sup> בשבת כו' כמו ש[י]הי' בעוה\"ב ממש שנק' עולם ברור<sup data-n=\"8459\">1430</sup> וד\"ל.\n[כו]<b> ומעתה</b> י\"ל ענין מה של\"ט מלאכות שנאסרו בשבת ילפינן להו ממשכן דוקא כנ\"ל במ\"ש אלה הדברים כו', דהנה ידוע ומבואר בזהר בענין ציור המשכן ביריעות וכלים [כ]שולחן ומנורה כו' שזהו הכל הי' בדוגמא",[["8452","1423","<b>שא[יזה] בית</b>: ישעי' סו, א."],["8453","1424","<b>השמים ושה\"ש</b>: מל\"א ח, כז."],["8454","1425","<b>דבחי'</b>: יאיז: דכתיב."],["8455","1426","<b>[ג\"פ] הב\"ו</b>: נסמן לעיל פ' יתרו רנב, ד הערה 134."],["8456","1427","<b>ש\"מ</b>: שולחן מלכים."],["8457","1428","<b>שאין בו פסולת כלל כמו המן</b>: יומא עה, ב. ראה לעיל פ' בשלח קסא, א הערה 577."],["8458","1429","<b>שלא יצא איש ממקומו</b>: בשלח טז, כט."],["8459","1430","<b>בעוה\"ב. . עולם ברור</b>: ראה גם לעיל פ' שמות ט, א. וש\"נ."]]],[2300550840,"למשכן העליון<sup data-n=\"8460\">1431</sup> שנק' משכן דלעילא כמ\"ש במ\"א עמ\"ש אלה פקודי המשכן<sup data-n=\"8461\">1432</sup> משכן העדות כו' שזהו כמו תפארת אדם לשבת בית למטה, שעיקר בחי' תפארת הזה לאדם הוא כאשר הבית וההיכל יש בו ד' אלה מטה ושולחן כסא ומנורה<sup data-n=\"8462\">1433</sup> (וכמו באלישע שאמרה ונשים לו שם מטה ושולחן<sup data-n=\"8463\">1434</sup> כו' שהמטה לשכב בה והמנורה להאיר אור והשולחן לאכול וכה\"ג והכסא לישב עלי', ואם אין בהיכל מטה וכסא לישכב ולישב ולא שולחן ומנורה לא נק' היכל לדירה כלל, דאיך ידור בו בקביעות לישן ולישב ולאכול כו' בלא מטה ושולחן וכסא ומנורה כידוע שד' אלה הן עיקר התיקונים להיות בבית תפארת לאדם לשבת ולדור בו. כי לבד הכרח השימוש בד' אלה הכלים לענין השייך לדירת קבע שא\"א בלא ד' אלה דוקא לכל אדם שזהו עיקר תשמישו הקבוע בדירתו שהוא במזונו וישיבתו והשינה והאור להאיר, אף גם לבד זה הרי עיקר ההידור והתפארת לאדם בהיכלו כולו אומר כבוד והוד והדר הוא בד' כלים אלה כמו מטה נאה ושולחן וכסא ומנורה נאים ויפים שמייפים כל ההיכל והבית [ש]המה עיקר התפארת לאדם לשבת בית והיכל. אבל אם האדם בהיכל ובית בלא מטה ושולחן וכסא ומנורה אינו תפארת כלל וכלל ולא נק' דירה כלל, כי מצד עצם ההיכל והאהל אע\"פ שיש עליו מכסה מלמעלה ויכול להגן מן החום והגשמי' אינו ראוי לדירת קבע בלא ד' כלים הנ\"ל רק להיות בו לפי שעה לבד וגם הרי ההיכל אינו נאה כלל כו'.\n<b>והדוגמא</b> מכ\"ז יובן למעלה בבחי' תפארת לאדם העליון לשבת בבית והיכל למעלה שנק' מקדש או משכן הוי'<sup data-n=\"8464\">1435</sup> למעלה בבחי' האצי' שהוא ג\"כ בד' מיני כלים האלה דוקא, שהן מטה ושולחן וכסא ומנורה וכמ\"ש בזהר דד' כלים האלה נק' ד' תיקונין דשכינתא<sup data-n=\"8465\">1436</sup> בהיכל העליון (שהן היכלות דבריאה או היכלות דאצי'<sup data-n=\"8466\">1437</sup> ) שבהיכל ק\"ק שם הוא בחי' המט\"ה (כמו חדר המטות<sup data-n=\"8467\">1438</sup> ע\"ש ענין היחוד כו') כמ\"ש הנה מטת\"ו שלשלמ\"ה<sup data-n=\"8468\">1439</sup> כו'<sup data-n=\"8469\">1440</sup> ס' גבורים סביב לה כו', והוא בחי' יח\"ע דקוב\"ה ושכינתי' בהשראת גילוי אוא\"ס שבארון ולוחות שהוא בבחי' כת\"ר וח\"ע<sup data-n=\"8470\">1441</sup> כו' כידוע. ושם הוא בחי' הכסא כ\"ס א[ל\"ף]<sup data-n=\"8471\">1442</sup> אלופו ש\"ע<sup data-n=\"8472\">1443</sup> ושולחן בלחם הפנים<sup data-n=\"8473\">1444</sup> <span data-k=\"pg\">1282</span> ּ בצפון ומנורה בדרום<sup data-n=\"8474\">1445</sup> כו' וא' וכי לאורה הוא צריך אלא ללמד<sup data-n=\"8475\">1446</sup> כו', וכל אלה זהו רק לצורך האדם כנ\"ל שיוכל להיות בדירת קבע כמו במזון בלחם הפנים שנק' שולחן המלך (שממנו",[["8460","1431","<b>המשכן. . בדוגמא למשכן העליון</b>: ראה זהר (רע\"מ) בשלח נט, ב. תרומה קמ, ב. קנט, א. קסב, ב. לעיל פ' תרומה דש, ג. וש\"נ."],["8461","1432","<b>אלה פקודי המשכן</b>: פקודי לח, כא."],["8462","1433","<b>מטה ושולחן כסא ומנורה</b>: נסמן בסמוך בהערה 1436."],["8463","1434","<b>ונשים לו שם מטה ושולחן </b>: מל\"ב ד, י."],["8464","1435","<b>מקדש או משכן הוי'</b>: חוקת יט, כ (מקדש). אח\"מ יז, ד (משכן)."],["8465","1436","<b>ד' תיקונין דשכינתא</b>: ראה זהר תרומה קלג, א. לעיל פ' וארא עד, ב. וש\"נ."],["8466","1437","<b>היכלות דאצי'</b>: ראה גם לעיל פ' בשלח קמא, ג. וש\"נ."],["8467","1438","<b>שבהיכל ק\"ק. . חדר המטות</b>: ע\"פ מל\"ב יא, ב. דהי\"ב כב, יא. רש\"י ורד\"ק למלכים שם. רש\"י שה\"ש א, טז. מאמרי אדה\"ז תקס\"ג כאן (ס\"ע רלט). תקס\"ד כאן (ע' עט)."],["8468","1439","<b>הנה מטת\"ו שלשלמ\"ה</b>: שה\"ש ג, ז."],["8469","1440","<b>כו'</b>: ו: ליתא. יאיביז: כבפנים."],["8470","1441","<b>ולוחות. . וח\"ע</b>: ראה גם מק\"מ לזהר בראשית כו, ב (ד\"ה אבני שיש טהור). כס\"מ לת\"ז ת\"מ אות ש ואות ה. מאמרי אדה\"א שמות ח\"ב ע' תט."],["8471","1442","<b>הכסא כ\"ס א[ל\"ף]</b>: ראה גם בענין כסא כס א תו\"ח ח\"ש קל, ב ובהערה 28."],["8472","1443","<b>אלופו ש\"ע</b>: לשון ב\"ר פ\"כ, ב."],["8473","1444","<b>ושולחן בלחם הפנים</b>: תרומה כה, ל. אמור כד, ה ואילך."],["8474","1445","<b>ומנורה בדרום</b>: פקודי מ, כה. יומא כא, ב."],["8475","1446","<b>וכי לאורה הוא צריך אלא ללמד</b>: ראה שבת כב, ב. לעיל פ' וארא עב, ד."]]],[2300550841,"נמשך שפע המזון לכל העולמות כו') ומנורה להאיר אור ה' בנרות שלה שהן נש\"י (ומשם יאיר אור לכל העולמות והמלאכים) (ועד\"ז יש גם עתה בסדר התפלה שנק' ג\"כ בשם בית כמ\"ש כי ביתי בית תפלה<sup data-n=\"8476\">1447</sup> כו', שזהו סדר<sup data-n=\"8477\">1448</sup> ד' תיקוני' הנ\"ל מטה ושולחן אלא שבחי' מטה הוא קודם ב\"ש שזהו [כמו באדם בבוקר אור מן ה]עלי' והקימה מן השינה במטה או' שלא עשני<sup data-n=\"8478\">1449</sup> כו' ופוקח עורים<sup data-n=\"8479\">1450</sup> וכה\"ג. ושולחן זהו שמסדר שבחו ש\"מ בפסוד\"ז כידוע, וכסא בשתים לפני ק\"ש וק\"ש עצמה שמייחד יחו\"ע דע\"ס דאצי' להיות אלופו ש\"ע במוחי' שבמדות כו'. ומנורה בש\"ע כידוע. ובד' תיקוני' הללו נשלם בחי' תפארת האדם העליון לשבת בית בבית תפלה כמו בבהמ\"ק כו').\n<b>ועד\"ז</b> יובן ג\"כ בבחי' אורות המקיפי' שהי' במשכן כי כל הכלים כמו ארון ושולחן ומנורה ומזבח הזהב וכה\"ג הכל הוא [ב]בחי' כלים לאו\"פ שבא ויורד מעצמות אוא\"ס בהשרא[ה] וגילוי אור בכלי ממש, אבל היריעות הפרושות על הכלים נק' אהל שהוא בחי' אורות המקיפי' שבלתי מוגבלים בכלים וזהו שנק' בית והיכל וכתי' [בי'] כתפארת אדם לשבת בית כו' שהוא ע\"י הכלים שבו שהן עיקר התפארת לבית כנ\"ל. והקרשים [שב]משכן הן עצי שטים עומדים<sup data-n=\"8480\">1451</sup> שה[ן] בחי' מקיפים דיריעות במדות שמקיף מד' רוחות כמו שהיריעות מקיפים מלמעלה שנחשבו מבחי' האהל המקיף בכלל ואין אהל בלא כלים וא\"א לכלים בלי אהל כידוע. ועכ\"פ הרי כל תבנית וציור המשכן במקיפים וכלים שהוא ביריעות וכלים הכל הי' כמראה ותבנית המשכן דלעילא כמ\"ש וראה ועשה בתבנית\"ם כו'<sup data-n=\"8481\">1452</sup> אשר אתה מראה בהר כו'<sup data-n=\"8482\">1453</sup> דוקא לא יוסיף ולא יגרע דבר, והיינו כמו שבמשכן העליון נמשך מלמעלה בחי' מקיפים דיריעות כמו עוטה אור כשלמה וכמו נוטה שמים כיריעה<sup data-n=\"8483\">1454</sup> כו', וכן בכלים [כ]ארון ושולחן ומנורה הכל הוא למעלה באצי' בבחי' אהל ומשכן העליון וכתבניתם עשה משה למטה דוקא. והטעם הוא לפי שכל עניני העבודה שבמשכן כמו בקרבנות וקטורת והדלקת המנורה כו' וכה\"ג א\"א להיות כח בקרבן לעלות למעלה לריח ניחוח להוי' כו' וכן [ב]קטרת וכה\"ג, רק ע\"י כח ההמשכה מלמעלה למטה דוקא שמשם נמשך כח ועוז בבחי' המל' שנק' שכינה להיות מברר לנוג\"ה כקרבן בהמה שיהי' לריח ניחוח לה' מהקטר חו\"ד גשמי, וכה\"ג בכל [ה]עבודה כמו במזון דלחם על השולחן לפני ה' ובמנורה להאיר אור הוי'",[["8476","1447","<b>כי ביתי בית תפלה</b>: ישעי' נו, ז."],["8477","1448","<b>סדר</b>: יז: בחי'."],["8478","1449","<b>או' שלא עשני</b>: ברכות השחר. ראה גם לעיל פ' וארא עד, ב וש\"נ."],["8479","1450","<b>ופוקח עורים</b>: ברכות השחר. ראה גם לעיל פ' וארא נ, א. וש\"נ. עד, ג."],["8480","1451","<b>והקרשים. . עצי שטים עומדים</b>: תרומה כו, טו."],["8481","1452","<b>כו'</b>: כ\"ה גם ביאיז."],["8482","1453","<b>כו'</b>: כ\"ה גם ביאיז."],["8483","1454","<b>נוטה שמים כיריעה</b>: תהלים קד, ב."]]],[2300550842,"בנרות כו' וכן בקטרת במזבח הזהב, הכל הי' זה ע\"י כח הנמשך מן המשפיע שהוא בחי' אדם העליון כמו שהוא בחכ' ומדות דעצמות המאציל שיתן כח ועוז לבחי' המל' לברר בעה\"ד כנ\"ל.\n<b>ולזה</b> הטעם הוא שנצטווה משה לעשות המשכן וכליו [כ]תבנית המשכן העליון דוקא כדי שע\"י הכלים דמשכן שנעשו [כ]תבנית כלי משכן העליון בכל פרטיהם יוכל <span data-k=\"pg\">תרמא</span> ּ להיות השראת כח הבירור הזה בכל פרטי העבודה במשכן בקדש העליון, ואם לא היו הכלים דמשכן עם היריעות שלו כתבנית המשכן וכלים העליון ממש לא הי' כח הבירור כלל למטה בפרטי העבודו' שבאהל מועד, כמו הקרבן בהמה במזבח החיצון אם לא הי' מזבח הזה בתבנית מזבח העליון לא הי' במזבח כזה כח לעלות לריח ניחוח להוי' להיות נק' לחמי לאשי ריח ניחוחי כו', וכן בלחם הפנים אם לא הי' השולחן כתבנית שולחן העליון שלפני הוי' ממש לא הי' נק' לחם הפנים לבחי' מזון, וכן במזבח הזהב [ב]קטורת מי\"א<sup data-n=\"8484\">1455</sup> סממנים [לפי] שהי' הכל בדוגמא דמזבח הקט[ו]רת למעלה, וכן במנורה, וכה\"ג גם בגילוי אלקות בארון וכפורת שבהיכל ק\"ק לפי שהוא בציור היכל ק\"ק העליון שנק' לפני ולפנים למעלה בבהמ\"ק ומשכן העליון דוקא. וכך הוא בכל פרטי עניני המשכן וכלים שלו למטה שכ\"ז אינו רק לפי שנמשך בציור זה בכלל ובפרט מכח האורות פנימי' ומקיפי' דמשכן העליון ליתן בהם כח ועוז לעלות ולברר בכלל ובפרט מטעם הנ\"ל שא\"א למקבל להתברר ולעלות מכח עצמו כ\"א בירידת הכח ועוז מן המשפיע דוקא כנ\"ל (ולכך חייבים משום שחוטי חוץ<sup data-n=\"8485\">1456</sup> אף שמקריבי' הבהמה כדין בכל פרטי' כשאינם מקריבים בפנים דוקא ולא יעלה הקרבן לריח ניחוח כלל אע\"פ שמתברר מרע לטוב בכוונה ורעו\"ד להעלות עולה לה' כמו שהי' מקריב בפנים ממש, אך לפי שאינה נקרב במזבח החיצון בפתח א\"מ<sup data-n=\"8486\">1457</sup> אינו עולה למעלה כלל, לפי שאינו בדוגמא דמשכן ומקדש העליון שנמשך משם הכח ועוז למטה לכל מתברר שיוברר ויומשך<sup data-n=\"8487\">1458</sup> ויעלה למעלה, ולהיות שכל המשכות הכח העליון לברר שזהו המשכת כח הבירור אינו אלא ע\"י כלי המשכן והמקדש בפנים דוקא ולא בחוץ שאם הוציא המזבח<sup data-n=\"8488\">1459</sup> ועשאו במה בחוץ אין עבודתו כלום וחייב כרת<sup data-n=\"8489\">1460</sup> כשוחט בחוץ (והיינו לפי שצריך להיות במקום שהיכל ה' כו' שבבחי' היכל ובית שורה שם מבחי' מקיף למקיף דוקא, וזהו שגם בתפלה שנק' בית [ה'] כמ\"ש כי ביתי בית תפלה כו' א' חציף עלי מאן דמצלי בבקתא כו' [להיות] כמו מקריב בבמה כו' (כמ\"ש בסידור באריכות<sup data-n=\"8490\">1461</sup> ).\n<b>אך</b> באמת הרי כל הדברים שבמשכן כמו תכלת וארגמן כו' וכסף וזהב לכלים ועצים לקרשים וכל כלי המשכן הכל",[["8484","1455","<b>מי\"א</b>: יאיז: מלאה. יב: כבפנים."],["8485","1456","<b>שחוטי חוץ</b>: ראה רמב\"ם הל' מעשה הקרבנות פי\"ח, ה\"ב ואילך."],["8486","1457","<b>א\"מ</b>: אהל מועד."],["8487","1458","<b>ויומשך</b>: יאיז: ליתא."],["8488","1459","<b>שאם הוציא המזבח</b>: ראה רמב\"ם הל' בית הבחירה רפ\"ב."],["8489","1460","<b>המזבח. . בחוץ. . וחייב כרת</b>: ראה רמב\"ם הל' מעשה הקרבנות רפי\"ט. פי\"ח, ה\"ב."],["8490","1461","<b>חציף. . דמצלי בבקתא. . בסידור באריכות</b>: ברכות לד, סע\"ב. סידור שער התפלה כג, ג."]]],[2300550843,"הביאו ישראל מנדבות לבם משלהם דוקא כמ\"ש קחו מאתכם תרומה לה' כל נדיב לבו יביאה כו', וא\"כ הרי המשכן וכל כליו נעשו מדברים גשמיי' דנוגה מכו\"ז<sup data-n=\"8491\">1462</sup> גשמי ומצומח דעץ גשמי ויריעות עזים ותכלת כו', רק שנעשה בהם באותו הציור והדוגמא דמשכן ה'<sup data-n=\"8492\">1463</sup> העליון דאצי' כמ\"ש וראה ועשה בתבניתם כו' וא' בזהר בפי' תרומה זו שהוא ארמותא להוי' לרומם לשם הוי' שבמשכן העליון כו', ואם כל הבירור והעלאות שהי' במשכן אינו בא רק מכח ההמשכו' העליונות שנמשך מלמעלה דוקא כנ\"ל מה[ו] שא' ארמותא להוי' איך יש ביכולת המקבל לרומם ולהעלות למשפיע כו'. אלא מוכרח לומר דאע\"פ שנמשך גילוי אורות <span data-k=\"pg\">1284</span> ּ העליונים בכלי המשכן בבחי' קדש העליון דמשכן [ה'] שלמעלה באצי' כנ\"ל להיות כח ועוז לבחי' המל' לברר כנ\"ל, אבל כל נדיב לב דוקא יביאה לתרומ' ה' כו', שבחי' או\"ח דנדיב לב בכלי המשכן שלמטה דוקא יש בזה כח רב יותר לעשות תוס' אור גדול ורב יותר מכח הנמשך מלמעלה כנ\"ל בענין תשבע\"פ שמקבל מתושב\"כ דבינה יתירה ניתנה באשה כו', וכצמיחה שאחר הזריעה שבא בחידוש גמור לבלי שיעור כו'. ולכך בכלי המשכן שלמטה בהעלאה דתרומת ה' מכל נדיב לב עולי' [כל] הקרבנות [ו]כל העבודות לריח ניחוח להוי' שבמשכן העליון למעלה יותר מאור המאיר ונמשך במשכן וכלים העליון (וכמו בבהמ\"ק דשלמה שא' ע\"ז וביום שמחת לבו<sup data-n=\"8493\">1464</sup> כו' (כמ\"ש במ\"א).\n<b>ובכל</b> הנ\"ל יובן הטעם למה שכל הל\"ט מלאכות שנאסרו בשבת ילפינן להו ממלאכות שהיו במשכן דוקא כנ\"ל, כי באמת הרי לפי כל הנ\"ל בענין הבירורי' דימות החול בוי\"מ המעשה בל\"ט מלאכות שזהו רק ענין הבירור בעה\"ד טו\"ר לתקן ולהעלות למעלה כל בחי' הטוב שנפל בק\"נ מרפ\"ח ניצוצ[ות] דתהו כנ\"ל, וא\"א להיות כח זה לברר מעצמו כ\"א ע\"י המשכות העליונות מח\"ע מלמעלה למטה דוקא כמ\"ש תנו עוז לאלקי' שהוא ש' ב\"ן דמל' המברר לבחי' ב\"ן דנוג\"ה להיות בחי' מזון ולבוש ובית למטה כמו למעלה ממש כו' כנ\"ל. וזהו ג\"כ ענין המשכן וכליו כנ\"ל דכל עיקר המשכן וכליו באו\"מ ואו\"פ כו' אינו רק בחי' המשכת האורות העליונים שנמשך ומתצמצם מלמעלה [למטה] ליתן כח ועוז במל' שהיא השכינה ששורה במשכן לברר ולהעלות לרפ\"ח כו' בכל הקרבנות ועבוד[ו'] שהי' במשכן כנ\"ל. ולפ\"ז הרי ענין א' הם ממש, ולכך ילפינן כל הל\"ט מלאכות האסורים בשבת לפי שנק' בירור ובשבת בורר אסור רק ממלאכות שהיו במשכן דוקא, לפי שכל מלאכ[ה] שהיתה במשכן בכלים הי' בחי' הירידה וההמשכה מלמעלה להמשיך קדש העליון בכלים הללו שיוכלו לברר ולהעלות מרפ\"ח כו', [כ]בירור האוכל מתוך הפסולת כידוע ומלאכה ועבודה כזו אינה",[["8491","1462","<b>מכו\"ז</b>: יז: מכסף וזהב."],["8492","1463","<b>ה'</b>: יאיז: ליתא."],["8493","1464","<b>וביום שמחת לבו</b>: שה\"ש ג, יא."]]],[2300550844,"שייך רק בוי\"מ המעשה דוקא. אבל בשבת נאסרה מלאכה כזו להיות[ו] למעלה מבחי' הבירורי' לגמרי רק אחר שכבר הוברר בחול בתכלית הוא שעולה בשבת בבחי' ההעלאה שאחר הבירור דוקא (כמשי\"ת), ולזאת כל מלאכה שלא היתה במשכן אינה אסורה בשבת כלל רק מלאכה שהיתה נעשית במשכן בשביל כח הבירור שלמטה כנ\"ל וד\"ל.\n<b>וזהו</b> אלה הדברים אשר ציוה ה' לעשות אותם שהן ל\"ט מלאכות שציוה ה' לעשות אותם לתקן ולברר עה\"ד טו\"ר כמו ברמ\"ח מ\"ע שלמעלה ומברר הטוב מן הרע כו' כמו לעבדה בג\"ע כנ\"ל, ואמנם בו' ימים דוקא תעשה מלאכה זו שהוא בחי' הבירורי' כמו במלאכות שהי' במשכן שנמשך על ידם כח ועוז למתברר כנ\"ל, וכל מלאכה שציוה לעשות במשכן נק' עבודה ומלאכה ולא מלאכה זולת זה מטעם הנ\"ל, אבל ביום הז' יהי' לכם קדש שבת שבתון כו'. ובאמת עדיין י\"ל למה נאסר בשבת מלאכה שהיתה במשכן <span data-k=\"pg\">תרמב</span> ּ דוקא לפי שנק' קדש העליון שלמעלה מן הבירורי' דעה\"ד כנ\"ל, הלא המשכן וכליו נק' קדש העליון כידוע שטמא אסור ליכנס<sup data-n=\"8494\">1465</sup> ולעבוד במשכן<sup data-n=\"8495\">1466</sup>, ואדרבה ע\"י כלי המשכן דוקא הוא שנמשך מקדש העליון להיות כח הבירור והעלאה למטה בכל העבודו' שהי' במשכן כנ\"ל, וא\"כ למה נאסר גם בשבת הנק' קדש העליון מלאכה כזו שיהי' נמשך מלמעלה כח הבירור כו'. ועוד יש להבין דאם קדש דשבת הוא במדרגה עליונה כ\"כ עד שגם להמשיך כח ועוז לברר למטה נק' מלאכה וירידה מן העצמות היפוך השביתה והמנוחה כו', א\"כ למה הותרו הקרבנות בשבת<sup data-n=\"8496\">1467</sup> שיש בהן מלאכה ועבודה רבה בבירור ותיקון גמור כמו בזריקת דם והקטר חלבים כו' והעלאה זו דקרבנות לריח ניחוח להוי' זהו בא מכח הבירור הנעשה למטה ע\"י המשכ' כח ועוז מלמעלה דוקא כמו בשאר העבודות שבמקדש ומשכן כנ\"ל. ועוד שהרי הקרבנו' נק' לחמי לאשי כו' וידוע שבחי' אכילת מזבח נק' בירור שלמטה ואכילת אדם נק' בירור למעלה שהאכילה מצד עצמה נק' בירור, ואעפ\"י שמבואר למעלה באכילה דשבת שאינו נק' בירור אלא ענין ההעלאה לבד שעולה אחר הבירור בתכלית כו', גם זה אינו מובן דאיך אפשר להיות אכילה בלא בירור כי המאכל מעורב חיצוני' ופנימי' רוחני' וגשמיות כו', וע\"י האכילה שטוחן בשיניו ומתעכל במעיו הרי שמתברר ועולה הפנימי' מן החיצוני' כידוע. ועוד שהרי הקרבנו' הן ודאי בבחי' בירור גמור ולמה הותרו בשבת, וגם האכילה לאדם עכשיו שהוא במקום קרבן כמ\"ש פתח במזבח כו' שולחנו מכפר עליו כמזבח האיך הותר בשבת, ואם לפי שאין במאכל דשבת פסולת כלל כנ\"ל היא גופא יש להבין שהרי ודאי יש בו בירור מן הפסולת כנראה בחוש הטבעי' ולמה או'",[["8494","1465","<b>שטמא אסור ליכנס. . במשכן</b>: ראה רמב\"ם הל' ביאת מקדש פ\"ג, ה\"א ואילך."],["8495","1466","<b>שטמא אסור. . ולעבוד במשכן</b>: ראה רמב\"ם הל' ביאת מקדש רפ\"ד."],["8496","1467","<b>למה הותרו הקרבנות בשבת</b>: ראה אוה\"ת ויקהל ע' ב'קלו."]]],[2300550845,"בסעודות השבת דא היא סעודתא [דע\"י] כו'. והלא גם במשכן היו מקריבין קרבנות בשבת ובודאי הי' נמשך כח ועוז לבירור זה מלמעלה והאיך הותר בשבת כו' (ומה שהתפלה היא במקום קרבן עכשיו שמקריב לנה\"ב באש ש\"מ כו' בבירור דטו\"ר כו' זהו בתפלת החול דוקא, אבל בתפלות דשבת אינו רק להתענג על ה' באה\"ר בתענוגי' שלא בדרך עבודה ותיקון ובירור כלל כמו אז תתענג על ה' דא צלותא דמע\"ש<sup data-n=\"8497\">1468</sup> כו' לא נק' בירור כלל וכמ\"ש במ\"א (וכמשי\"ת) בענין אכילה דשבת<sup data-n=\"8498\">1469</sup>. אך באמת יותר יש לתמוה ולהפליא בזה על מה שהקרבנות בבהמ\"ק לא יבוטלו אפי' לע\"ל בעוה\"ב אחר תחה\"מ כנ\"ל שיהי' אז ודאי בתכלית המעלה והשלימות האמיתי' [ב]עילוי גדול ברוחני' שיהי' עליות העולמות למעלה מעלה יותר משהי' בגעה\"ע קודם חטא אדה\"ר<sup data-n=\"8499\">1470</sup> בעה\"ד דכתי' לעבדה עכ\"פ כנ\"ל, וא\"כ למה יהי' נצרך אז לקרבנות, וגם לבחי' אכילה ברוחניות עכ\"פ כנ\"ל שזהו נק' בחי' בירור עכ\"פ יהי' איך שיהי' כנ\"ל ולע\"ל לא יהי' בחי' בירורים<sup data-n=\"8500\">1471</sup> כלל וכלל כידוע [וכנ\"ל] וד\"ל.\n[כז]<b> אך</b> הנה כ\"ז יובן ע\"פ המבואר במ\"א ע\"פ ואכלתם אכול ושבוע<sup data-n=\"8501\">1472</sup> והללתם את שם ה' כו', להיות שיש להבין מארז\"ל במה שמיכאל כה\"ג מקריב נשמות ע\"ג המזבח דזה פלאי לכאו' האיך הנשמות שהן בבחי' אדם יהי' עולה כבהמה לקרבן ע\"ג המזבח <span data-k=\"pg\">1286</span> ּ והלא אין מקריבים קרבנות מן האדם אדרבה האדם הוא שמקריב מן הבהמה כמ\"ש אדם כי יקריב<sup data-n=\"8502\">1473</sup> כו' ולא שיקריבו את האדם ע\"ג המזבח כו'. והנה תחלה י\"ל שרש ענין האכילה באדם למטה להיות ידוע בסדר ההשתלשלו' שיש ג' עולמות בי\"ע ובכל עולם יש נשמות ומלאכים, נשמות הן [בחי'] פני אדם ומלאכים הן בחי' בהמות וחיות ובחי' פני אדם כולל הכל. וידוע שאין ערך כלל בין עולם התחתון לגבי העליון הימנו עד שבחי' אדם שבעולם התחתון אינו רק בבחי' צומח או חי בעולם העליון הימנו (כמו שנראה בערך הנבדל מגשמיות דעוה\"ז לרוחני' שבג\"ע הארץ דעשי', שגם מזל הרוחני שמגדל העשב והחטה מרוחניות לגשמיות אינו רק בחי' גשמיות למטה מבחי' דומם וצומח דעשב שבג\"ע, כידוע שדומם קרקע הג\"ע גבוה מד\"י ארמ\"ע<sup data-n=\"8503\">1474</sup> הרוחני' שלנו ולכך גם מ\"ז ודב\"ט הרוחני' צריך טבילה בביטול מציאותם בתכלית בנה\"ד קודם שתכנס הנשמה לג\"ע וכה\"ג (עד שגם העונג שהוא נחשב רוחני יותר משכל וחכ' כמו עונג הכבוד<sup data-n=\"8504\">1475</sup> יחשב גשמי' ממש בג\"ע, וכל תענוגי עוה\"ז אינו רק מפסולת שבצומח ודומם שבג\"ע, ולזה יכול להיות שבחי' אדם בר שכל בעוה\"ז למטה הרבה מן העץ הנחמד להשכיל שנטוע בג\"ע כו'. וכך הוא גם מעולם היצי' לגבי העולם העליון דנשמות דיצי' בגעה\"ת",[["8497","1468","<b>אז תתענג. . צלותא דמע\"ש</b>: ראה לעיל פ' תרומה שו, א. וש\"נ."],["8498","1469","<b>(וכמשי\"ת). . דשבת</b>: יאיז: (וכמשי\"ת. . דשבת)."],["8499","1470","<b>בעוה\"ב. . יותר משהי' בגעה\"ע קודם חטא אדה\"ר</b>: ראה גם לעיל פ' בשלח קנו, ג ובהנסמן שם."],["8500","1471","<b>ולע\"ל לא יהי' בחי' בירורים</b>: ראה גם לעיל פ' בשלח קנט, ג ובהערה 501."],["8501","1472","<b>ואכלתם אכול ושבוע</b>: יואל ב, כו. ראה להבא לקמן מאמרי אדה\"ז תקס\"ז ע' רנא. מאמרי אדה\"א שמות ח\"א ע' קנא. וש\"נ."],["8502","1473","<b>אדם כי יקריב</b>: ויקרא א, ב."],["8503","1474","<b>מד\"י ארמ\"ע</b>: ראה גם לעיל שצד, א ובהנסמן שם."],["8504","1475","<b>עונג הכבוד</b>: ראה גם לעיל פ' בא צט, ד. וש\"נ."]]],[2300550846,"למטה יותר מצומח דבריאה כמו עלה שבאילן העליון יותר גבוה מפרי האילן<sup data-n=\"8505\">1476</sup> שלמטה כו' כמ\"ש במ\"א), וכמו מלאכים ונשמות דיצי' נק' בחי' בהמות וחיות בערך לגבי נשמות דבריאה, וכמו\"כ נשמות דבריאה אינו רק בחי' בהמו' וחיות בעולם האצי', שבחי' האחרונה שבאצי' גבוה הרבה ממדרגה העליונה שבבריאה (כמו שמבחי' מל' דאצי' נעשה ע\"י וכתר לבריאה וגם זה ע\"י הפסק מסך כידוע וכן מל' דבריאה נעשה ע\"י ליצי'<sup data-n=\"8506\">1477</sup> וכן מיצי' לעשי'<sup data-n=\"8507\">1478</sup> עד מל' דמל' דעשי' בגלגלי'<sup data-n=\"8508\">1479</sup> כו'.\n<b>והנה</b> עד\"ז הולך האור ומשתלשל מעילה לעילה בדילוג הערך מאד עד סוף עולם העשי' בהשפע' הבאה לגשמיות דדצח\"ם וארמ\"ע ע\"י המזלות שאין לך עשב<sup data-n=\"8509\">1480</sup> כו', ושרש הרוחני' דדצ\"ח<sup data-n=\"8510\">1481</sup> הגשמיי' עולה בשרשו בגבוהי' עליהם [שהוא] מחיצוני' דאופנים דעשי'<sup data-n=\"8511\">1482</sup> והאופנים מקבלים ממלאכים דיצי' ומלאכים דיצי' ממלאכים דבריא' שהוא הראשון במדריג' ברוחניות כנ\"ל, והאחרון יותר זהו שבא לגשמיות דצ\"ח כו'. ועד\"ז יובן ענין [ה]השתלשלו' בבחי' מזון ומאכל למלאכי' ונשמות דבי\"ע, דהנה ידוע שמזון המלאכים דבריאה [כ]שרפים כו' הוא מה שנמשך להם אור וחיות האלקי בתוך כלי וחומר דצורה שלהם שבא בהגשמה לפ\"ע הגבלת הכלי שלהם, שמחמת זה משיגים אלקות במורגש ההתפעלות והעונג וטעם באוי\"ר עד שזהו לחם<sup data-n=\"8512\">1483</sup> כחיות המזון הגשמי לאדם התחתון, שעי\"ז [יהי'] בהם תוס' כח ועוז להשיג יותר באלקות ביתר מכפי המדה שמצ[ו]מצם בהן תמיד להחיותם כמו נותן לבהמה לחמה<sup data-n=\"8513\">1484</sup> לבהמות וחיות דמרכבה כמו פני ארי' פ\"ש<sup data-n=\"8514\">1485</sup> כו' וכמ\"ש בזהר עמ\"ש כפירים שואגי' לטרף<sup data-n=\"8515\">1486</sup> כו' וכמ\"ש במ\"א. ובחי' מזון זה הרוחני יותר שנמשך למלאכים דבריאה משם יורד ונמשך בירידות המדרגו' בהשתלשלו' ומשתנה בשינוי המהות מעילה לעילה <span data-k=\"pg\">תרמג</span> ּ מעולם לעולם עד שנעשה מזון ושפע למלאכים דעשי' ומהם נמשך ויורד עוד למטה עד המזון הגשמי דחטה ועשב למאכל אדם ובהמה גשמי', וכ\"ז מצד ריבוי ההשתל' בריבוי הממוצעי' מעילה לעילה שזן את כל העולמות הרוחני' עד שנותן לחם לכ\"ב כו' וד\"ל.\n<b>וכ\"ז</b> בדרך כלל, אך בדרך פרט הנה ידוע דשרש הראשון לשפע החסד במדרגה דרוחני' היינו בבחי' פני ארי' להימין ושרש השפע דגבו' נמשך מפני שור מהשמאל כו', וכל א' לפי אופן מדרגתו בשרשו כך יורד ונמשך ומשתלשל ממנו למטה מטה בריבוי הממוצעי' כנ\"ל עד בחי' נפש הבהמה הגשמי'",[["8505","1476","<b>עלה שבאילן. . גבוה מפרי האילן</b>: ראה גם מאמרי אדה\"ז הקצרים ע' קמה. תקע\"א ע' מט. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370159\" data-slug=\"torah-or\" data-id=\"3901370159\">תו\"א מקץ לד, ג</a>. שע\"ת נ, ג. מאמרי אדה\"א במדבר ח\"ד ע' א'תקצא."],["8506","1477","<b>מל' דבריאה. . ליצי'</b>: ראה ע\"ח (שער כסה\"כ) שמ\"ו, פ\"ב. פ\"ה. פ\"ו."],["8507","1478","<b>מיצי' לעשי'</b>: נסמן בהערה שלפנ\"ז."],["8508","1479","<b>מל' דמל' דעשי' בגלגלים</b>: ראה גם לעיל פ' בשלח קסה, ב הערה 70."],["8509","1480","<b>שאין לך עשב</b>: ראה ב\"ר פ\"י, ו. מאמרי אדה\"א דברים ח\"ג ע' תתמח. וש\"נ. ע' תתעו ואילך. שער האמונה נג, א."],["8510","1481","<b>דדצ\"ח</b>: יאיז: דדצח\"מ."],["8511","1482","<b>ושורש הרוחני' דדצ\"ח. . דאופנים דעשי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680049\" data-slug=\"torat-chaim\" data-id=\"2300680049\">תו\"ח וישב רד, סע\"ד</a> ואילך."],["8512","1483","<b>לחם</b>: יאיז: להם."],["8513","1484","<b>נותן לבהמה לחמה</b>: תהלים קמז, ט."],["8514","1485","<b>פני ארי' פ\"ש</b>: יחזקאל א, י."],["8515","1486","<b>כפירים שואגי' לטרף</b>: תהלים קד, כד [ושם: הכפירים]. ראה מאמרי אדה\"א בראשית ע' קכא ובהנסמן שם. דרושי חתונה ח\"א ע' רעט."]]],[2300550847,"ששרשה הראשון הוא מבחי' פ\"ש<sup data-n=\"8516\">1487</sup> דיצי' ושרש הנפש דחיות מפני ארי'<sup data-n=\"8517\">1488</sup> כידוע, וכמו שלמעלה מעלה נכללו בחי' ארי' ושור ונשר בפני אדם העליון מהם כך הוא עד למטה מטה עד עוה\"ז השפל דכל בחי' צומח וחי דבהמה ועוף נכללו ועולי' ע\"י האדם דוקא כידוע. והנה עפי\"ז יובן שבאכילת האדם למטה מאכל בשר בהמה ונעשה מזה חיות ואור לשכל ומדות שבאדם הרי נכלל ועולה בחי' נפש הבהמה שבבשר זה ונעשה מזון לבחי' אדם שזהו עליי' גדולה לבחי' בהמה שיוכלל ויעלה בבחי' אדם, וכך הוא עד רום המעלות בשרש הנפש דבהמה שהוא בבחי' פ\"ש דמרכבה כנ\"ל שבאכילת אדם למטה לבשר בהמה יעלה אותה לשרשו הראשון בבחי' פני שור כו' ונכלל ועולה בחי' פני שור בבחי' פני אדם שבמרכבה, ואין זה הכח לעלות לבהמה לבחי' פני שור רק באדם למטה שהוא בדומה לפני אדם שבמרכבה (דמ\"ה מברר לב\"ן בכל עולם לפי ערכו כו') (והגם שיש יתרון מעלה בבהמה מאדם מצד שרש הבהמות וחיות בבחי' התהו שקדם לבחי' התיקון דאדם וע\"כ יש כח במאכל לחזק למוחי' ומדות דאדם, וכמו שא' עד דלא אכילנא<sup data-n=\"8518\">1489</sup> כו', אך מ\"מ בתחלה האדם שהוא בחי' מ\"ה מברר ומעלה לבהמה בחי' ב\"ן וכמו אדם כי יקריב מן הבהמה רק אח\"כ עולה לשרשו למעלה בבחי' ס\"ג דתהו שלמעלה ממ\"ה דאדם כ[מ\"ש במ\"א ב]ענין אד\"ם ובהמ\"ה תושיע<sup data-n=\"8519\">1490</sup> כו' וד\"ל).\n<b>ומעתה</b> הנה יובן מזה שבבחי' עליות העולמות, כמו שעתה נחשבו גם המלאכים בחי' בהמות וחיות לגבי בחי' פני אדם שבמרכבה כמו למטה כיתרון האדם על הבהמה גשמי', כך כשיהי' עליות המדרגות בבחי' בירור אחר בירור אזי גם בחי' נשמות דאדם דעכשיו שבכל עולם שנק' פני אדם בכל עולם לפי מה שהוא [י]חשבו רק בחי' בהמות וחיות לגבי הנשמות העליונות יותר, שיהי' בבחי' אדם למעלה בעילוי היותר נבדל בערך מאדם דעכשיו כהבדלת ערך האדם עכשיו על הבהמה ממש. וכמו שיהי' עילוי הנשמות בימוהמ\"ש בדעת והשגה אלקו' במעלה עליונה ביותר על נשמות דאדם דעכשיו כערך יתרון מעלת האדם על הבהמה עכשיו, עד דמה שעכשיו נק' בחי' אדם כשיעלו במדרגה העליונה ביותר בהבדלת הערך כמו בימות המשיח לא יחשבו אז רק כערך בהמה וחי' לבד (ולא בערך אדם כלל אפי' כתינוק קטן, לפי ששכל אדם דעכשיו כנפש בהמה ממש יחשב שמה) עד שכאשר יצטרכו לבא אז בבחי' בירור הרי יתבררו <span data-k=\"pg\">1288</span> ּ ויתעלו להיות כמו מזון וחיות לנשמות העליונות החדשות כמו התכללות דמאכל בהמה ש[מ]פני שור שמתברר",[["8516","1487","<b>נפש הבהמה. . פ\"ש</b>: ראה גם לעיל פ' יתרו רסג, ג. וש\"נ."],["8517","1488","<b>ושרש הנפש דחיות מפני ארי'</b>: ראה אור החיים אחרי יז, יד. מאמרי אדה\"א דברים ח\"ד ע' א'רו וע' א'רפה."],["8518","1489","<b>עד דלא אכילנא</b>: נסמן לעיל פ' תשא שפד, ג."],["8519","1490","<b>אד\"ם ובהמ\"ה תושיע</b>: תהלים לו, ז. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'ריז. וש\"נ."]]],[2300550848,"ונכלל בבחי' פני אדם עכשיו בכל עולם. ואין זה פלא כ\"כ מאחר שידוע שבסדר ההשתל' מעולם לעולם שיש בכל עולם [בחי'] פני שור ופני אדם ולפ\"ע עליות המדרגות מתחתון לעליון יחשב פני אדם שבעולם התחתון בעלותו למעלה לעליון הימנו רק בחי' פני שור לבד (מאחר שמחיצוני' שבעליון נמשך לתחתון כנ\"ל), וכמו ש[ה]אדם בעוה\"ז אין לו ערך אף לצומח וחי שבגעה\"ת כנ\"ל. ואין זה חידוש כלל דגם בעוה\"ז נמצא במין<sup data-n=\"8520\">1491</sup> האדם מעין זה, כמו שכבר הי' לעולמים בהגלות נגלות אור האלקי בנשמות צדיקי' ונביאים עד שהיו מופשטים מחומר גופם בתכלית ועלו למעלה ממדריגת המלאכים העליוני' כאברהם ומשה ואליהו וכה\"ג, עד שהי' ערך נפשות האדם לגביהם כבהמות ממש, וכמו שאברהם רדף אחר ד' מלכים<sup data-n=\"8521\">1492</sup> במתי מספר והיינו לפי שסר צלם<sup data-n=\"8522\">1493</sup> צל אדם מהם וברחו מפניו כמו איכה ירדוף אחד אלף<sup data-n=\"8523\">1494</sup> כו' (וכערך נה\"ב הגם שנק' אדם, לגבי נה\"א כידוע).\n<b>ודוגמא</b> לזה אנו מוצאים גם עכשיו בנש\"י בגופי' שיש בהם ב' מדרגות בחי' אדם ובחי' בהמה (והוא בחי' בהמ\"ה שבאדם) כמ\"ש וזרעתי את ב\"י<sup data-n=\"8524\">1495</sup> זרע אדם וזרע בהמה דגם שנק' נשמות שבאים בזריעה דאור העליון מ\"מ נק' זרע בהמה לגבי הנשמות העליונות מהם שנק' זרע אדם, וכמו שאנו רואים דנשמות ת\"ח שיש בהן דעת והשגה אלקית בבחי' גדלות המוחי' והמדות דאוי\"ר שכליי' כו' נק' זר\"ע אדם העליון כו', והנשמות דע\"ה אף שהן יריאים בקבלת עומ\"ש כשור לעול למשא ועבודה אלקי' בבחי' עשי' בפ\"מ לבד ואין בהן דעת והשגה אלקי' כלל וגם לא התפעלות אוי\"ר רק בבחי' אוי\"ר טבעי' כבהמה ממש רק שהוא בבחי' התפעלות אלקות כמרכבה דפני ארי' ושור כו' למעלה זהו שנק' זרע בהמה. ועכ\"ז יש בהן חילוקי מדרגות זו למעלה מזו עד שיש בזרע בהמה שעובדי' ה' בגופם למעשה לבד ג\"כ בחי' אדם שהוא קצת השגה אלקי' שמכיר לבוראו ומתפעל באוי\"ר מצד השגתו המצומצם בדוגמא דאופנים וחיות דיצי'<sup data-n=\"8525\">1496</sup> שהן בבחי' מדות דאוי\"ר בקטנות המוחי' כו', נק' בחי' בהמה ממש לגבי הנשמות שבבחי' גדלות המוחי' דחב\"ד שמתפשט ברחבות המדות (כשרפי' ונשמות דבריאה בגעה\"ע כו'). וכן עד\"ז גם נשמות דבריאה שבגעה\"ע בגדלות המוחי' ומדות דאדם נק' רק בחי' קטנות המוחי' ומדות דבהמה לגבי נשמות דאצי' ממש (כנשמות דפני אדם בבנ\"י במ\"ת שנק' אנפי זוטרי לגבי הארת פני הוי' דאדם הגדול שנק' אנפי רברבי<sup data-n=\"8526\">1497</sup> ) וכשרפים דבריאה לגבי בחי' המל' שנק' אדם תתאה. וכך גם עליות הנשמות דאצי' למעלה מן האצי' דמאציל עצמו וכידוע דכמו שאין ערך לבריאה עם האצי' כך אין ערך לאצי' לגבי",[["8520","1491","<b>במין</b>: ויז: בחי'. יא: (תיבה אחת קשה לפענחה) בחי'. יב: כבפנים."],["8521","1492","<b>שאברהם רדף אחר ד' מלכים</b>: לך יד, יד ואילך."],["8522","1493","<b>שסר צלם</b>: שלח יד, ט. ראה גם שע\"ת ח, ג. נה, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670567\" data-slug=\"torat-chaim\" data-id=\"2300670567\">תו\"ח נח עה, א</a>. מאמרי אדה\"א דברים ח\"ג ע' א'מה."],["8523","1494","<b>איכה ירדוף אחד אלף</b>: האזינו לב, ל."],["8524","1495","<b>וזרעתי את ב\"י</b>: ירמי' לא, כו [בדילוג — נסמן לעיל פ' משפטים רעז, א]. ראה גם לעיל שם ובהנסמן בריש המאמר שם."],["8525","1496","<b>דאופנים. . דיצי'</b>: ראה גם לעיל פ' בא צז, ג. וש\"נ."],["8526","1497","<b>אנפי זוטרי. . אנפי רברבי</b>: נסמן לעיל פ' משפטים רפז, ג."]]],[2300550849,"המאציל (וכזקנים שנחה עליהם רוחו של משה דכתיב ויאצל מן הרוח<sup data-n=\"8527\">1498</sup> כו' כמ\"ש במ\"א).\n<b>ומכל</b> זה וכיוצא בזה יובן ג\"כ ענין הבירור אחר בירור שיהי' לע\"ל כמו בימות המשיח ומימות <span data-k=\"pg\">תרמד</span> ּ המשיח לעוה\"ב דהיינו שגם שעכשיו בחי' מ\"ה דאד\"ם דנשמות דבי\"ע (בג' מדרגו' דנר\"נ בכלל) מברר לב\"ן דבהמה כפני שור ופני ארי' שנכללו ונעשו כמזון וחיות לבחי' פני אד\"ם בכל עולם לפי מה שהוא בבי\"ע עד נשמות ומלאכים דאצי' כנ\"ל הנה זהו בירור הראשון, אבל לע\"ל כמו בימוהמ\"ש שיומשך גילוי אורות העליונים שלפני האצי' שהן נשמות חדשות לגמרי<sup data-n=\"8528\">1499</sup> כידוע, יתבררו נשמות דאדם דעכשיו עוד הפעם והיינו מה שיוכללו בבחי' פני אדם דנשמות דלע\"ל [ו]הוא לפי שלא יחשבו אז רק [ל]בחי' בהמות וחיות בקטנות לגבי נשמות הגבוהות דלע\"ל (כביטול דנשמות דבריאה בפני אדם דאצי' ועד\"ז מאצי' למעלה יותר כנ\"ל) עד שנשמות דאדם דבריאה דעכשיו בגעה\"ע לא יהי' רק לבחי' מזון ומחי' כמזון גשמי' לנשמות שיהי' לע\"ל בבחי' פני אדם בעילוי המדרגה בערך נבדל ביותר עד שיצטרכו נשמות דעכשיו שנק' זרע אדם ליכלל בהם ממש כמו התכללות ובירור דמאכל ומזון הגשמי דבשר בהמה וצומח דחטה בנפש האדם עתה מטעם כל<sup data-n=\"8529\">1500</sup> הנ\"ל בענין עליות העולמות וד\"ל. ובזה יובן שיוכל להיות גם עכשיו מעין זה שיהי' לע\"ל והוא מה שא' דמיכאל כה\"ר מקריב נשמות ע\"ג המזבח דהיינו גם נשמות דבריאה שנק' בחי' פני אדם כמרכבה דבריאה מקריב אותם במזבח דאצי' לעלות לריח ניחוח להוי' דאצי' שזהו לאשתאבא בגופא דמלכא כמזון ולחם דקרבן בהמה גשמי' למטה במזבח שלמטה שנק' לחמי לאישי כו', והוא מטעם הנ\"ל כמו שיהי' לע\"ל בעליות העולמות דנשמות דפני אדם דעכשיו יב[ו]או לבירור[י'] ועלי' להיות נכללים בפני אדם שיהי' לע\"ל כמו בחי' בהמה באדם עכשיו, [כך] גם עתה נשמות דבריאה יוכללו במזבח דאצי' לאכילת אדם העליון דאצי' ע\"י מיכאל כה\"ר דאצי' כמו שמקריבי' בחי' פני שור כו' וד\"ל.\nובכ\"ז יובן ענין סעודת לויתן ושור הבר לע\"ל (אחר תחה\"מ שזה יהי' עלי' ב' אחר ימוהמ\"ש שזהו עלי' ובירור אחר בירור מגעה\"ת לגעה\"ע, כך הוא<sup data-n=\"8530\">1501</sup> מימוהמ\"ש לעוה\"ב ותחה\"מ הוא בין ימוהמ\"ש לעוה\"ב וכמ\"ש במ\"א בענין וחד חרוב<sup data-n=\"8531\">1502</sup> כו', ובעוה\"ב עצמו יש עלי' העולמות עוד כמו מגעה\"ע לאצי' ומאצי' למעלה יותר כמו ילכו מחי\"ל כו' וכמו שנשמות דאבות ומשה ואהרן עולים גם עתה בלי שיעור",[["8527","1498","<b>ויאצל מן הרוח</b>: בהעלותך יא, כה. ראה גם לעיל פ' שמות יא, ד."],["8528","1499","<b>נשמות חדשות לגמרי</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380106\" data-slug=\"likkutei-torah\" data-id=\"4001380106\">לקו\"ת צו ז, ג</a>. וש\"נ. מאמרי אדה\"ז תקס\"ז ע' לט. וע' רנד. שער האמונה ס, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680224\" data-slug=\"torat-chaim\" data-id=\"2300680224\">תו\"ח תולדות קנב, ב</a>. מאמרי אדה\"א בראשית ע' שנז. במדבר ח\"ב ע' תתמו. דרושי חתונה ח\"ב ע' תרלט ואילך. הנחות תקע\"ז ע' קפ. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316270481\" data-slug=\"or-hatorah-hb\" data-id=\"8316270481\">אוה\"ת בראשית (כ\"ג) ע' תפא</a>. ובהנסמן במקומות הנ\"ל."],["8529","1500","<b>כל</b>: יאיז: ליתא."],["8530","1501","<b>הוא</b>: יאיז: ליתא."],["8531","1502","<b>וחד חרוב</b>: ר\"ה לא, א. סנהדרין צז, סע\"א. ראה לעיל פ' בשלח רכא, ד ובהנסמן שם. מאמרי אדה\"ז תקס\"ה ח\"א ס\"ע תיב ואילך."]]],[2300550850,"למעלה בעצמות אוא\"ס כמ\"ש במ\"א). והענין הוא דודאי א\"א לומר דאכילה זו דלויתן ושור הבר הוא אכילה גשמי' אף שיהי' הלויתן מבורר מן הרע ופסולת וכן שור הבר (כמו שאכל אדה\"ר בשר ודגים בג\"ע קודם החטא וכה\"ג), דא\"א לומר שיהי' נשמות שיקומו בתחה\"מ [ב]חומר הגופני בבשר ודם [כ]גופי' דעכשיו שיהיו צריכים למזון גשמי באכילה גשמי' יהי' איך שיהי' (וגם הלא א' דהעוה\"ב אין בו או\"ש כלל רק הנשמות יושבין ונהנין כו'). וראי' ממשה שעלה להר לא אכל מ' יום<sup data-n=\"8532\">1503</sup> כלל (ומ\"ש ויחזו את האלקי' ויאכלו<sup data-n=\"8533\">1504</sup> כו' זהו אכילה רוחני' כמו [ש]אכלו המלאכים אצל אברהם<sup data-n=\"8534\">1505</sup> כו'). אלא צ\"ל שיהי' זה האכילה רוחני' שלא כדרך בירור מטו\"ר כאכילה גופני' דעכשיו (אלא כמו שא' אכלו ריעים לעילא כו'), והיינו שלויתן זה יהי' בו התלבשות והתכללות מכל הנשמות עליונות שהן מעלמא <span data-k=\"pg\">1290</span> ּ דאתכסיא (שנק' נוני ימא רבא<sup data-n=\"8535\">1507</sup> וכת\"ח שנק' דגים שבים<sup data-n=\"8536\">1508</sup> דחכמה) וכן שור הבר יהי' בו מכל הנשמות מעלמא דאתגליא<sup data-n=\"8537\">1506</sup> כפני שור שבמרכבה כו', ויהי' לבחי' מזון וחיות לנשמות הגבוהות ביותר שיהי' אז בערך נבדל כערך האדם עכשיו על מאכל צומח וחי עד שיאכלום אותם הנשמות שכלולי' בלויתן ויעלו אותן [ה]נשמות דצדיקים דלע\"ל כמו אדם מעלה עכשיו למזון ומאכל גשמי מטעם הנ\"ל וד\"ל.\n[כח]<b> וביאור</b> הדבר יובן מענין הנ\"ל בענין בירור אחר בירור שיהי' לע\"ל כמו בימוהמ\"ש וכן עכשיו בגעה\"ע כמו שמיכאל מקריב [נשמות] ע\"ג המזבח כו' שזהו שיהי' נשמות [ד]זרע אדם דעכשיו יחשבו אז לגבי נשמות הגבוהות בערך הנבדל ומרומם ביותר רק בבחי' פני שור דעכשיו שנק' זרע בהמה, וכמו שעכשיו מתברר בחי' נפש הבהמה שהיא בבחי' פני שור ליכלל להיות למזון בנשמות למזון [ל]פני אדם כמו שהמזון דבשר בהמה גשמי' נכלל בנפש האדם למטה כך גם נשמות דאדם דעכשיו יהי' למזון לנשמות דלע\"ל כנ\"ל. וכך הוא ענין סעודת דלויתן ושור הבר דהיינו שהן נעשי' בהגשמה מאורות [ו]ניצוצ[ות] קדושות העליונים דעולם המח' העליונה (כעונג המורגש במחשבה והשגה אלקי' בנשמות שבגעה\"ע דבריאה שנקרבי' ע\"ג המזבח ועולי' למזון למעלה בבחי' אדם דאצי' לאשתאבא בגופא דמלכא כו'), כנשמות דעכשיו שגם שמשיגים אלקות ומתענגים על ה' כו' נק' עונג מורגש וכתענוג גשמי שבמזון יחשב לגבי עונג הנעלם הרוחני דנשמות הגבוהות יותר, כערך הנבדל בעונג האלקי דג\"ע דעשי' על תענוגי' גשמיי' דעוה\"ז עד דגם עונג הרוחני דעוה\"ז כמו בכבוד וגדולה ועונג שבשכל כו' גשמי ממש יחשב לגבי עונג האלקי הרוחני שבג\"ע דעשי' אפי' בצו\"ד<sup data-n=\"8538\">1509</sup> דשם. ועד\"ז יחשב גם בחי' עונג האלקי שבנשמות דג\"ע דעשי' תענוג גשמי לגבי העונג הנבדל בערך",[["8532","1503","<b>ממשה. . לא אכל מ' יום</b>: ראה גם לעיל פ' בשלח קצד, ד. וש\"נ."],["8533","1504","<b>ויחזו את האלקי' ויאכלו</b>: משפטים כד, יא. ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקיט."],["8534","1505","<b>[ש]אכלו המלאכים אצל אברהם</b>: וירא יח, ח וברש\"י."],["8535","1507","<b>נוני ימא רבא</b>: זהר בלק קפח, א."],["8536","1508","<b>וכת\"ח שנק' דגים שבים</b>: כ\"ה בכ\"מ — ראה ברכות סא, ב. שער האמונה פה, ב ובהערה 10."],["8537","1506","<b>מעלמא דאתכסיא. . מעלמא דאתגליא</b>: נסמן לעיל פ' תצוה שנו, ד."],["8538","1509","<b>בצו\"ד</b>: בצומח ודומם."]]],[2300550851,"כמו בחו\"ב דנשמות דגעה\"ע וכן מגעה\"ע לעונג דחו\"ב דאצי' (שזהו שנק' לוית\"ן שהוא עונג אלקי המורגש בחו\"ב בהעלם דמח' בנשמות שנק' נוני ימא רבא כו'), ונשמות דעלמא דאתגליא הוא הע[ו]נג [ה]אלקי' שמורגש בהתפעלו' המדות דאוי\"ר בלב שהוא רוח ונפש כו' (והן ב' מיני נשמות צדיקים צ\"ע וצ\"ת שבמוחי' דגדלות בעומק ההשגה ובקטנות רק בהתפעלות הלב במורגש כנ\"ל). וזהו ענין סעודת לויתן ושור הבר לע\"ל לנשמות הצדיקי' הגבוהים ביותר ששרשם מעצמות התענוג הפשוט שבעצמות המאציל ממש (שנק' שעשועי המלך בעצמו ממש כו') כנשמות האבות ומשה ואהרן לע\"ל כו', שיהי' [מ]עונג האלקי המלובש בגשמי'<sup data-n=\"8539\">1510</sup> דחו\"ב [ומח'] ומדות דעכשיו (בג' מדרגות דנר\"נ דבי\"ע וגם למעלה באצי' כו') רק כמו בחי' עונג גשמי כמזון [בטעם גשמי] דדג ובשר שור לאדם שלמטה ויוכללו בהן ממש בבחי' האכילה רוחני') כמו<sup data-n=\"8540\">1511</sup> אכלו ריעים לעילא באו\"א דאצי' שזהו מבירורי' דנשמות דבי\"ע בהעלא' מ\"ן<sup data-n=\"8541\">1512</sup> במס\"נ שלהם בק\"ש ותפלה שעולה מבי\"ע לאצי' כל הנברר מזה בירור אחר בירור עד שנעשה כמו בחי' מאכל רוחני לחו\"ב דאצי' כו').\n<b>אך</b> עדיין יש להבין האיך אפשר שיהיו נשמות צדיקים דעכשיו שנק' פני אדם דמרכבה בבריאה יהיו רק [כמו] בחי' מזון גשמי דלויתן ושור לנשמות הצדיקים דלע\"ל שיהיו צריכים עלי' ובירור על ידם דוקא <span data-k=\"pg\">תרמה</span> ּ כמו שמתברר בהמה ע\"י אדם עתה, ואיך אפשר להיות מאדם בהמה כי הלא האדם הוא בצלם אלקי' כו'. ועוד דהלא שכר הנשמות דצדיקים דעכשיו הוא בעוה\"ב שהוא עולם התענוג העליון לנשמות כו' כידוע, וא\"כ גם הן יתענגו על ה' לעוה\"ב כמו אותן הנשמות הגבוהות שיקומו בתחה\"מ ולמה יהי' להן בחי' ירידה גדולה כזו שיהי' בבחי' מאכל ומזון כלויתן ושור הבר כו'. ועוד דא\"כ היכן הוא עיקר השכר בעוה\"ב מתו\"מ ועבודה האלקי' שעבדו כל ימיהם בעוה\"ז מאחר שלא יהי' רק כמו בחי' מזון גשמי לנשמות החדשות שלע\"ל שיעלו אותן ע\"י אכילה רוחני' זו כנ\"ל, וגם איך שייך ענין מזון ומאכל במעשה המצוה ותורה אור דנשמות דעכשיו שיהי' בהתלבשות ג\"כ בדג דלויתן ושור הבר כו'. אך הענין הוא בדרך כלל דאדרבה היא הנותנת משום דתו\"מ ואוי\"ר בהשגות אלקות במס\"נ דנשמות צדיקים דעכשיו צריכים להיות בחי' כלי להכיל ולקבל אור התענוג העצמי הפשוט דשעשועי' העצמי' דא\"ס ב\"ה בעוה\"ב, ע\"כ צריכים להיות תחלה בבירור ועלי' [שיתלבשו] כסעודת לויתן כו' ויהי' להן עלי' ע\"י נשמות צ\"ג העליונים שנבדל בערך מהם שיאכלום ויהי' להם למזון ואז יעלו להיות כלי לקבל השכר בעוה\"ב מתו\"מ ואוי\"ר במס\"נ שלהם שהי' להם בעוה\"ז (וזהו ענין תחה\"מ שלפני עוה\"ב שזהו כמו שהי' נה\"ד לפני",[["8539","1510","<b>בגשמי'</b>: יאיז: בנשמות."],["8540","1511","<b>רוחני') כמו</b>: שם: רוחני' (כמו."],["8541","1512","<b>מ\"ן</b>: ויאיז: ליתא. יב: כבפנים."]]],[2300550852,"געה\"ע שיטהרו בו הנשמות בטבילה בביטול המציאות כו', כך טהרה זו דתחה\"מ מטל העליון דנטיף<sup data-n=\"8542\">1513</sup> מע\"י<sup data-n=\"8543\">1514</sup> כו' שיב[ו]או בגופים טהורים וקדושים ויאכלו מסעודת לויתן שהן [ה]נשמות הגבוהות דימא רבא בפנימי' העונג דחו\"ב דאצי' כו' הנק' לויתן כמ\"ש בזהר על מה שאמר לויתן זה יצרת לשחק בו<sup data-n=\"8544\">1515</sup> כו'. וטהרה זו שבתחה\"מ כסעודת<sup data-n=\"8545\">1516</sup> לויתן ושור הבר הוא שיעשה<sup data-n=\"8546\">1517</sup> הכל למדריג' דעוה\"ב שנק' קדושה העצמי' ממש כידוע דטהרה מביאה לידי קדושה<sup data-n=\"8547\">1518</sup> כו') (כמ\"ש במ\"א בענין ברכה דאתה גבור כו' שמדבר בתחה\"מ לפני ברכה דאתה קדוש<sup data-n=\"8548\">1519</sup> כו').\n<b>ושרש</b> הענין הוא, לפי שמס\"נ דנש\"צ דעכשיו וגם התו\"מ שלהם נחלק לב' מדרגות בפנימי' וחיצוני' שהוא בחי' סתים וגליא, דמס\"נ בכוונה ורעו\"ד<sup data-n=\"8549\">1520</sup> ביח\"ע עולה לה' אחד ממש כמו אליך ה' נפשי אשא ממש כו', וכן הכוונה טובה באוי\"ר שכליי' [ו]בעסק התו\"מ וכ\"ש בהשג' הנסתר בפנימי' וסודות התורה שכ\"ז נק' בחי' סתים שהוא בהעלם דחו\"ב כמו שהוא בהעלם דרצון ותענוג העליון שבתו\"מ ותו\"מ שלמעלה באצי' כו'. ובודאי צריך להיות בירור אחר בירור מכל ההשגה ואוי\"ר ותו\"מ דנשמות הללו שהן מעלמא דאתכסיא אף בעלות[ם] מבריא' לאצי' ממש כו' [ו]לאשתאבא כו' במס\"נ, כי ודאי אין ערך כלל וכלל אף לפנימי' העונג [ה]אלקי שבפנימי' השגות חו\"ב דתורה שלהם הפנימי' לגבי עצמו' העונג דעצמו' א\"ס שבפנימי' הכתר כו'. וכ\"ש וק\"ו אותן נשמות שעבודתם באוי\"ר במס\"נ בחיצוני' ההשגה [ה]אלקי' עד שבאה במדות בלב בשר ברשפי אש בגבו' שבחום הטבעי שנשרף <span data-k=\"pg\">1292</span> ּ בשלהבת י\"ה כו' כשרפים וחיות הקדש בתוך הבירור<sup data-n=\"8550\">1521</sup> בהן יותר להפשיט<sup data-n=\"8551\">1522</sup> מבחי' יש וגסות דגבו' קשות, וכן עסק תו\"מ שלהם שצריך להיות בלבושי' גשמי' דק\"נ להפשיטם מגשמיות לרוחניות עד שיוכלו לעלות הכל למעלה וליכלל באח\"פ כו', ואז יהי' ראוי' לקבלת השכר בעוה\"ב שהוא גילוי אור התענוג הפשוט שבעצמות המאציל ממש כמו שהוא בעצמות התענוג שבתו\"מ<sup data-n=\"8552\">1523</sup> העצמיי'<sup data-n=\"8553\">1524</sup> [כמו שהן במהו\"ע ממש]. וזהו ענין סעודת לויתן ושור הבר שהן במדרג'<sup data-n=\"8554\">1525</sup> דבחי' סתים וגליא בתו\"מ ואוי\"ר שכליי' וטבעי' כמו שיהי' הכל לאחר הבירור בתכלית מעה\"ד טו\"ר ויתבררו כל העלאות מ\"ן דנשמות צדיקים לעלות למעלה באצי' בלי תערובות גשמיי' כלל, והיינו כל מס\"נ ואה\"ר בתענוגי' ובהשגות דחו\"ב והתפעלות במורגש הכל יב[ו]או בהתלבשות בב' מדרגות הללו דלויתן ושור הבר, ויתעלו",[["8542","1513","<b>דתחה\"מ מטל העליון דנטיף מע\"י</b>: ראה גם לעיל פ' שמות ז, ב ובהערה 312."],["8543","1514","<b>מע\"י</b>: ויאיז: ליתא. יב: כבפנים."],["8544","1515","<b>לויתן זה יצרת לשחק בו</b>: תהלים קד, כו. ראה זהר בשלח נ, ב. ביאוה\"ז שם. מאמרי אדה\"ז תקס\"ז כאן ע' רנד. מאמרי אדה\"א דרושי חתונה ח\"ב ע' תרמד. וש\"נ."],["8545","1516","<b>כסעודת</b>: יאיז: וסעודת."],["8546","1517","<b>שיעשה</b>: שם: שיעלה."],["8547","1518","<b>דטהרה מביאה לידי קדושה</b>: נסמן לעיל פ' תצוה שמה, ד."],["8548","1519","<b>ברכה דאתה גבור. . בתחה\"מ. . דאתה קדוש</b>: ברכות שמו\"ע. ראה דרך חיים פ\"מ ואילך."],["8549","1520","<b>ורעו\"ד</b>: זהר וירא ק, א."],["8550","1521","<b>בתוך הבירור</b>: יאיז: שצריך בירור. יב: שצריך להיות הבירור."],["8551","1522","<b>להפשיט</b>: יז: להפריש."],["8552","1523","<b>שבתו\"מ</b>: ויאיז: ליתא. יב: כבפנים."],["8553","1524","<b>העצמיי'</b>: ו: העצמי."],["8554","1525","<b>במדרג'</b>: שם: ב' מדריגות."]]],[2300550853,"ע\"י אכילה דנשמות הגבוהות שיקומו בתחה\"מ לע\"ל כאבות<sup data-n=\"8555\">1526</sup> ומשה ואהרן<sup data-n=\"8556\">1528</sup> ויוסף<sup data-n=\"8557\">1529</sup> ודוד שנק' ז' רועי\"ם<sup data-n=\"8558\">1527</sup> בכלל שאינו נחשב כל ענין עבודתם במס\"נ באה\"ר בתענוגים כו' לגבי מדר[י]גת[ם] בעונג הנעלם דעצמו' א\"ס ממש, רק כמו בבחי' עונג מורגש כמאכל דג ובשר ועי\"ז יוכלו כל הנשמות לקבל שכר דעוה\"ב וד\"ל).\n<b>ויובן</b> זה בתוס' ביאור עפ\"י הידוע בסדר ההשתל' דקו\"ח מעצמות א\"ס ב\"ה שאינו אלא כמו קו וחוט ממושך בצמצום אחר העלם האור דעצמו' א\"ס ממש בצמצום הראשון הנק' מקו\"פ וחלל ריקן כו', ובחי' קו\"ח זה הוא הבוקע ועובר כל ההשתלשלו' דאבי\"ע להאציל אורות מקיפים ופנימי' בכלל כמו עולם העקודי' ונקודים כו' עד ע\"ס דאצי' באו\"כ בבחי' התיקון עד שנמשך ג' עולמות דבי\"ע כו'. אבל למעלה מבחי' הקו\"ח הזה שהוא כמו מל' דא\"ס שלפני הצמצום אע\"פ שאינו רק גילוי אוא\"ס שנק' שמו הגדול כו' מ\"מ מתאחד בעצמותו ממש כמו אתה קדוש ושמך קדוש<sup data-n=\"8559\">1530</sup> כו' ומובדל בערך לגמרי אפי' להיות מקור למקור להשתלשלו' דקו\"ח רק ע\"י צמצום הראשון הנק' מקו\"פ כו' (וזהו כי עמך מקו\"ח מקור כל החיים העליונים שבקו\"ח עד סוף העשי' עמך טפל ובטל כו', אבל באורך נראה אור זהו בחי' אורך העצמי שהוא בחי' שעשועי המלך בעצמו ממש כמו שהוא בתענוג הפשוט שברצון העליון דמצות וח\"ע העצמי' דתוה\"ק נרא\"ה אור זה בעוה\"ב שנק' עדן כו', שמשם נמשך מקור כל התענוגי' העליוני' בקו\"ח עד מל' דאצי' בגעה\"ע [ו]בגעה\"ת כו' והכל מקיום המצות שהן פנימי' [ה]רצון ועונג העליון ממש שמזה יהי' גילוי האור בעדן דעוה\"ב כו'). ונמצא דרך כלל נק' זה הקו\"ח בחי' או\"פ ואור העצמו' דא\"ס שלפני הקו\"ח בחי' או\"מ הכללי שמקיף לכל ההשתל' דקו\"ח זה<sup data-n=\"8560\">1531</sup> בהשוואה א' ממש (ונק' טה\"ע).\n<b>והנה</b> שרש הראשון של כל הנשמות דעכשיו שהוא בבחי' התיקון דקו\"ח זה שנמשך באצי' ביחו\"ע דאו\"א וזו\"נ עד מל' דאצי' בבי\"ע להיות נשמות דבי\"ע מאין ליש, אבל הנשמות העליונות שיהי' לע\"ל הרי יומשכו מעצמות התענוג הפשוט שבעצמות א\"ס שלפני הקו\"ח שהוא מקיף וסובב הכלל (בבחי' טה\"ע) [כ]ז' הרועי' הנ\"ל ששרשן הי' בעצמות דמקיף הנ\"ל, כמו נשמת משה <span data-k=\"pg\">תרמו</span> ּ שאמר בו [כי] מן המ\"ע משיתיהו מח\"ע הקדומה דיה\"ק<sup data-n=\"8561\">1532</sup> שנק' מים שמעל השמים העליוני' כו', ונשמת",[["8555","1526","<b>כאבות</b>: ראה לעיל תיא, ג. וש\"נ."],["8556","1528","<b>ואהרן</b>: נסמן לעיל פ' תצוה שנו, א."],["8557","1529","<b>ויוסף</b>: ראה הנסמן בהערה 1526."],["8558","1527","<b>כאבות ומשה. . ודוד שנק' ז' רועי\"ם</b>: כסדר הזה הובא גם במאמרי אדה\"ז תקע\"א ע' כט וע' מב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680162\" data-slug=\"torat-chaim\" data-id=\"2300680162\">תו\"ח מקץ ריז, ב</a>. וראה בהנסמן במ\"מ לשם."],["8559","1530","<b>אתה קדוש ושמך קדוש</b>: תפלת שמו\"ע. ראה גם לעיל פ' משפטים חצר, ב."],["8560","1531","<b>זה</b>: יאיז: ליתא."],["8561","1532","<b>המ\"ע. . דיה\"ק </b>[יא: דים הקדמוני]: ראה גם לעיל פ' שמות מד, א. וש\"נ."]]],[2300550854,"אברהם מחסד דעצמות א\"ס וכן יצחק ויעקב שהוא בחי' ימי קדם<sup data-n=\"8562\">1533</sup> ) ויוסף ודוד [ב]בחי' יסוד [ו]מל' דא\"ס<sup data-n=\"8563\">1534</sup> וז\"ש אברהם לא יברך ברהמ\"ז בסעודת לויתן על יין המשומר משי\"ב<sup data-n=\"8564\">1535</sup> כו'<sup data-n=\"8565\">1536</sup> אלא דוד<sup data-n=\"8566\">1537</sup> כו' (כמ\"ש במ\"א). ולפ\"ז יכול להיות שנשמות דעכשיו ששרשן בקו\"ח הנ\"ל לא יחשבו אז רק לבחי' צו\"ח כפני שור לגבי נשמות דלע\"ל שיהיו מא\"מ דעצמו' ממש, כי באמת אין ערוך כלל לכל ההשתלשלו' דקו\"ח לגבי בחי' העצמו'<sup data-n=\"8567\">1538</sup> ממש יותר [מ]שאין ער[ו]ך לצו\"ח לגבי אדם, מאחר שגם בחי' א\"ק דהיינו [כ]אדה\"ר שנק' אדם דבריאה<sup data-n=\"8568\">1539</sup> שנברא מאין ליש אין לו ערך כלל לגבי הבורא שהוא אור א\"ס שבא בצמצום דקו\"ח שנק' חה\"ע בכלל ונשמת א\"ק זה נק' נשמתא דפרחא מחה\"ע<sup data-n=\"8569\">1540</sup> מאין ליש כו'. וא\"כ לפ\"ז לא יפלא כלל על היות הנשמ[ות] דעכשיו נחשבי' רק לבחי' מזון ומאכל בהגשמה כלויתן ושור הבר כנ\"ל לנשמות הצדיקי' שיהי' לע\"ל (וכמ\"ש במ\"א בשרש לוית\"ן זה שהוא פנימי' היחוד בעונג הרוחני העליון דאו\"א דאצי' דעכשיו שמשם שרש התולדות דנשמות דאבי\"ע דעכשיו, שלע\"ל בעליות העולמות יקרא רק בשם לוית\"ן כלוית\"ן שבים הגדול (שהן נוני ימא רבא כנשמות האבות<sup data-n=\"8570\">1541</sup> ונשמת רשב\"י ור\"ע<sup data-n=\"8571\">1542</sup> וכה\"ג) להיות בבחי' עונג גשמי לגבי נשמות דעונג הנעלם (שבטה\"ע כנ\"ל)<sup data-n=\"8572\">1543</sup>, וז\"ש לוית\"ן זה יצרת לשחק בו בשחוק ועונג העליון שיורד ונשפל בבירורי' דתו\"מ ואוי\"ר במס\"נ ביח\"ע דאו\"א וזו\"נ כו' וד\"ל. ודוגמא כזה שיהי' מעונג רוחני הנעלם<sup data-n=\"8573\">1544</sup> ביותר דעכשיו רק בבחי' עונג גשמי לע\"ל יובן ממה שהי' כבר לעולמים במזון דמן שנק' לחם מבחי'<sup data-n=\"8574\">1545</sup> השמים מבחי' טלא דפנימי' ע\"י<sup data-n=\"8575\">1546</sup> שהוא פנימי' אבא<sup data-n=\"8576\">1547</sup> ונתגשם ודכו במדוכה למזון ממש (והוא הטל שיחי' בו המתים לע\"ל שיבאו מרוחני' לגשמי' נשמות בגופים ממש), וכדוגמא זה יהי' לע\"ל שמבחי' ע[ו]נג היותר רוחני ועליון דעכשיו כפנימי' התענוג שבחו\"ב דאצי' בנשמות דאבי\"ע כו' לא יחשב אז רק בחי' ע[ו]נג גשמי להיות לבחי' מזון בצו\"ח בלבד וזהו ענין סעודת לוית\"ן (ומטעם הנ\"ל) וד\"ל.\n<b>וזהו</b> ואכלתם אכול ושבוע כו' שאכילה דלע\"ל כסעוד' לויתן לא יהי' כאכילה דעכשיו בבירורי' דרפ\"ח כו' שאין בה כדי שביעה לפי שהמשפיע לא יתמלא מן המקבל לפי שאין ערך ביניהן כלל, וזהו עכשיו כבירורי' דמ\"ה דאדם שמברר לב\"ן דבהמה [ב]פני שור כו'. אבל לע\"ל יהי' בחי' אד\"ם דעכשיו",[["8562","1533","<b>אברהם מחסד דעצמות א\"ס. . יצחק ויעקב. . ימי קד\"ם</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'שכא וס\"ע א'שפד."],["8563","1534","<b>ודוד. . [ו]מל' דא\"ס</b>: ראה גם ש\"א לג, ב."],["8564","1535","<b>יין המשומר משי\"ב</b>: נסמן לעיל פ' תצוה שסג, א."],["8565","1536","<b>כו'</b>: יב: (שבטה\"ע הנ\"ל). וראה בסמוך הערה 1543."],["8566","1537","<b>אלא דוד</b>: ראה סידור שער בהמ\"ז קב, ב ואילך. לעיל פ' בשלח קסא, א. וש\"נ."],["8567","1538","<b>אין ערוך כלל לכל ההשתלשלו'. . העצמו'</b>: ראה גם מאמרי אדה\"א דרושי חתונה ח\"ב ע' תרמד."],["8568","1539","<b>א\"ק. . שנק' אדם דבריאה</b>: ראה גם לעיל פ' בשלח קמה, ג. וש\"נ."],["8569","1540","<b>נשמתא דפרחא מחה\"ע</b>: ראה זהר תרומה קלח, א. מאמרי אדה\"א דברים ח\"ב ע' תסא."],["8570","1541","<b>נוני. . האבות</b>: ראה גם לעיל פ' יתרו רסה, א והערה 83. יב: הסבו' — ראה גם סידור שער בהמ\"ז קה, א. מאמרי אדה\"ז על מארז\"ל ע' קמד בהערה. שע\"ת צב, ד. מאמרי אדה\"א ויקרא ח\"א ע' רנב. במדבר ח\"ב ע' תקעא. דברים ח\"ג ע' א'כד."],["8571","1542","<b>ונשמת רשב\"י ור\"ע</b>: ראה גם לעיל פ' בשלח צט, ג. וש\"נ."],["8572","1543","<b>(שבטה\"ע כנ\"ל)</b>: יב: ליתא. וראה לעיל הערה 1536."],["8573","1544","<b>הנעלם</b>: ויאיביז: הנעלה."],["8574","1545","<b>מבחי'</b>: שם: מן."],["8575","1546","<b>דמן. . מבחי' טלא דפנימי' ע\"י</b>: ראה זהר בשלח סא, ב. סב, ב. בלק רח, א. (אד\"ז) האזינו רצב, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370400\" data-slug=\"torah-or\" data-id=\"3901370400\">תו\"א ויקהל פט, א</a>."],["8576","1547","<b>דפנימי' ע\"י. . אבא</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתסה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380918\" data-slug=\"likkutei-torah\" data-id=\"4001380918\">לקו\"ת נצבים מט, ד</a>. לעיל פ' שמות כג, א. וש\"נ."]]],[2300550855,"בבירור הב' למזון לאדם העליון ביותר אז א' ואכלתם אכול ושבוע באכילה בשביעה בלי שיעור כלל מצד עילוי המדרגות ביותר לאין שיעור כלל, וכל שעולה יותר יהי' אכילה למה שכבר נאכל ונשבע כמו מאכל שכבר נאכל שבא לבירור ב' מגשמיות לרוחני' יותר לפי שבמקום שעלה יותר גם הוא גשמי יחשב (כבירור דמאכל בקיבה להתברר בירור עוד לרוחני' שבדם ומן הדם יבורר עוד לחיות<sup data-n=\"8577\">1548</sup> [ש]בלב בחה\"ש<sup data-n=\"8578\">1549</sup>, ויבורר ויעלה עוד להיות למוחי' שבראש<sup data-n=\"8579\">1550</sup> והמוחי' דחו\"ב יעלו עוד לרצון ותענוג עד עצמות התענוג דיחידה כו' וכה\"ג). וזהו ואכלתם אכול כלומר מאכל שכבר נאכל בעליות נשמות <span data-k=\"pg\">1294</span> ּ שבגעה\"ת לגעה\"ע ומגעה\"ע לאצי' ממש), וכמו שיהי' בסעודת לויתן שנשמות שכבר הן בבחי' הבירור ותיקון דש' מ\"ה דאצי' יעלו לבירור ב' להיות מאכל לנשמות הגבוהות יותר שזהו כמאכל שכבר נאכל כו' וד\"ל.\n<b>ובכ\"ז</b> יובן ענין הקושי' הנ\"ל למה הותר האכילה בשבת אחר שהאכילה נק' בירור וגם למה הקרבנות הותרו בשבת כו' כנ\"ל, דהנה לפי המבואר למעלה בענין ואכלתם אכול כו' הרי לע\"ל יהי' עלי' [אחר עלי']<sup data-n=\"8580\">1551</sup> עד אין קץ למעלה (לפי שאוא\"ס למעלה עד אין קץ<sup data-n=\"8581\">1552</sup> כידוע) והכל בעילוי המדרגות בעונג העצמות כקדושים יהללוך סלה כו'), ובכלל כל מה שנברר ונאכל מכבר בו\"א שני דהוי עלמא אף בעליות העולמות עד געה\"ע ולמעלה יהי' בחי' אכילה עוד למה שכבר נאכל אחר תחה\"מ ומתחה\"מ יעלה עוד בעוה\"ב כנ\"ל בדרך זה דמה שכבר הוברר יאכל עוד. וזהו אכול ושבוע דגם ששבע מ[ה]אכילה הא' בעלותו למעלה יאכל אכילה ב' בבירור ב' וכן עד אין קץ, וזהו והללתם את שם ה' [ב]בחי' הילול זה עולה בעליות המדרגות בלי שיעור כלל כמו יהללוך סלה בלי הפסק כלל מטעם הנ\"ל דאין שיעור להפלאת והבדלת הערך בעילוי המדרגות מתחתון לעליון (כמו עד\"מ הטעות הדק<sup data-n=\"8582\">1553</sup> שיתוקן עדיין נק' טעות וצריך תיקון לבאי<sup data-n=\"8583\">1554</sup> לעומק השכל הנפלא ממנו ששם יחשב שכל וסברא ישרה זו לטעות כו', כמו בעיון אחר עיון בעומק שגם מה שהוברר בעיון הב' והג' יוקשה עליו בשכל העמוק ומופלא בערך כמו בהגיע לחכם הגדול יותר שזהו העלאה דכח השכל בעומק אחר עומק לאין שיעור. וכך בעליות העולמות בעומק העילוי שגם אור צח אוכם הוא<sup data-n=\"8584\">1555</sup> וכמו שמים לא זכו כו' (וכל הקרוב יותר יותר כלא חשיב כו' וכידוע בפי'",[["8577","1548","<b>לחיות</b>: ויא: להיות."],["8578","1549","<b>בחה\"ש</b>: בחלל השמאלי."],["8579","1550","<b>למוחי' שבראש</b>: ויאיז: בחי' מוחין לראש. יב: מזון למוחין בראש."],["8580","1551","<b>עלי' [אחר עלי']</b>: ויא: עילוי אחר עילוי."],["8581","1552","<b>שאוא\"ס למעלה עד אין קץ</b>: נסמן לעיל פ' תצוה שכג, א."],["8582","1553","<b>הדק</b>: יב ניתוסף בין השיטין: הרבה."],["8583","1554","<b>לבאי</b>: יא: לבוא. יז: לבא."],["8584","1555","<b>אור צח אוכם הוא</b>: ראה ת\"ז ת\"ע (קלה, ב)."]]],[2300550856,"יראה בוש\"ת<sup data-n=\"8585\">1556</sup> ). וזהו אשר עשה עמכם להפליא הפל\"א ופלא [פי' הפלא] זהו הנבדל בערך לגמרי ומושלל מכל השגה בשכל כמו כי יפלא ממך דבר<sup data-n=\"8586\">1557</sup> כו', וזהו עליי' השכל במקור השכל שאינו בא בהשג\"ה ונק' שכל הנעלם מכ\"ר<sup data-n=\"8587\">1558</sup>. וגם השכל המופלא הזה לא נק' מופלא בעלותו לגבי העליון ממנו שהוא מקור דפלאות חכ'<sup data-n=\"8588\">1559</sup> כמו עושה פל\"א<sup data-n=\"8589\">1560</sup>, וזהו להפליא מקור הפלא בהפלאה והבדלה אחר הפלאה בלי שיעור כלל. ועד\"ז והללתם את שם ה' בעילוי המדריגות בלי שיעור בהפלאות זו למעלה מזו וכידוע שאין קץ לעליות העולמות מקו\"ח בכלל בנ\"א יובלות<sup data-n=\"8590\">1561</sup> שכל שמיטה תעלה לשמטה שלמעלה ממנה<sup data-n=\"8591\">1562</sup> כו' וד\"ל.\n<b>וזהו</b> הטעם שלא יבוטלו הקרבנות גם אחר תחה\"מ שיהי' העילוי במדרגה בתכלית כי אין קץ לעליות וגם אז יצטרכו להיות עלי' עוד למעלה יותר כמו גם בעוה\"ב שאין להם מנוחה<sup data-n=\"8592\">1563</sup> שנאמר ילכו כו' (כי ו\"א שני ועוה\"ב אינו רק שמיטה א' לבד כמו ו' שנים יעבוד ו\"א שני'<sup data-n=\"8593\">1564</sup> כו') וכמו מגעה\"ע לאצי' ומאצי' למעלה עד אין שיעור כמיכאל מקריב נשמות כו' כנ\"ל. וזהו ג\"כ [הטעם] שהותרו הקרבנות בשבת ואין זה נק' בירור כלל כמו בימות החול, כי בשבת יש מעין העוה\"ב שכולו שבת שאז יהי' שלימות הבירורי' דרפ\"ח כו' אפילו בחיצוני' העולמות ואפי' [ב]בהמות וחיות (כידוע בענין שביעית<sup data-n=\"8594\">1565</sup> ), ומה שמקריבים קרבנות בשבת אין זו מלאכה ותיקון כלל אלא בבחי' העלאה שאחר העילוי דכבר הוברר בימות החול (כתפלה דשבת בתענוג עצמי ממה שכבר הוברר <span data-k=\"pg\">תרמז</span> ּ בעבודה בשכל ומדות בתפלת החול כו'). ואין זה כמברר ומפריד אוכל מפסולת (שאין פסולת כלל בשבת מעין העוה\"ב ממש ולכך אמר ולא פרש שבתכ\"ם דמטעם זה גם המותרות דלתיאבון נכלל בקדושה דשבת ואינו מזיק כלל כנ\"ל) רק כמו אוכלא דאפרת<sup data-n=\"8595\">1566</sup> שמפריד אוכל מאוכל ולא אוכל מפסולת כו', שזהו כמאכל שכבר נאכל בחול מעלי' אותו לעלי' יותר כנשמות דאדם שיעלו למזון לנשמות הגבוהות יותר כנ\"ל. ולכך אומרים [בשבת] בסעוד' דשבת דא היא סעודתא דע\"י ממש כמו שיהי' בחי' האכילה דלע\"ל בלוית\"ן כו', כך הוא בעונג גשמי דדגים ובשר בשבת דעונג הרוחני שבחול נעשה רק כעונג גשמי בשבת כנ\"ל ביום שכולו שבת דתחה\"מ ועוה\"ב בעליות",[["8585","1556","<b>יראה </b>[יאיז: ירא]<b> בוש\"ת</b>: ראה לעיל פ' שמות יב, ב הערה 549."],["8586","1557","<b>כי יפלא ממך דבר</b>: פ' שופטים יז, ח."],["8587","1558","<b>שכל הנעלם מכ\"ר</b>: נסמן לעיל פ' תצוה שמא, ד."],["8588","1559","<b>דפלאות חכ'</b>: ראה גם לעיל פ' שמות כא, ב. וש\"נ."],["8589","1560","<b>עושה פל\"א</b>: בשלח טו, יז."],["8590","1561","<b>בנ\"א יובלות</b>: ראה ש\"ך ר\"פ בהר. מאמרי אדה\"א בראשית ע' רסו. וש\"נ. שע\"ת ע, ג ובהערה 43. ש\"א ח, ב ובהערה 30."],["8591","1562","<b>שכל שמיטה. . למעלה ממנה</b>: ראה גם לעיל פ' שמות מג, א. וש\"נ."],["8592","1563","<b>בעוה\"ב שאין להם מנוחה</b>: ראה גם לעיל פ' שמות ד, ג. וש\"נ."],["8593","1564","<b>ו' שנים יעבוד ו\"א שני'</b>: משפטים כא, ב. ראה גם לעיל פ' משפטים רעח, ד. וש\"נ."],["8594","1565","<b>בענין שביעית</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670204\" data-slug=\"torat-chaim\" data-id=\"2300670204\">תו\"ח נח סא, ג</a> ובהערה 26 [ושם צ\"ל: במדבר ח\"ב ע' שלח. ח\"ג ע' א'רנח]."],["8595","1566","<b>אוכלא דאפרת</b>: ביצה ב, א."]]],[2300550857,"[העולמות] <b>לאין</b> שיעור. וזהו שנק' עולת שבת בשבתו לאין שיעור כו', וז\"ש בזהר דקוב\"ה ממש אתענג מענוגי' דישראל בסעודתא דשבת כו' כמו בעוה\"ב וד\"ל. וזהו אלה הדברים ל\"ט מלאכות שהי' במשכן דוקא לברר ולתקן שזהו עכשיו ונאסרו<sup data-n=\"8596\">1567</sup> בשבת להיותו בבחי' העלי' אחר הבירור וד\"ל. וכל הנ\"ל יובן בברכות המצות [מד\"ס]<sup data-n=\"8597\">1568</sup> שהן בחי' מקיפים ליתן כח ועוז לברר ולתקן בעבודה זו דמצות כמ\"ש לעבד\"ה כו', וזהו בא\"י א\"ק במצותיו לברר ולתקן להיות יחודא עילאה כו' באצי' או<sup data-n=\"8598\">1569</sup> בעוה\"ב יהי' ההעלאה בקדש העליון כנ\"ל<sup data-n=\"8599\">1570</sup>.\n<b>והנה</b> אחר שנתבאר<sup data-n=\"8600\">1571</sup> בענין סמיכות פ' שבת לפ' המשכן כנ\"ל, יש עוד להבין בטעם מה שאנו רואים ששינה משה כאן את הסדר מכמו שנצטווה, שהרי מבואר בפ' תרומה תצוה שנצטווה לעשות הכלים תחלה שהן הארון והשולחן ומנורה כו' כמ\"ש שם ועשו ארון<sup data-n=\"8601\">1572</sup> כו' ועשית שולחן<sup data-n=\"8602\">1573</sup> כו' ואח\"כ א' לו ואת המשכן תעשה<sup data-n=\"8603\">1574</sup> עשר יריעות כו' ואח\"כ [ה]קרשים<sup data-n=\"8604\">1575</sup> והפרכת<sup data-n=\"8605\">1576</sup> ומזבח החיצון<sup data-n=\"8606\">1577</sup> כו', ובכאן בפ' ויקהל כשבא משה לצוות על המעשה בפ\"מ לבצלאל וחכמים עושי המלאכה א' ויעשו כל חכם לב כו' את המשכן עשר יריעות<sup data-n=\"8607\">1578</sup> כו' ואח\"כ ויעש את הקרשים<sup data-n=\"8608\">1579</sup> [ויעש את הפרוכת<sup data-n=\"8609\">1580</sup> ] ואח\"כ ויעש בצלאל את הארון<sup data-n=\"8610\">1581</sup> ואח\"כ השולחן והמנורה ומזבח הזהב<sup data-n=\"8611\">1582</sup> ומזבח העולה<sup data-n=\"8612\">1583</sup> כו' הרי עשה למשכן תחלה ואח\"כ לכלים היפוך הסדר שנצטווה (וידוע מאמרז\"ל בזה<sup data-n=\"8613\">1584</sup> שאמר בצלאל למשה מנהג העולם שאדם בונה בית תחלה ואח\"כ מכניס כלים לתוכו כו' וא\"ל משה כך שמעתי מפי ה' בצ\"ל א\"ל היית וידעת<sup data-n=\"8614\">1585</sup> כו', ואין זה מובן דאיך אמר לו משה כך שמעתי כו'<sup data-n=\"8615\">1586</sup> מאחר שבפירוש שמע הצווי על הכלים תחלה כמבואר בפ' תרומה, וצריך לומר דגם זה שמע מפי ה' שלענין מעשה בפו\"מ צריך לעשות המשכן תחלה ואח\"כ כלים אעפ\"י שהקדים לומר למשה הכלים תחלה (עיין באוה\"ח<sup data-n=\"8616\">1587</sup> כמשי\"ת). והנה יותר מכ\"ז יש להפליא ולתמוה מאד על מה שבפ' תרומה ותצוה נאמר למשה מלאכת המשכן תחלה ואח\"כ בכלות הצווי על כל מלאכת המשכן נאמר לו מצות שבת (בפ' כי תשא ואתה דבר אל כו' אך את שבתותי תשמרו<sup data-n=\"8617\">1588</sup> כו') ורש\"י פי'<sup data-n=\"8618\">1589</sup> לומר שמלאכת המשכן אינה דוחה את השבת ע\"ש ולכך אמר אך כו' אבל עכ\"פ נצטווה משה על השבת אחר מלאכת המשכן, ובכאן שינה הסדר הזה",[["8596","1567","<b>שזהו עכשיו ונאסרו</b>: יאיב: ונאסרו עכשיו."],["8597","1568","<b>בברכות המצות [מד\"ס]</b>: ראה ברכות טו, א. לעיל פ' שמות סז, א. וש\"נ."],["8598","1569","<b>או</b>: יאיז: אך."],["8599","1570","<b>כנ\"ל</b>: ע\"כ נמצא בתו\"ח. ומכאן ואילך נדפס מח."],["8600","1571","<b>והנה אחר שנתבאר</b>: להבא לקמן ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' שלט ואילך."],["8601","1572","<b>ועשו ארון</b>: תרומה כה, י."],["8602","1573","<b>ועשית שולחן</b>: תרומה שם, כג."],["8603","1574","<b>ואת המשכן תעשה</b>: תרומה כו, א."],["8604","1575","<b>[ה]קרשים</b>: שם כו, טו."],["8605","1576","<b>והפרכת</b>: שם שם, לא."],["8606","1577","<b>ומזבח החיצון</b>: תרומה כז, א."],["8607","1578","<b>ויעשו. . את המשכן עשר יריעות</b>: ויקהל לו, ח."],["8608","1579","<b>ויעש את הקרשים</b>: ויקהל שם, כ."],["8609","1580","<b>ויעש את הפרוכת</b>: שם לו, לה."],["8610","1581","<b>ויעש בצלאל את הארון</b>: ויקהל לז, א."],["8611","1582","<b>השולחן והמנורה ומזבח הזהב</b>: ויקהל שם, י. יז. כה."],["8612","1583","<b>ומזבח העולה</b>: ויקהל לח, א."],["8613","1584","<b>בזה</b>: טזיז: במה."],["8614","1585","<b>מנהג העולם. . בצ\"ל א\"ל היית וידעת</b>: ברכות נה, א."],["8615","1586","<b>כו'</b>: טזיט ניתוסף: (עיין באוה\"ח). יז: כבפנים וראה בהערה הבאה."],["8616","1587","<b>עיין באוה\"ח</b>: תרומה כה, ט. טזיט: ליתא (כבהערה שלפנ\"ז). יז: כבפנים."],["8617","1588","<b>ואתה דבר. . אך את שבתותי תשמרו</b>: תשא לא, יג."],["8618","1589","<b>ורש\"י פי'</b>: בשינוי לשון."]]],[2300550858,"ואמר להם משה תחלה מצות השבת בא' אלה הדברים עד שבת שבתון כו' ואח\"כ א' להם מצות מלאכת המשכן והוא בא' ויא[מר] משה אל כל כו' קחו מאתכם תרומה לה' כו', והיה לו להקדים תחלה מצות מלאכת המשכן ואח\"כ לומר להם מצות שבת כפי הסדר שנצטווה. ועוד שינה במה שציוה על המשכן תחלה ואח\"כ כלים והוא נצטוה על הכלים תחלה ואח\"כ משכן כנ\"ל, ו[א\"כ] לפי\"ז נמצא ששינה משה הסדר בכל ג' אלה הדברים בשבת ומשכן וכלים מן הקצה לקצה שהוא נצטווה לעשות כלים תחלה ואח\"כ משכן ואח\"כ שבת והוא צוה על השבת תחלה [ואח\"כ משכן] ואח\"כ כלים כמבואר בפ' זו דויקהל וזהו פלא גדול לכאורה<sup data-n=\"8619\">1590</sup>.\n<b>אך</b> הנה כ\"ז יובן בהקדים תחלה להבין שרש ענין המשכן וכלים דהנה כתיב ועשו לי מקדש ושכנתי בתוכם [ד]הל\"ל בתוכו לשון יחיד וא' בתוכם לשון רבים דקאי בכנ\"י<sup data-n=\"8620\">1591</sup> שישכ[ו]ן בתוכם כאשר יעש[ו] לו מקדש דוקא, ולכאורה אין זה מובן דוודאי עיקר השראת השכינה הוא במקדש ומשכן והל\"ל ושכנתי בתוכו ולמה א' בתוכם דמה שייכות יש לגלוי אלקות בכנ\"י ע\"י שישכ[ו]ן במקדש דוקא, וצ\"ל בהכרח שעיקר ענין המשכן וכלים הוא בשביל השראות והמשכות אלקות בנש\"י וע\"ז מורה כל עיקר תבנית המשכן ותבנית כל כליו שהן בדוגמא וציור למשכן וכלים העליון כמ\"ש ככל אשר אני מראה אותך כו' כנ\"ל. והנה להבין זה דהנה תחלה י\"ל בדרך כלל בענין כללות המשכן שנחלק לב' מדריגות בבחינת או\"פ ובחי' או\"מ, בחי' או\"פ זהו שנתלבש האור<sup data-n=\"8621\">1592</sup> בכלים דמשכן כמו בארון ושולחן ומנורה וכה\"ג ובחי' או\"מ זהו שמתלבש בלבוש דיריעות עיזים כו' לאהל שזהו בחי' או\"מ דוקא. וכללות ב' המדריגות הללו הוא שנמשך ג\"כ בענין התו\"מ שלנו דהתורה הוא בבחי' מזון לנשמות<sup data-n=\"8622\">1593</sup> כמ\"ש ותורת\"ך בתוך מע\"י כו' וכתיב לכו לחמו בלחמי שנק' לחם ומזון ממש לנשמה וכמו כי אמרתך חייתני<sup data-n=\"8623\">1594</sup> כידוע, והמצות שעושה האדם בדברים גשמי[י'] נקרא בחי' לבוש<sup data-n=\"8624\">1595</sup> להלביש לנשמות בג\"ע כידוע בזוהר במ\"ש ואברהם [זקן] בא בימים באינון יומין עילאין שהן בחי' הלבושים דמצות וכמ\"ש והלך לפניך צדקיך כו' וביהושע כה\"ג א' הלבש אותו<sup data-n=\"8625\">1596</sup> מחלצות כו'. והיינו ענין היריעות שהי' במשכן שהן בבחינת לבושים לכסות על הקדש שבפנים כמו הלבוש דמעשה המצות שהן בחי' מקיפים לנר\"ן, וענין הכלים כארון ושולחן כו' זהו כמו בחי' מזון שנק' או\"פ בכלי לנשמה כמו האור הבא בגלוי בארון בלוחות כו' וד\"ל.",[["8619","1590","<b>לכאורה</b>: בכת\"י זה נכפלה תיבה זו."],["8620","1591","<b>בתוכו. . בתוכם. . בכנ\"י</b>: ראה אלשיך תרומה כה, ח. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261083\" data-slug=\"likkutei-sichot\" data-id=\"1300261083\">לקו\"ש בא (כרך כו) ע' 83</a>. וש\"נ. טור יהלום — ליו\"ד — סשס\"ג, ס\"ז. לעיל פ' תרומה דש, ג. תצוה שנג, ב."],["8621","1592","<b>האור</b>: טזיט: ליתא. יז: כבפנים."],["8622","1593","<b>דהתורה. . מזון לנשמות</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ\"ה</a> (ובמ\"מ הגהות והע\"ק שם)."],["8623","1594","<b>כי אמרתך חייתני</b>: תהלים קיט, נ."],["8624","1595","<b>והמצות. . לבוש</b>: ראה גם תניא שם."],["8625","1596","<b>אותו</b>: טז: אותך."]]],[2300550859,"<b>ולהבין</b> דבר זה הנה יש להקדים [תחלה] ענין הכללי ביחוד עצמו' א\"ס ב\"ה שלמעלה ממקור ההשתל' דאבי\"ע וכמ\"ש כי עמך מקור חיים כו' ולכך אין בו שנוי כלל מקודם ההשתל' באצי' ובריאה לאח\"כ וכמו שאנו או' אתה הוא<sup data-n=\"8626\">1597</sup> כו' כידוע במ\"ש אני הוי' לא שניתי<sup data-n=\"8627\">1598</sup>, והטעם הוא כי אם היה האור והשפע בא ונמשך להשתל' באבי\"ע מבחי' מהו\"ע ית' ממש הי' ראוי שיפול בזה ענין שנוי מקודם ההשפעה וההמשכה לאחר ההשפעה הזאת כו', אבל באמת אין האור והשפע זו נמשך ממהו\"ע ית' ממש רק מבחי' הארה דהארה מבחי' האור וזיו דשם מלכותו<sup data-n=\"8628\">1599</sup> העצמ[י]ת בלבד שאינו רק בחי' התפשטות וגילוי דגילוי הבא בבחי'<sup data-n=\"8629\">1600</sup> אותיות דשמו הגדול לבד, וכמ\"ש כי נשגב שמו לבדו הודו על ארץ [כו'] פי' שמו העצמי זהו בחינת מל' דאצילות כמו שהוא טרם שנמשך להיות מל' בעולמות לה[ו]ות מאין ליש וכן ברום המעלות במל' דא\"ס קודם שנמשך בקו\"ח כמ\"ש אני ראשון ואני אחרון כידוע, ובחי' מדה זו דמל' נק' שמו לבדו שזהו שם מלכותו וכמ\"ש דקודם שנבה\"ע היה הוא ושמו בלבד כו', ובחי' הארה דהארה שנק' הודו של שמו זה הוא שנעשה ונתצמצם להיות מקור לכל ההשתל' דאבי\"ע והוא מ\"ש מל[כותך] מל' כ\"ע, דהיינו רק במה שנק' שמו עליהם בהתפשטות שם המלך על אנשי מדינתו שבממשלתו ומלכותו עליהם מתקיימת כו' וכמ\"ש ישתבח שמך לעד מלכינו<sup data-n=\"8630\">1601</sup> כו' ונקרא מלך יחיד חי העולמים<sup data-n=\"8631\">1602</sup> [או יחיד חי העולמים] מלך<sup data-n=\"8632\">1603</sup> כמ\"ש במ\"א וד\"ל.\n<b>ונמצא</b> מובן שיש במדת<sup data-n=\"8633\">1604</sup> שם ומל' הנ\"ל ב' מדריגות ושניהם בבחי' מקיף ולבוש כמ\"ש ה' מלך גיאות [לבש] כו' והוא בחי' לבוש [ד]מל', א' ב[בחי'] פנימי' ועצמיות דמדה זו כמו שהוא מצד רוממות והתנשאות העצמות (שנק' טה\"ע ). והב' בחי' הצמצום דמדה זו להיות מל[ך] על עם בהתנשאות מ[ו]גבלת על העולמות לבד (וכידוע שזהו מלך מרומם לבדו מאז וכמו נכון כסאך מאז כו' ואח\"כ מלך גיאות לבש כו' להיות מתנשא מימו\"ע לבד כו' (וזהו טה\"ת ) ונקרא זו\"ן<sup data-n=\"8634\">1606</sup> שמים ושה\"ש<sup data-n=\"8635\">1605</sup> כו'<sup data-n=\"8636\">1607</sup> ). וזהו עוט\"ה או\"ר כשלמ\"ה בחינות טה\"ע דמל' דא\"ס קודם הצמצום (שנקרא שה\"ש) נוטה שמים כיריעה (בחי' מקיף לעולמות בחי' טה\"ת) שיתנשא על עולמות כו'). וזהו [ה]הפרש בכלל בין [בחי'] פנימי' מל' שמים דלעילא כמו בקעומ\"ש בתו\"מ לנש\"י כמו במ\"ת שמלכותו ברצון קבלו כו' וכמ\"ש להודיע לבני האדם כו' וכבוד הד\"ר מלכותו, הפנימי שנק' לבוש מל' (כמו יביאו לבוש מל' אשר לבש בו המלך במ\"ת<sup data-n=\"8637\">1608</sup> כו' כמ\"ש",[["8626","1597","<b>אתה הוא</b>: תפלת השחר."],["8627","1598","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו. ראה גם לעיל פ' תרומה שה, א."],["8628","1599","<b>דשם מלכותו</b>: טזיט: דמל'. יז: כבפנים."],["8629","1600","<b>בבחי'</b>: טזיט: מבחי'. יז: כבפנים."],["8630","1601","<b>ישתבח שמך לעד מלכינו</b>: ברכת ישתבח. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680055\" data-slug=\"torat-chaim\" data-id=\"2300680055\">תו\"ח ויחי רמ, א</a>. מאמרי אדה\"א הנחות תקע\"ז ע' קפב."],["8631","1602","<b>מלך יחיד חי העולמים</b>: ראה גם לעיל תג, ג."],["8632","1603","<b>מלך יחיד. . יחיד חי העולמים] מלך</b>: ברכת ישתבח וברכת ברוך שאמר. ראה גם לעיל פ' וארא סט, ג. וש\"נ."],["8633","1604","<b>במדת</b>: יט: בבחי'."],["8634","1606","<b>זו\"ן</b>: טזיזיט: ליתא."],["8635","1605","<b>טה\"ע. . טה\"ת. . שמים ושה\"ש</b>: ראה גם לעיל פ' בשלח קעח, ג. וש\"נ."],["8636","1607","<b>כו'</b>: שם: ליתא."],["8637","1608","<b>יביאו לבוש מל'. . במ\"ת</b>: אסתר ו, ח. ראה גם לעיל פ' תצוה שלא, ד. וש\"נ."]]],[2300550860,"במ\"א) ובין חיצוניות המל' בהתפשטות המל' על המלאכים בהתנשאות חיצוניות. ומפנימי' המל' לנש\"י בעול תו\"מ כמו בר\"ה שאו' י\"פ דמלכ[י]ות שתמליכוני עליכם<sup data-n=\"8638\">1609</sup> דוקא (ויש בזה ב' מעלות על המלאכים, א' מצד בחי' אדם דנשמות שהן בצלם אלקים [ו]המל' על נשמות יותר עליון ממל' על ארי' ושור וכה\"ג. [והב'] מצד שהוא בפנימיו' הרצון והחכ' דתו\"מ שבחי' קעומ\"ש זה בקיום התו\"מ שרשו בפנימיות ועצמיות דמל' דא\"ס ממש כמ\"ש במ\"א) ולע\"ל יתעלה<sup data-n=\"8639\">1610</sup> מבחי' פנימיות<sup data-n=\"8640\">1611</sup> דלבוש מל' שמלובש עתה בחיצוניות על נש\"י בעול תו\"מ וזהו [ו]ע\"י יתיב כו' וה' ימלוך לע\"ו שיאיר אפס קצהו במשיח כידוע. וזהו ענין המקיפים דיריעות המשכן בכלל שהוא בחי' מקיף הכללי דבחי' לבוש מל' הפנימי' שע\"ז א' עוטה אור כשלמה נוטה שמים כיריעה שמתלבש בחי' הפנימיות דמל' בחיצוניות דיריעה להיות בחי' מקיף על האו\"פ דכלים שבמשכן שהן בבחי' פנימיות ועצמיות דתורה ונש\"י (כמשי\"ת).\n<b>והנה</b> לכאורה יש סתירה לענין הנ\"ל בשרש המצות שנק' בחי' לבושים (שכללותם בקעומ\"ש דמצות נק' לבוש מל' הפנימיות כנ\"ל) שהן בחי' מקיפים ובאמת מבואר בזוהר בכמה דוכתי שרמ\"ח מ\"ע נק' רמ\"ח אברים דמלכא<sup data-n=\"8641\">1612</sup> ופי' אבר זהו בחי' כלי מוגבל להכיל האור וחיות שבו כידוע, וא\"כ המצות בבחי' או\"פ מוגבל בכלי שהן רמ\"ח אברים כו'. אבל הענין הוא דאדרבה לפי שהמצות הן בחי' לבושים ומקיפים כנ\"ל ע\"כ הן מתלבשים בבחי' אברים, כי גם האברים אינם בבחי' כלי ממש אלא בבחי' לבוש דוקא להלביש ולהעלים ולכסות על האור וחיות שבו והיינו כמו העור ובשר שא' עור ובשר תלבישני<sup data-n=\"8642\">1613</sup> הרי נק' לבוש [ו]כן העצמות מלבישים לכל האור וחיות הפנימי' בעצם<sup data-n=\"8643\">1614</sup>, כי האור וחיות הרי הוא רוחני ומתלבש ומתעלם באברים המלבישים אותו ומעלימי' בתוכן כדוגמת הלבוש ממש מבגד גשמי שמכסה ומעלים ממש לגופו של אדם כך גם הרצון<sup data-n=\"8644\">1615</sup> מלביש לנפש הרוחניות שבו כידוע (אלא שמתאחד יותר עם הנפש כחכ' בכלי המוח והראי' בעין ומהתעבות האור נעשה הכלי<sup data-n=\"8645\">1616</sup> שהוא הלבוש כי שרש הכלים במקיפים<sup data-n=\"8646\">1617</sup> כידוע). וכך יובן ג\"כ בענין המצות דגם שבאמת נק' לבושים שמתלבש בהן גילוי אור רצה\"ע וחכ' כו' כמו בלבוש מל' בכלל אבל בפרט הן בחינות רמ\"ח אברים שהם ג\"כ בחי' לבוש בפרט להלביש לנשמ' האלקית כמו גופו של אדם שמכסה ומלביש",[["8638","1609","<b>שתמליכוני עליכם</b>: ר\"ה טז, סע\"א. לד, ב."],["8639","1610","<b>יתעלה</b>: טזיזיט: יתגלה."],["8640","1611","<b>פנימיות</b>: טז: מקיפי'."],["8641","1612","<b>שרמ\"ח מ\"ע. . אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). שע\"ת עב, ג הערה 17."],["8642","1613","<b>עור ובשר תלבישני</b>: איוב י, יא."],["8643","1614","<b>בעצם</b>: טזיזיט: דאדם."],["8644","1615","<b>הרצון</b>: טזיט: הגוף. יז: כבפנים."],["8645","1616","<b>ומהתעבות האור נעשה הכלי</b>: ראה ע\"ח (שער העקודים) ש\"ו, פ\"ג. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תשנג. מאמרי אדה\"א נ\"ך ע' קלד. וש\"נ."],["8646","1617","<b>שרש הכלים במקיפים</b>: ראה גם שעה\"י קלו, ב. ש\"א עח, א. מאמרי אדה\"א נ\"ך שם. וש\"נ. לעיל פ' שמות מו, א ובהנסמן שם."]]],[2300550861,"[ל]<b>הנפש</b> כו' כנ\"ל. וכמו\"כ למעלה באדם העליון דאצילות נק' רמ\"ח אברים דמלכא שהן רמ\"ח מ\"ע העליונים שנק' מצו\"ת ממש כמ\"ש שקדשנו במצותי\"ו<sup data-n=\"8647\">1618</sup> שהן ג\"כ בחי' לבוש שמתלבש הקב\"ה בהן כו' (וכמ\"ש הקב\"ה מניח תפילין ומתעטף בציצית<sup data-n=\"8648\">1619</sup> כמ\"ש לבושי' כתלג כו' כידוע).\n<b>ולהבין</b> זה בתוס' ביאור הנה יש ראי' כלל[י'] לזה ממצות ציצית וגם ממצות תפילין, דהנה מצות ציצית עיקר ענינה אינו אלא בחי' המשכות אור מקיף דבחי' לבוש מל' שמים דלעילא כו' הרי בהתעטפו בטלית זהו שמקבל וממשיך על נפשו פרישו<sup data-n=\"8649\">1620</sup> דיראת שמים<sup data-n=\"8650\">1621</sup> שזהו בחי' התנשאות העצמות דסוכ\"ע הכללי בעיטוף זה (וראיה לזה ממה שאו' בעיטוף הטלית<sup data-n=\"8651\">1622</sup> פסוקים [ד]כי עמך מקור חיים כו' כמ\"ש במ\"א בפ' ציצית), וכמו שמקבל ע\"ע מל' כמו שום תשים עליך מלך כו' מלך ממש שהיא מדת מלכותו ית' הפנימיות שנמשך רק לקיום כל המצות שהן פנימי' רצונו כנ\"ל, וכמו שמקבלים עול מלכות לקיים גזירתו בכל אשר יצוה לבטל הרצון מפני רצונו כו', שמקבלה זאת נמשך הכח ועוז לכל קיום הרצון, כך בקעומ\"ש שבטלית שמעטף על ראשו זהו בחי' מקיף כללי לכל המצות שיקיים בביטול רצון מפני רצון ה'. וז\"ש וראיתם אותו שהוא התכלת<sup data-n=\"8652\">1623</sup> (שזהו לבוש מל' דלעילא שהוא בבחי' מקיף כמו שהתכלת דומה לים<sup data-n=\"8653\">1624</sup> [וים] דומה לרקיע שזהו נוטה שמים כיריעה כו') וזכרתם את כו', ולכך מצות ציצית שקולה [כ]נגד כל המצות<sup data-n=\"8654\">1625</sup> (כידוע דציצית עם הקשרים<sup data-n=\"8655\">1626</sup> וח' חוטין גי' תרי\"ג<sup data-n=\"8656\">1627</sup> [כו']. ומכח זה דקעומ\"ש במקיף דעיטוף הטלית שהוא פרישו דמל' שמים העליון נמשך כח ועוז לכל יח\"ע שבכל[ל] כמו בק\"ש ובפרט בכל מצוה ותורה אור כו', להיותו בבחי' לבוש מל' הפנימיות שכולל כל העומ\"ש שבכל מצוה ומצוה בפרט (ונק' כת\"ר מל' שלמעלה גם מכל רצון בפרט שמאיר ונמשך בכל מצוה בעשותה בקעומ\"ש כו' מאחר שזהו בחי' ביטול כללי לעצמות באדה\"ר<sup data-n=\"8657\">1628</sup> דמצות שא' ונעשה רצונו כמו שבמ\"ת א' כל אשר דבר ה' נעשה ועדיין לא שמעו רצונו שזה מגיע למעלה בעצם מקור כל רצון<sup data-n=\"8658\">1629</sup> כמ\"ש במ\"א).\n<b>ועד\"ז</b> יובן גם במצות תפילין שהוא ג\"כ מבחי' או\"מ כטלית רק שהטלית הוא בבחי' מקיף כללי והתפילין הן בבחי' המקיפים להמוחין שבראש שנמשך ממקיף הכללי להיות ג\"כ",[["8647","1618","<b>שקדשנו במצותי\"ו</b>: נוסח ברכת המצות."],["8648","1619","<b>הקב\"ה מניח תפילין ומתעטף בציצית</b>: ראה ר\"ה יז, ב. ברכות ו, א. מאמרי אדה\"א ויקרא ח\"ב ע' תסז. וש\"נ."],["8649","1620","<b>פרישו דמל' שמים</b>: ראה זהר (סבא) משפטים צז, ב. לעיל פ' בשלח קלח, א הערה 282."],["8650","1621","<b>דיראת שמים</b>: טז: דמ\"ש. יז: כבפנים. יט: דמל' שמים."],["8651","1622","<b>שאו' בעיטוף הטלית</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תרטו. אוה\"ת תשא (כרך ח) ע' ג'קו."],["8652","1623","<b>וראיתם אותו שהוא התכלת</b>: שלח טו, לט. ראה זהר תרומה קנב, ב. מאמרי אדה\"א דברים ח\"ד ע' א'תו. וש\"נ."],["8653","1624","<b>שהתכלת דומה לים</b>: ראה חולין פט, א. מאמרי אדה\"ז תקס\"ד ע' סח ובהנסמן במ\"מ לשם."],["8654","1625","<b>ציצית שקולה [כ]נגד כל המצות</b>: נדרים כה, א."],["8655","1626","<b>הקשרים</b>: טז: ה' קשרים."],["8656","1627","<b>דציצית. . תרי\"ג</b>: ראה תנחומא קרח יב. שע\"ת לח, ד הערה 41."],["8657","1628","<b>באדה\"ר</b>: טזיזיט: בעה\"ר בעל הרצון — ראה לעיל הערה 817."],["8658","1629","<b>כמו שבמ\"ת. . מקור כל רצון</b>: ראה גם לעיל תיב, ג."]]],[2300550862,"בבחי' כולל לכל האברים, כי הלא הענין במכו[ו]ן הכללי שבמצות הנחת תפילין בראש ובזרוע הוא להיות המשכות או\"מ לד' מוחין דחו\"ב וחו\"ג<sup data-n=\"8659\">1630</sup> ע\"י הדעת שמחלק<sup data-n=\"8660\">1631</sup> כו' כידוע, והוא במה שכותבין ד' פרשיות בקלף ודיו בד' בתים בהנחתן ע\"ג הראש בבחי' בליטה<sup data-n=\"8661\">1632</sup> ע\"ג הראש להורות שהן בחי' מקיפים<sup data-n=\"8662\">1633</sup> דחו\"ב שבראש בהעלם ליתן כח ועוז לחו\"ב בג[י]לוי אור ההשגה ביח\"ע בק\"ש. והטעם הוא לפי שבתפילין בקלף ובתים<sup data-n=\"8663\">1634</sup> נק' בחי' לבוש<sup data-n=\"8664\">1635</sup> כמו פארך<sup data-n=\"8665\">1636</sup> כו' להיותן בלבוש גשמי שאין בהן גילוי אור בפנימיות כלל, כמו בפ' קדש שהוא באור החכ'<sup data-n=\"8666\">1637</sup> שאין בפ' זו הכתובה בקלף ודיו גשמיות בחינת ג[י]לוי אור החכ' דאצילות ממש רק בהעלם בבחי' מקיף דאור הח\"ע ששורה על הלבוש כמ\"ש בתפילין שבראש כי שם הוי' נקרא עליך<sup data-n=\"8667\">1638</sup> [עלי\"ך] בבחי' מקיף ע\"ג המוחין שבראש, ע\"כ בהניח אדם התפילין בראשו מלביש לבוש זה דתפילין בבחי' מקיף על מוחו מבחי' מקיפים דחו\"ב שבמקיף הכללי (שהן ל\"ב חוטי דציצית שכוללים רמ\"ח מ\"ע ושס\"ה ל\"ת<sup data-n=\"8668\">1640</sup> בחוטי לבן וחוטי תכלת שהן חו\"ג בכלל שנחלק מחו\"ב בל\"ב נ\"ח<sup data-n=\"8669\">1639</sup> דמקיף הכללי דעוטה אור כשלמה כו' כמ\"ש במ\"א), ועכ\"ז נק' פושעי ישראל בגופם במי שאין מניח תפילין<sup data-n=\"8670\">1641</sup> כו' להיותם כוללים כל הרמ\"ח מ\"ע שנקרא רמ\"ח אברים כו' וד\"ל.\n<b>ועכ\"פ</b> מב' מקיפים דטו\"ת בכלל ובפרט במקיף דמוחין (וכן בתפילין שביד נגד הלב זהו מקיף דמדות שבלב כידוע) וכמ\"ש בס' היראה שזהו לשעבד המוחין והמדות<sup data-n=\"8671\">1642</sup> שנק' אדם ולכך צריך שלא יסיח דעתו מן התפילין<sup data-n=\"8672\">1643</sup> כו' וכמ\"ש וקשרתם לאות על ידיך ולטוטפת<sup data-n=\"8673\">1644</sup> כו') יש ראי' מהם שכל פרטי המצות הגם שנקרא רמ\"ח אברים הן מבחי' מקיפים דבחי' לבושים דוקא וכללותם הוא בחי' לבוש מל' הפנימי' הנ\"ל הנקרא הדר מל[כותו] כנ\"ל וד\"ל (ועוד ראי' ממצות צדקה שהוא שקולה [כ]נגד כל המצות<sup data-n=\"8674\">1645</sup> וכללות המצות נק' בשם צדקה כמ\"ש וצדקה תהיה לנו<sup data-n=\"8675\">1646</sup> כו' והוא בבחי' לבוש דוקא [ו]כמו וילבש צדקה כשריון כו' וכן או' לבושו צדקה<sup data-n=\"8676\">1647</sup> כו' וזהו והלך לפניך צדקיך כבוד ה' יאספך כו' במקיף דלבוש מל' הנ\"ל וד\"ל). וז\"ש דוד שהי' מרכבה לבחי' מל' דאצילות כידוע (ושרש[ו] הראשון בבחי' מל' דא\"ס הפנימי' הנ\"ל שיאיר במשיח",[["8659","1630","<b>לד' מוחין דחו\"ב וחו\"ג</b>: ראה זהר ואתחנן רסב, א. סידור שער התפלה ז, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670598\" data-slug=\"torat-chaim\" data-id=\"2300670598\">תו\"ח נח עח, ד</a> הערה 34."],["8660","1631","<b>הדעת שמחלק</b>: נסמן לעיל פ' תצוה שנג, א הערה 462."],["8661","1632","<b>בבחי' בליטה</b>: טזיט: בבליטה. יז: כבפנים."],["8662","1633","<b>בליטה. . מקיפים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670492\" data-slug=\"torat-chaim\" data-id=\"2300670492\">תו\"ח נח נה, ג</a>. לעיל פ' שמות מט, א."],["8663","1634","<b>ובתים</b>: טזיט: ו(ב)דיו. וראה בסמוך שו\"ה שאין. יז: כבפנים."],["8664","1635","<b>לבוש</b>: טזיט: פאר. יז: כבפנים."],["8665","1636","<b>פארך</b>: יחזקאל כד, יז. ראה גם לעיל פ' יתרו רנט, ג ובהערה 140."],["8666","1637","<b>בפ' קדש. . החכ'</b>: בא יג, א ואילך. ראה זהר שבהערה 1630."],["8667","1638","<b>כי שם הוי' נקרא עליך</b>: תבוא כח, י."],["8668","1640","<b>רמ\"ח מ\"ע ושס\"ה ל\"ת</b>: מכות כג, סע\"ב."],["8669","1639","<b>ל\"ב חוטי דציצית. . בל\"ב נ\"ח</b>: ראה זח\"ג (תוספת) שא, א. מאמרי אדה\"א בראשית ע' שצד. וש\"נ."],["8670","1641","<b>פושעי ישראל בגופם. . תפילין</b>: ר\"ה יז, א."],["8671","1642","<b>בתפילין. . בס' היראה. . לשעבד המוחין והמדות</b>: ראה שו\"ע (ואדה\"ז) הל' תפילין סכ\"ה, ס\"ה (סי\"א). תניא פמ\"א."],["8672","1643","<b>שלא יסיח דעתו מן התפילין</b>: ראה שו\"ע אדה\"ז שם רסכ\"ח. ראה גם מאמרי אדה\"ז על ענינים ס\"ע עדר. אוה\"ת ואתחנן ס\"ע שדמ ואילך. ס\"ע שמה ואילך. ע' שלד."],["8673","1644","<b>וקשרתם. . ולטוטפת</b>: ואתחנן ו, ח [ושם: והיו לטטפת]."],["8674","1645","<b>צדקה שהוא שקולה. . המצות</b>: ב\"ב ט, א."],["8675","1646","<b>וצדקה תהיה לנו</b>: ואתחנן ו, כה. ראה לעיל פ' שמות יד, א. וש\"נ."],["8676","1647","<b>לבושו צדקה</b>: פיוט (לימים נוראים) האוחז ביד מדת משפט."]]],[2300550863,"ב\"ד כידוע) ארוממך אלקי המלך, פי' המלך סתם זהו שנק' מלך יחיד לבדו ומלך הקדוש כנ\"ל שלמעלה מהיות מלך לעולמות, וגם להמלך הקדוש ומרומם לבדו [מאז] א' ארוממך אלקי המלך שירומם עוד<sup data-n=\"8677\">1648</sup> למעלה מעלה יותר. וזה פלא גדול בב' אופנים, א' למה צריך לרוממות יותר מאחר<sup data-n=\"8678\">1649</sup> שאין עוד מלבדו כו'. ועוד האיך יש<sup data-n=\"8679\">1650</sup> ביכולת נפש דוד לרומם להמלך שנקרא מלך מלכי [המלכים] כו'.\n<b>אך</b> הנה עפ\"י הנ\"ל בשרש בחי' המשכות לבוש מל' הפנימיות בעול מצות דוקא כמו בא' אשר קדשנו במצותיו וציוונו כו' עי\"ז דוקא ארוממך אלקי המלך למעלה יותר גם מבחי' הפנימי' מדת מל' דא\"ס שמצד עצמו ממש לפי שנעתב\"ס דוקא, דכאשר המצות שהן פנימיות רצונו שבמהו\"ע (שע\"ז א' רחב\"ה מצות\"ך מאוד<sup data-n=\"8680\">1651</sup> ) ירדו בהתלבשות בלבושים גשמיות בב[י]רורים דרפ\"ח כו' שמזה נעשה בחינות לבוש מל' בקעומ\"ש [בכללות] המצות כנ\"ל ה\"ז עולה לתענוג גדול ונפלא יותר מתענוג העצמי שבפנימיות מדת מל' דא\"ס (הנק' בחי' שעשועי המלך בעצמו כידוע), לפי שנתאווה להיות לו דירה בתחתונים<sup data-n=\"8681\">1652</sup> וסוף מעשה עבמח\"ת כו' ולכך ירומם להמלך סתם בעלוי העונג והמעלה יותר מעונג העצמי בכתר מלכותו העצמי' (וראי' ממ\"ת שכאשר אמרו כל אשר דבר ה' נעשה ירד ה' על ה\"ס בלבוש מל' שנעשה עי\"ז בפנימיות בעול תו\"מ שלמטה דוקא וא' אנכי הוי' אלקיך כו' מי שאנכי<sup data-n=\"8682\">1653</sup> דלמתב\"כ<sup data-n=\"8683\">1655</sup> וכלל<sup data-n=\"8684\">1654</sup> ) וכן מה שאומ' י\"פ דמלכות בר\"ה מעוררים לבחינת פנימיות המל' שעולה ברוממות העצמות יותר והוא מה שנק' מלך הקדוש בקדושה דתו\"מ שלמטה דוקא וכמ\"ש בי מלכים ימלוכו<sup data-n=\"8685\">1657</sup> גם מלכי<sup data-n=\"8686\">1658</sup> כו' מטעם הנ\"ל וד\"ל<sup data-n=\"8687\">1656</sup>.\n<b>וזהו</b> ארוממך בקבלת [עו]מ\"ש במצות המלך שהיה בדוד המלך שהמשיך למעלה בחינת לבוש מל' הפנימית והעצמית הנ\"ל עכ\"ז<sup data-n=\"8688\">1659</sup> עי\"ז ארוממך אלקי המלך לרוממות העצמות דא\"ס בלי שיעור למעלה מעלה דאור א\"ס למעלה<sup data-n=\"8689\">1660</sup> עד אין קץ כו'). אך זהו בבחי' המקיף והוא בבחי' ההתנשאות או<sup data-n=\"8690\">1661</sup> הפנימי' והעצמית ע\"י ביטול הרצון לפנימיות רצונו, אח\"כ א' ואברכה שמך לע\"ו שאחר בחי' העלאה דאו\"ח בבחי'",[["8677","1648","<b>עוד</b>: טזיט: אותו. יז: כבפנים."],["8678","1649","<b>יותר מאחר</b>: טזיט: דאוא\"ס למעלה עד אין קץ כו'. יז: כבפנים."],["8679","1650","<b>יש</b>: טזיט: ליתא. יז: כבפנים."],["8680","1651","<b>רחב\"ה מצות\"ך מאוד</b>: תהלים קיט, צו."],["8681","1652","<b>שנתאווה. . בתחתונים</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא</a> רפל\"ו. לעיל פ' וארא ע, ג. בהערה 67."],["8682","1653","<b>אנכי. . מי שאנכי</b>: נסמן לעיל פ' יתרו רנד, ג."],["8683","1655","<b>(וראי'. . דלמתב\"כ וכלל)</b>: שם: וראי'. . דלמתב\"כ."],["8684","1654","<b>וכלל</b>: טזיזיט: ליתא."],["8685","1657","<b>בי מלכים ימלוכו</b>: משלי ח, טו."],["8686","1658","<b>מלכי</b>: טזיט: מלך מלכי. יז: מלכי'."],["8687","1656","<b>וכן. . וד\"ל</b>: שם: (וכן. . וד\"ל)."],["8688","1659","<b>עכ\"ז</b>: שם: ע\"כ."],["8689","1660","<b>דאור א\"ס למעלה</b>: טזיט: ליתא. יז: כבפנים."],["8690","1661","<b>או</b>: טזיט: ליתא. יז: כבפנים."]]],[2300550864,"הקד[ו]שה ו[ה]הבדלה בערך למעלה מעלה מאד מאד<sup data-n=\"8691\">1662</sup> כנ\"ל זהו עצמו גורם בחי' הירידה וההמשכה מלמעלה למטה בבחי' או\"י, והיינו ממקום ומדריגה שעלה לשם<sup data-n=\"8692\">1663</sup> משם דוקא יומשך למטה והיינו ואברכה שמ\"ך ממש בברכה בג[י]לוי תוס' אור על<sup data-n=\"8693\">1664</sup> המצות דוקא ששורה בהן ברכת הוי', כמו שאו' בברכת המצות בא\"י כו' וישראל נק' ברוכי הוי' ע\"י מעשה המצות וכידוע בכללות ענין המצות שיש בהן יחוד ברכה וקדושה<sup data-n=\"8694\">1665</sup> כו', ועיקר הברכה דשמ\"ך במצות יהי' לע\"ל בעוה\"ב שבא בשכר המצות דוקא כידוע והוא שאומר ברכת ה' היא תעשיר כו'. וז\"ש ואברכ\"ה שמ\"ך לע\"ו בעוה\"ב לע\"ו בנצחיות דא\"ס בברכת עולם, וכן גם עתה בכל יום נמשך ברכה בשם הוי' ויח\"ע דקוב\"ה ושכינתי' בכל מצוה ומצוה ע\"י קבלת עומ\"ש בפנימיות ועצמיות דמדת מל' שעי\"ז ארוממך כו' כנ\"ל ע\"כ אח\"כ נמשך ויורד האור מלמעלה למטה כנ\"ל וד\"ל (וז\"ש שכל האו' תהלה לדוד בכל יום מובטח לו שהוא בן העוה\"ב<sup data-n=\"8695\">1666</sup> לפי שתהלה לדוד מרומם לבחי' המל' דא\"ס עצמו כמ\"ש ארוממך כנ\"ל שעי\"ז נמשך חיי העוה\"ב שז\"ש ואברכ\"ה שמ\"ך ממש לע\"ו כנ\"ל (וזהו ג\"כ פי' הברכה דמצות בא\"י כו' בבחי' ברכ\"ה דשמ\"ך שעי\"ז נקרא מלך העולם כמו בר\"ה שמי\"פ דמל' נעשה רצון למלך על עולמות כו' אשר קדשנו לפי שקדשנו במצותיו בבחי' פנימיות לבוש המל' הנ\"ל) (וז\"ש אתה ה' לבדך<sup data-n=\"8696\">1667</sup> [ממש כמא'] שקודם שנבה\"ע היה הוא ושמו בלבד כנ\"ל (וגם בבחי' מקיף דטה\"ע שלמעלה מטה\"ת שייך להיות מקיף למקיף עכ\"פ להשתל' העולמות<sup data-n=\"8697\">1668</sup>, אבל אתה ה' לבדך זהו כשהיה הוא ושמו הגדול בלבד, ואח\"כ אתה עשית את השמים טה\"ת ושה\"ש<sup data-n=\"8698\">1669</sup> טה\"ע כו', ואתה מחי' את כולם בבחי' ממכ\"ע בבי\"ע בפרטי פרטים עד אתה אשר בחרת באברם<sup data-n=\"8699\">1670</sup> שע\"י היה ג[י]לוי עצמ' שמו הגדול ד\"ע הוי'<sup data-n=\"8700\">1671</sup> ואלקים בעולם כמ\"ש ויקרא אברם בשם הוי' אל עולם<sup data-n=\"8701\">1672</sup> וצדיק כאברהם באמונת\"ו יחי'<sup data-n=\"8702\">1673</sup> שכולל כל התרי\"ג מצות כידוע, וז\"ש כי ידעת[יו] אשר יצוה את בניו<sup data-n=\"8703\">1674</sup> כו' שעי\"ז ארוממ\"ך אלקי המלך כנ\"ל, ומעלוי זה נמשך ונתבר[ך] שמך לעד כו' כמו ואת\"ה מחיה את כולם בבחי' התפשטות במל' למטה עד אין תכלית כמו שהוא למעלה עד אין שיעור כנ\"ל. ועכ\"ז אין בו שינוי כלל כמ\"ש אתה הוא כו' דהיינו שאתה ה' לבדך ממש גם עכשיו שאתה עשית השמים ושה\"ש עד ואתה מחיה כו' וד\"ל).",[["8691","1662","<b>מאד</b>: שם: ליתא."],["8692","1663","<b>לשם</b>: טזיט: ליתא."],["8693","1664","<b>על</b>: שם: ע\"י."],["8694","1665","<b>המצות. . יחוד ברכה וקדושה</b>: ראה גם לעיל פ' בשלח קס, ד ובהנסמן לעיל קנו, ב הערה 315."],["8695","1666","<b>שכל האו' תהלה לדוד. . העוה\"ב</b>: ברכות ד, ב. ראה בגליון הש\"ס שם. לעיל פ' וארא עה, א ובהערה 183."],["8696","1667","<b>אתה ה' לבדך</b>: נחמי' ט, ו [ושם: אתה הוא ה']."],["8697","1668","<b>העולמות</b>: טזיט: ליתא."],["8698","1669","<b>ושה\"ש</b>: בנחמי' שם: שמי השמים — נסמן לעיל פ' בשלח קעא, ד."],["8699","1670","<b>אשר בחרת באברם</b>: נחמי' שם, ז."],["8700","1671","<b>ד\"ע הוי'</b>: טזיזיט: דהוי'."],["8701","1672","<b>ויקרא אברם בשם הוי' אל עולם</b>: ויקרא כא, לג [ושם: ויקרא שם]."],["8702","1673","<b>וצדיק. . באמונת\"ו יחי'</b>: חבקוק ב, ד. ראה מכות כד, א. לעיל פ' תצוה שיח, ג."],["8703","1674","<b>כי ידעת[יו] אשר יצוה את בניו</b>: נסמן לעיל פ' יתרו רנא, א."]]],[2300550865,"<b>וא\"כ</b> יובן עכ\"פ מכל הנ\"ל דמסיבת מעשה המצות למטה דוקא בקעומ\"ש לקיים רצונו במצות דוקא עי\"ז נמשך בחי' פנימיות ועצמיות דמדות מל' ית' שנק' לבוש המל' בפנימיות כבוד הדר מלכותו כנ\"ל, וגם למטה מטה להיות מל' כ\"ע בזמן ומקום כמו מלך ימלוך<sup data-n=\"8704\">1675</sup> כו' מלך העולם נמשך רק מבחי' פנימיות דמל' בתו\"מ ונש\"י (כמו בעטיפת הטלית ובק\"ש שתמליכהו בשמים וארץ<sup data-n=\"8705\">1676</sup> כו' להיות נקרא אלופו ש\"ע כידוע), ולע\"ל יתגלה בחי' פנימיות דמל' דא\"ס כמו שעלה ע\"י המצות מלמטלמ\"ע להיות ביתרון מעלה רבה מבתחלה כנ\"ל והוא שיתגלה במשיח ב\"ד ע\"י שלימות הברורים דמצות דוקא. וז\"ש ויעש דוד שם<sup data-n=\"8706\">1677</sup> פי' שעשה דוד ההעלאה במס\"נ שלו בקעומ\"ש לקיים המצות בפו\"מ בחי' שם דבחינת פנימיות המל' דא\"ס שנקרא שם כבוד מלכותו והוא בחי' שמו הגדול הנ\"ל שעשה אותו שם בתוס' אור ומעלה יתירה והוא מה שיתגלה במשיח (דאדם אד\"ם דוד ומשיח ) שהקים על עולה דתו\"מ כידוע והוא בחינת כתר ש\"ט שעולה ע\"ג ג' הקשרים<sup data-n=\"8707\">1678</sup> כו' כמ\"ש טוב ש\"ם משמן טוב<sup data-n=\"8708\">1679</sup> כו' וזהו ויעש דוד שם וד\"ל.\n<b>וז\"ש</b> ריב\"ק למה קדמה פ' ק\"ש<sup data-n=\"8709\">1680</sup> לפ' ו[ה]א\"ש כדי לקבל עליו עומ\"ש תחלה ואח\"כ עומ\"צ ולכאורה אינו מובן מה שחילק בין עומ\"ש לעומ\"צ. אך הענין הוא דקעומ\"ש זה בפ' דשמע כו' זהו בבחי' מקיף דמל' דא\"ס שבפנימיות ועצמיות שנמשך בתו\"מ דוקא כנ\"ל ואח\"כ מתחלק לפרט שהן עומ\"צ כמ\"ש והיה א\"ש כו' אשר אנכי מצוה כו' לאהבה ולעבדו<sup data-n=\"8710\">1681</sup> בפ\"מ והוא קבלת עומ\"צ בפרט, אבל קבלת מ\"ש בפ' שמע זהו בחי' לבוש מל' כענין שום תשים עליך מלך כו' כמו בטלית כנ\"ל לקבל ע\"ע בכל אשר יגזור או[מר] כו' כמו שקיבלו במ\"ת, וממקיף זה נמשך להתחלק בקעומ\"ש בפרט בכל מצוה למעשה<sup data-n=\"8711\">1682</sup> בפ\"מ כו'. וע\"כ אם אינו מקבל עומ\"ש בכלל דמקיף הנ\"ל איך יקבל עומ\"ש<sup data-n=\"8712\">1683</sup> בפרט לכן הקדים פ' שמע לוהי' [א\"ש] (שפ' שמע בכלל בבחי' שם מ\"ב והי' א\"ש בשם ע\"ב<sup data-n=\"8713\">1684</sup> דחסד<sup data-n=\"8714\">1685</sup> שזהו בבחי' או\"ח ואו\"י ששקולים כא' כנ\"ל בארוממ\"ך ואברכ\"ה כו'). ואמנם כמו שפרט צריך לכלל כך כלל צריך לפרט כו' דאין לחלק ביניהם, לפי שגם בחינת הפרט דרמ\"ח מ\"ע כלולים זע\"ז והיה לאחדים עד שבאמצעות כולם יחד נק' אדם שזהו מבלי שימצא ראש וסוף כלל<sup data-n=\"8715\">1686</sup> דראש מקבל מרגל כו' וכן<sup data-n=\"8716\">1687</sup> כל רמ\"ח אברים נק' קומה א' כו' ולא יש קיום בלא זולתו, ולכך",[["8704","1675","<b>מלך </b>[טז: מלך מלך]<b> ימלוך</b>: ראה זהר בראשית לד, א."],["8705","1676","<b>שתמליכהו בשמים וארץ</b>: ראה זהר (רע\"מ) פינחס רכג, ב. עקב ערב, א. הנסמן במאמרי אדה\"א בראשית ע' לד."],["8706","1677","<b>ויעש דוד שם</b>: שמו\"ב ח, יג."],["8707","1678","<b>הקשרים</b>: טזיזיט: הכתרים."],["8708","1679","<b>טוב ש\"ם משמן טוב</b>: קהלת ז, א."],["8709","1680","<b>ק\"ש</b>: טזיזיט: שמע."],["8710","1681","<b>והיה א\"ש. ולעבדו</b>: עקב יא יג [בדילוג]."],["8711","1682","<b>למעשה</b>: טז: ומעשה. יז: כבפנים. יט: ומצוה."],["8712","1683","<b>עומ\"ש</b>: שם: עול מצות."],["8713","1684","<b>שמע. . שם מ\"ב והי' א\"ש בשם ע\"ב</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשח ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670410\" data-slug=\"torat-chaim\" data-id=\"2300670410\">תו\"ח בראשית מ, ד</a>. ובהערה 51."],["8714","1685","<b>בשם ע\"ב דחסד</b>: ראה גם לעיל פ' וארא פה, א ובהערה 816."],["8715","1686","<b>מבלי שימצא ראש וסוף כלל</b>: ע\"פ קהלת ג, יא."],["8716","1687","<b>וכן</b>: טזיט: וכמו."]]],[2300550866,"במצוה א' שהיא אבר א' יש התכללות מכל המצות ואין הפרש בין מצוה קלה לחמורה כלל (כמו מצות צדקה שבבחי' רגל<sup data-n=\"8717\">1688</sup> מעמיד ומקיים למצוה שבראש כת\"ת וק\"ש וכה\"ג כמ\"ש במ\"א). וכמו שבלבוש המקיף לכל הגוף אין חילוק בו מראש לסוף והאוחז במקצתו כאוחז בכולו וממשיך לאדם כולו ע\"י המקצת שבלבושו כמו שתופס בכולו, כך באברים שיאחזנו בידו או ברגלו ימשכנו כולו כא' לפי שהאברים קשורים זע\"ז כא' ונק' קומה א' (והוא לפי שהאברים נק' ג\"כ בבחי' לבוש להלביש לנפש הרוחניות שמתעלמת בו כנ\"ל שנק' בחי' מקיף כללי ג\"כ כו'). וזהו הטעם שגם בקבלת מ\"ש בפרט במצוה א' זהו כמו בקעומ\"ש בכלל דמקיף דמל' הנ\"ל מטעם דאין לחלק בין כלל לפרט אם הפרט ג\"כ הכל כלול כא' כמו גוף ולבוש שמתאחדים כא' כו'. ונמצא דכמו שע\"י בחינת לבוש מל' הנ\"ל יכולים להמשיך כל עצמות אור א\"ס בגלוי למטה כמו למעלה כמו שמושך אדם לחבירו בלבוש כו', כך גם במצוה א' יכולים להמשיך גלוי עצמות אלקות להיות מל' הפנימיות מל' כ\"ע שז\"ש בברכות המצות דוקא אלקינו מלך העולם כו' וד\"ל.\n<b>והנה</b> ידוע דרמ\"ח מ\"ע הן בדרך פרט בהתחלקות ימין ושמאל כו' והל\"ת הן שס\"ה גידים כו' בציור אדם באו\"כ בפרט (ועכ\"ז כלולים כא' ממש כנ\"ל), אבל בדרך כלל נכללו כל המ\"ע ול\"ת בב' מדריגות דחו\"ג שהחסד שרש רמ\"ח מ\"ע (וכמו האהבה שרש המ\"ע<sup data-n=\"8718\">1690</sup> שמקבל עומ\"ש באהבה ורצון לקיים רצונו כו') ושס\"ה ל\"ת בבחי' הגבו'<sup data-n=\"8719\">1689</sup> (שהוא קבלת מ\"ש ביראה ופחד אלקות שמזה יהיה סומ\"ר בכלל ובפרט). וזהו ענין אנכי ולא יהי' לך דכללות רמ\"ח מ\"ע כלולים באנכי וכללות שס\"ה ל\"ת כלולים בלא כו' ולכך בדבור א' נאמרו<sup data-n=\"8720\">1691</sup> לפי שחו\"ג הכולל כל המצות דמ\"ע ול\"ת כלולים יחד בעצמות בעה\"ר (ולכך בקעומ\"ש בכלל נכלל יחד האוי\"ר דמ\"ע ול\"ת כו' שזהו בפ' שמע כנ\"ל שנק' לבוש מל') (וזהו בחי' ההתכללות דחו\"ג בכלל בבחי' המקיף דכת\"ר דוקא (משא\"כ בחו\"ב שבמוח מתחלק לחו\"ג בחדרים שבדעת לל\"ב<sup data-n=\"8721\">1692</sup>, ולמטה בז' מדות דבינה כו' למדות שבלב ומן הלב לאברים בפרט). ויובן מזה דאע\"פ שבכללות כל המצות הן רק בחי' חו\"ג כנ\"ל מ\"מ נחלקים לז' מדות אף בבחי' הכת\"ר שנקרא מקיף הכללי כנ\"ל בענין בחי' לבוש מל' רק שז' מדות הללו הן בבחי' העלם הרצון בבחי'",[["8717","1688","<b>צדקה שבבחי' רגל</b>: ראה אגה\"ק סי\"ט. לעיל פ' שמות מו, ב. וש\"נ."],["8718","1690","<b>האהבה שרש המ\"ע</b>: נסמן לעיל פ' תצוה שכד, א."],["8719","1689","<b>שהחסד שרש רמ\"ח מ\"ע. . ושס\"ה ל\"ת בבחי' הגבו'</b>: נסמן לעיל פ' יתרו רסד, ג."],["8720","1691","<b>אנכי ולא יהי' לך. . בדבור א' נאמרו</b>: נסמן לעיל פ' יתרו רסד, א."],["8721","1692","<b>בחדרים שבדעת לל\"ב</b>: ראה לעיל פ' בא קח, א הערה 463."]]],[2300550867,"מקיף מלמעלה ומאירים גם למטה בהעלם כמו למעלה, וכידוע שלנגד הז' מדות שבאים בגילוי באו\"פ בכלי כך יש בהעלם דמקיף דנר\"ן ג\"כ ז\"מ<sup data-n=\"8722\">1693</sup> ונקרא מדות שבמקיף דצל\"ם כו'.\n<b>וז\"ש</b> (משלי ט') חכמת נשים בנתה ביתה<sup data-n=\"8723\">1694</sup> חצבה עמודיה שבעה דחכמות שנים היינו ח\"ע וח\"ת דתושב\"כ ושבע\"פ<sup data-n=\"8724\">1695</sup> כידוע בזוהר והוא שנק' בית והיכל ואמנם בחי' העמודים המחזיקים הבית מראשו לסופו הן בחי' תר\"ך עמוד\"י או\"ר<sup data-n=\"8725\">1696</sup> שהן תרי\"ג מצות<sup data-n=\"8726\">1697</sup> דאורייתא<sup data-n=\"8727\">1698</sup> וזמד\"ר<sup data-n=\"8728\">1699</sup> כידוע. ואעפ\"י שבדרך פרט הן תר\"ך עמודים שמחברים מעלה ומטה להיות שהמצות הן בחי' מקיפים דוקא כנ\"ל, אבל בכלל אינם רק ז' עמודים בלבד וז\"ש חצבה עמודי\"ה שבעה דוקא, והן ז' מדות העליונים שבבחי' מקיף בהעלם הנ\"ל שהוא השורה על בחי' הלבושים דמצות כעמודים הכוללים שנק' עמודי התוך שמחזיקים הגג עם הרצפה מעליון לתחתון (וכעמודים שבג\"ע<sup data-n=\"8729\">1700</sup> כמ\"ש במ\"א). ורש\"י פי' עמודיה ז' ז' ימ\"ב שהן מדות<sup data-n=\"8730\">1701</sup> דמח' הכלולים בז\"א שנין<sup data-n=\"8731\">1702</sup> כא' (ובאמת זהו זמד\"ר שע\"ז א' חצבה עמודיה ז' שעולים למעלה מתרי\"ג מצות<sup data-n=\"8732\">1703</sup> כמ\"ש במ\"א לפי שא\"ח עט\"ב כו'). וזהו ענין היריעות דמשכן שהן בחי' מקיפים דלבושים דמעשה המצות דוקא כנ\"ל וע\"כ היו ביריעות ז' מינים כוללים והן, תכלת וארגמן ותולעת שני ושש<sup data-n=\"8733\">1704</sup> ועיזים<sup data-n=\"8734\">1705</sup> הרי חמשה ועורות אלים מאדמים ועורות תחשים<sup data-n=\"8735\">1706</sup> למכסה לאהל הרי ז' מינים (דהיינו ד' מיני[ם] תכלת וארגמן ותולעת שני ושש ביריעות שהן עיקר המקיף דע\"ס דקדושה לכך הן יו\"ד יריעות<sup data-n=\"8736\">1707</sup> (ולנגדן ד' כלים ארון ושולחן ומנורה ומזבח הזהב). וזהו דרשה צו\"פ שהוא תכלת ושש שכוללת לחו\"ג דמ\"ע ול\"ת כנ\"ל, ועזים למכסה לאהל והן י\"א יריעות נגד הי\"א ארורים<sup data-n=\"8737\">1708</sup> דק\"נ שיתהפכו לקדושה בבחי' מקיף למקיף שהוא מכסה לאהל וזהו אורך היריעה [ל'] כו' ואורך היריעה דתכלת כ\"ח<sup data-n=\"8738\">1709</sup> דוקא (כמ\"ש במ\"א). והמקיף הג' מכסה למכסה זה שהן עורות אלים מאדמים ועורות תחשים שהוא חשמל דנוג\"ה, וזהו ססגוונא<sup data-n=\"8739\">1710</sup> כמו כתנות עור דאדה\"ר<sup data-n=\"8740\">1711</sup> כו'.\n[ו]<b>ביאור</b> זה היינו מה שמקיפים דנר\"ן צ' ול' ומ\"ם דצל\"ם מתלבש בג' לבושים דנר\"ן שהן מחדו\"מ ומקיף ששורה במח' זהו היריעות דתכלת כו' שכלולים בו חו\"ג כו',",[["8722","1693","<b>ז\"מ</b>: טזיט: מדות. יז: כבפנים."],["8723","1694","<b>(משלי ט) חכמת נשים בנתה ביתה</b>: משלי ט, א [בהוספת תיבת: נשים — וכ\"ה בתוספתא סנהדרין ספ\"ח. באר הגולה באר הרביעי סז, א. חידושי אגדות מהר\"ל ב\"ב יא, א (סו, א). (דרשות מהר\"ל דרוש על המצות נד, ד)]."],["8724","1695","<b>ח\"ע וח\"ת דתושב\"כ ושבע\"פ</b>: ראה גם לעיל פ' וארא עא, ג. וש\"נ."],["8725","1696","<b>תר\"ך עמוד\"י או\"ר</b>: ראה פרדס (שער מהות והנהגה) ש\"ח, פ\"ג. לעיל פ' שמות ח, א הערה 341."],["8726","1697","<b>תרי\"ג מצות</b>: ראה מכות כג, סע\"ב. לעיל פ' בשלח קפט, ג. הערה 250."],["8727","1698","<b>תרי\"ג מצות דאורייתא וזמד\"ר</b>: נסמן לעיל פ' משפטים שא, ב הערה 425."],["8728","1699","<b>וזמד\"ר</b>: ראה אגרת הקדש סכ\"ט. דרך חיים פנ\"ו. פס\"ד. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211410\" data-slug=\"likkutei-sichot\" data-id=\"1300211410\">לקו\"ש יתרו (כרך כא) ע' 401</a> ואילך. שופטים (כרך כט) ע' 104 ואילך. וש\"נ."],["8729","1700","<b>וכעמודים שבג\"ע</b>: ראה גם מאמרי אדה\"ז תקס\"ד ע' קג."],["8730","1701","<b>מדות</b>: טזיט: ז' מדות. יז: כבפנים."],["8731","1702","<b>בז\"א שנין</b>: טז כתב: בז\"א ומחקו ותיקן בוא\"ש."],["8732","1703","<b>זמד\"ר. . שעולים למעלה מתרי\"ג מצות</b>: ראה דרך חיים שבהערה 1699."],["8733","1704","<b>תכלת. . ושש</b>: תרומה כו, א."],["8734","1705","<b>ועיזים</b>: תרומה שם, ז."],["8735","1706","<b>ועורות. . תחשים</b>: שם: כו, יד."],["8736","1707","<b>תכלת. . יו\"ד יריעות</b>: תרומה שם, א."],["8737","1708","<b>ועזים. . י\"א יריעות נגד הי\"א ארורים</b>: שם שם, ז. תבוא כז, טו ואילך. ראה ע\"ח (שער המלכים) שי\"א, פ\"י."],["8738","1709","<b>אורך היריעה [ל']. . דתכלת כ\"ח</b>: תרומה כו, ח. ב. ראה ביאוה\"ז פקודי נח, ג ואילך."],["8739","1710","<b>ססגוונא</b>: נסמן לעיל פ' תרומה שיא, ב."],["8740","1711","<b>כתנות עור דאדה\"ר</b>: בראשית ג, כא. ראה גם לעיל שם."]]],[2300550868,"ואח\"כ מתברר מנוג\"ה גם בחי' לבוש דדיבור שהן העיזים דשעיר דעש\"ו, ואח\"כ לבוש הג' במעשה שהן עורות אלים ועורות תחשים שכלולים בו כל הגוונין דמדות שבמקיף דמ\"ם דצל\"ם דיחידה לפי שנתב\"ס דוקא, וע\"כ הי' זה המכסה עיקר השומר לאוהל דיריעות כו' וז\"ש אך בצלם יתהל\"ך איש כל היום במעשה כו') (ומזבח העולה להקריב חו\"ד מק\"נ זהו כמו המקיף דיריעות עיזים, והכיור וכנו לרחוץ כו' [ו]הוא נגד<sup data-n=\"8741\">*1712</sup> הבירור דמעשה כמו מי יעלה כו' נקי כפיים<sup data-n=\"8742\">1712</sup> כו' שהוא עורות תחשי\"ם במקיף דלבוש המעשה). ועד\"ז יש בירורים מז\"מ דחכ' דאצילות במל' בירידות המדריגות בהיכלות דק\"נ כמ\"ש יונתי<sup data-n=\"8743\">1713</sup> כו', והוא מ\"ש ומרדכי יצא מלפני המלך<sup data-n=\"8744\">1714</sup> שזהו בחי' יסוד אבא בזמן הגלות שמתעלם במקיף הכללי שנק' לבוש מל', ויש בו ג\"כ ז\"מ<sup data-n=\"8745\">1715</sup> כמו שמונה שם לבוש מל' תכלת וחו\"ר ועטרת זהב גדולה כו' (והן רק ששה<sup data-n=\"8746\">1716</sup> עם בוץ וארגמן לפי שהן בחינת ו\"ק דאבא<sup data-n=\"8747\">1717</sup> שיורדים בהעלם למטה במל' כמ\"ש ע\"פ החלצו<sup data-n=\"8748\">1718</sup> כו' הצובאים תמיד<sup data-n=\"8749\">1719</sup> כו', משא\"כ ביריעות שהן ז\"מ שבכת\"ר). וכ\"ז מטעם שהמצות שרשן בבחי' מקיפים דווקא שאין גילוי אור האלקי בא בהם באו\"פ (רק לע\"ל בעוה\"ב שיתגלו מן ההעלם שבהן דוקא באו\"פ בכלי וזהו העוה\"ב, כידוע שעוה\"ב בא בגלוי לנשמות כו') רק כמו לבוש מלבישים לנשמות ואינו נכנס האור בתוך הכלים דנר\"ן כו', אבל שרש התורה שנקרא אור ממש ה\"ז בא בבחי' או\"פ בכלי דוקא עד שיוכל ל[י]כנס בנפש בבחי' מזון וחיות ממש וכמו ותורתך בתוך מעי, וכמו מזון הנשמות בג\"ע מרזין וסודות התורה, וכן בלימוד בגירס' בפה שטוחן בשינים כטוחן מאכל עד שנכנס במעיו ומתברר שם ועולה למוח ולב באור [ו]חיות ממש וד\"ל. וזהו שרש ענין הכלים שהיה במשכן כמו הארון שהוא בחי' כלי ממש לאור א\"ס שבח\"ע דלוחות שהי' שם, וכן המנורה באור דחסד שבחכמה בדרום ושולחן בצפון בבחי' גבורות שבחכ' שמבחי' גבו' נעשה מזון לכלכל כו' והוא לחם דתורה שנק' לחם הפנים<sup data-n=\"8750\">1720</sup>, ומזבח הזהב בבחי' ת\"ת כו' וכמ\"ש במ\"א בפרטי עניני הכלים בכל א' כפי שהוא במדות דמקיף דיריעות דוקא וד\"ל.\n<b>והנה</b> להבין בתוס' ביאור ענין היריעות והכלים דמשכן שזהו ענין מקיפים ופנימי' דתו\"מ דתו' אור בבחי' האו\"פ והמצות בבחי' לבושים דיריעות כו', הנה יש להקדים תחלה",[["8741","*1712","<b>נגד</b>: תוקן ע\"פ טזיט. בכת\"י זה: השגה."],["8742","1712","<b>נקי כפיים</b>: תהלים כד, ד."],["8743","1713","<b>יונתי</b>: שה\"ש ב, יד."],["8744","1714","<b>ומרדכי יצא מלפני המלך</b>: אסתר ח, טו. ראה פע\"ח (שער הפורים) שי\"ט, פ\"ה."],["8745","1715","<b>ז\"מ</b>: ז' מינים. במאמרי אדה\"ז תקס\"ה כאן (ע' שמ): ז' דברים."],["8746","1716","<b>רק ששה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370394\" data-slug=\"torah-or\" data-id=\"3901370394\">תו\"א כאן (פז, ג</a>): וצ\"ע דכאן לא נזכר רק ו' לבושים, ואולי הוא ע\"ד מ\"ש במ\"א בפי' לשון הזהר שיתא אינון שבע אינון כו' ע\"ש. ולהעיר מאוה\"ת מג\"א [מהדורת תש\"נ] ע' קמז ואילך."],["8747","1717","<b>ו\"ק דאבא</b>: ראה גם לעיל פ' שמות יא, א. וש\"נ."],["8748","1718","<b>ע\"פ החלצו</b>: מטות לא, ג. ראה גם לעיל פ' בא צג, א ובהנסמן שם."],["8749","1719","<b>כו' הצובאים תמיד</b>: טזיט: כו' וא' הצובאות תמיד. יז: הצובאי' תמיד. תיבת הצובאים הובא במטות שם, מב. ואולי תיבת תמיד היא הוספת כ\"ק אדה\"א."],["8750","1720","<b>לחם דתורה שנק' לחם הפנים</b>: ראה גם לעיל תטז, ד."]]],[2300550869,"שרש ענין מצות השבת שהקדים כאן לפ' המשכן כנ\"ל ובמה שקורא יום הז' שבת שבתון שלא נזכר כן בשום מקום רק שיום הז' שבת להוי' ולא שבת שבתון כו'. אך הנה יש להקדים ענין א' והוא כידוע ומבואר במ\"א שיש ב' מיני רצון א' נק' רצה\"ת והב' נקרא רצה\"ע<sup data-n=\"8751\">1721</sup> (וזהו יפה את רעייתי כתרצה<sup data-n=\"8752\">1722</sup> שיתחבר רצה\"ע ברצה\"ת דוקא כמ\"ש במ\"א וכמשי\"ת). ויובן זה בנה\"א כמ\"ש בזוהר דאית רצון ואית רצון<sup data-n=\"8753\">1723</sup> כו', דרצה\"ת משמע שרצון זה נמשך מצד מדריגות התחתונים שלמטה שהן כח השכל והמדות שהן למטה מן הרצון בעצם, דעצם הרצון הוא למעלה מן השכל וטעם לגמרי רק שרצון זה בא בהרכבה בשכל וטעם דוקא ע\"כ נק' רצה\"ת עד שנמשך במדות שבלב שלמטה גם מן השכל ונק' רעוד\"ל כידוע. ואעפ\"י שהוא בעומקא דלבא נק' רצה\"ת מאחר שנולד זה הרצון מחמת השכל והטעם שבמוח החכמה ובינה דוקא ונקרא רצון הנולד או רצון המורכב, ואעפ\"י שיגיע רצון זה לענין מס\"נ שהוא למעלה וודאי מן הטעם והדעת מ\"מ נקרא רצה\"ת לבד. וזה אינו מובן כלל למה יקרא רצה\"ת אחר שהוא למעלה מן השכל שזהו ענין מס\"נ. ועוד דאיך יולד רצון בזה מהרכבת השכל והטעם שלמטה ממנו שהשכל והטעם מוגבל בכלי ורצון במס\"נ הוא בלתי מוגבל בכלי כלל.\n<b>אך</b> הנה יובן זה ברצון במס\"נ שבא לאדם בק\"ש בפ' ראשון דשמע ישראל למס\"נ בא' ממש ובואהבת בכל נפשיך אפי' נוטל את נפשיך<sup data-n=\"8754\">1724</sup> ממש כידוע, וזה הרצון בעומק כ\"כ עד שישליך נפשו מנגד ממש כו' הרי הוא נולד מחדש ע\"י ההתבוננות ביח\"ע בע\"ס דאצילות בכלל כמ\"ש ה' אלקינו ה' אחד<sup data-n=\"8755\">1725</sup> דידוע ענין הכוונה בא' זה היינו באל\"ף שהוא בחי' כת\"ר<sup data-n=\"8756\">1726</sup> עליון שנקרא אלופו ש\"ע שיומשך ויתחבר בחי\"ת ודלי\"ת שהן ז' רקיעים וארץ בחי' מעלה ומטה בכלל והוא החי\"ת ודלי\"ת רוחות העולם<sup data-n=\"8757\">1727</sup> דאצילות זהו הד'. וז\"ש תמליכהו בשמים ובארץ וד' רוחות העולם בחי' ו\"ק דבחי' מקום העליון דאצילות שהוא מקומו ש\"ע<sup data-n=\"8758\">1728</sup> כמו ברוך המקו\"ם<sup data-n=\"8759\">1729</sup> אך אין העולם מקומו כמו הנה מקום אתי כו' כמ\"ש משום<sup data-n=\"8760\">1730</sup> דאיהו תפיס בכ\"ע ולמדת\"ב<sup data-n=\"8761\">1731</sup> כו' לכך הוא עיקר ענין היחו\"ע הזה להמשיך ולחבר הא' בחי\"ת ודלי\"ת זהו להמשיך אור א\"ס שבכת\"ר להיות נקרא אלופו ש\"ע בו\"ק העליונים דאצילות כידוע וד\"ל. ועד\"ז יתבונן ביח\"ת בבשכמל\"ו שזהו בבחי' מל' דאצילות בבי\"ע במקום דעולם הבריאה ויצירה עד ו\"ק דמעלה",[["8751","1721","<b>רצה\"ת. . רצה\"ע</b>: ראה גם לעיל פ' תצוה שס, ד."],["8752","1722","<b>יפה את רעייתי כתרצה</b>: שה\"ש ו, ד. ראה גם לעיל פ' תצוה שסד, ג. וש\"נ."],["8753","1723","<b>דאית רצון ואית רצון</b>: ראה זהר (אד\"ר) נשא קכט, א. לעיל פ' בשלח קצט, א הערה 774."],["8754","1724","<b>ובואהבת בכל נפשיך. . נפשיך</b>: ואתחנן ו, ה. ראה ספרי שם. ברכות נד, א (במשנה)."],["8755","1725","<b>ה' אלקינו ה' אחד</b>: ואתחנן ו, ד."],["8756","1726","<b>באל\"ף. . כת\"ר</b>: ראה ת\"ז תמ\"ט. מאמרי אדה\"א ויקרא ח\"ב ע' תרסא. וש\"נ."],["8757","1727","<b>בחי\"ת. . ז' רקיעים וארץ. . ודלי\"ת רוחות העולם</b>: ראה ברכות יג, ב. שו\"ע אדה\"ז הל' ק\"ש סס\"א, ס\"ו."],["8758","1728","<b>שהוא מקומו ש\"ע</b>: ראה ב\"ר פס\"ח, ט. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670491\" data-slug=\"torat-chaim\" data-id=\"2300670491\">תו\"ח בראשית מג, א</a> הערה 2."],["8759","1729","<b>ברוך המקו\"ם</b>: מדות ספ\"ה. הגש\"פ (פסקא זו)."],["8760","1730","<b>משום</b>: טזיט: ליתא. יז: כבפנים."],["8761","1731","<b>דאיהו תפיס בכ\"ע ולמדת\"ב</b>: ראה זהר (רע\"מ) פינחס רכה, א. לעיל פ' יתרו רסב, א הערה 272."]]],[2300550870,"ומטה וד\"ר העולם למטה [ש]זהו נק' ממכ\"ע ג\"כ ביחוד וחיבור דא' בחי\"ת ודלי\"ת בז' רקיעים וארץ וד\"ר כו', וזהו הוי' א[חד] באצילות שהוא שם הוי' בכלל ושמו א[חד] בבי\"ע וכידוע במא[מ'] דכגוונא דאינון<sup data-n=\"8762\">1732</sup> כו' וזהו יחוד הוי' ואלקים יח\"ע ויח\"ת למהוי אב\"א, כמ\"ש השבטים ליעקב שהוא בת\"ת דאצילות בקו האמצעי כו' כשם שאין בלבך אלא א' ביח\"ע דאצילות כך אין בליבנו במל' דאצילות בבי\"ע אלא א' ביח\"ת כמו ביח\"ע ממש וזהו ענין בשכמל\"ו שא' יעקב (ולא א' משה) שמבריח לקצה התחתון דמל' להיות יח\"ת כיחו\"ע ממש וד\"ל.\n<b>והנה</b> כל ניצוץ מישראל שמתבונן בחו\"ב שבנפש ביח\"ע ויח\"ת הנ\"ל בשמע ישראל ובשכמל\"ו בדברים המקרבים לשכל להשיג ו[ל]אמת הדבר בכלי מוחו בבחי' יח\"ע דסובב ויח\"ת דממלא, אעפ\"י שזהו רק בשכל המצומצם בכלי המשיג לפ\"ע לבד עכ\"ז הרי יוליד בלבו ודעתו התפעלות האהבה והרצון (דאהבה הוא רצון לשון אבה והה\"א בא בתוס' לבד כשנמשך ונרגש הרצון בלב<sup data-n=\"8763\">1733</sup> נק' אהבה כמ\"ש במ\"א) בעומק הלב כ\"כ עד שיגיע לבחי' מס\"נ בא[חד] ממש, כמו אליך הוי' נפשי אשא ממש ומסירת הנפש זהו מסירת עצם הרצון בכל לב ונפש עד אפי' נוטל את נפשיך ממש כידוע שזהו יש בכאו\"א בכח ובפועל כו'. אך אעפ\"י שמס\"נ שברצון זה הוא ודאי למעלה מהגבלת הכלי שבשכל וטעם (כמו<sup data-n=\"8764\">1734</sup> מס\"נ הזה הוא לבחי'<sup data-n=\"8765\">1735</sup> מהו\"ע ית' ממש דוקא כמו אליך הוי' כו' דלמחתב\"כ רק ברעו\"ד בעומק כל הנפש העצמיות הוא נתפס כמ\"ש במ\"א), מ\"מ נק' רצה\"ת מאחר שנולד ונעשה רק מסיבת ההתבוננות בלבד שמתבונן ביחו\"ע דסובב ויח\"ת דממלא שמחמת זה דוקא נתפעל ברצון זה, א\"כ עיקר תולדת והתחדשות הרצון הזה לא בא רק מן השכל וטעם. הגם שבהגיע רצון זה בעומקא דלבא ונקרא רעותא דלבא הרי הוא למעלה מהגבלת הטעם והשכל ביחו\"ע ויח\"ת רק למהו\"ע ית' לבדו בלא טעם ודעת כלל מ\"מ נקרא רצה\"ת שהוא שנק' רעוד\"ל בלבד כו', לפי שגם שבמדות שבלב כמו האהבה (בה\"א בגלוי בהרצון בהתפעלות הלב בשר) הוא למעלה מן השכל וטעם זהו שלא יכילנו כלי המדות שבלב המוגבלים שהן למטה מן השכל שבמוח. אך השכל והטעם שבהשגת המוחין דחו\"ב ביחו\"ע ויחו\"ת דסובב וממלא הוא למעלה הרבה נבדל בערך ממהות התפעלות המדות שבלב כידוע שאין ערוך כלל ביניהן, ע\"כ יוכל להיות שמבחי' הארת אור השכל ודעת האלקי שבמוח יוליד זה הרצון שבא ונמשך במדות שבלב שיהי' למעלה מן הטעם והשכל דהיינו למעלה<sup data-n=\"8766\">1736</sup> מן השכל והטעם המצומצם במדות שבלב (וכמו שרואים בחוש שהתבוננות בעומק השכל ודעת שבמוחו יוליד הרצון במוח ועדיין כלול במוח ההשגה ובהגיעו ללב יתפעל שם ביתר מכפי השכל וטעם המוליד לרצון",[["8762","1732","<b>דכגוונא דאינון</b>: זהר תרומה קלה, סע\"א."],["8763","1733","<b>דאהבה. . אבה והה\"א. . הרצון בלב</b>: ראה גם לעיל פ' בשלח קצט, א. וש\"נ."],["8764","1734","<b>כמו</b>: טזיזיט: כי."],["8765","1735","<b>לבחי'</b>: טזיט: לגבי. יז: כבפנים."],["8766","1736","<b>הטעם. . למעלה</b>: טזיט: ליתא. יז: כבפנים."]]],[2300550871,"בתחלה, וא\"ז למעלה מכל עיקר ומקור השכל שהוליד זה הרצון אלא למעלה מכלי המדות שלא יכילנו השכל וטעם לרצון זה מצד קוצר הכלי שלהם כו').\n<b>ויובן</b> זה עד\"מ אדם הגדול בחכ' ששכלו רחב ביותר יוכל לעשות תולדות הרצון מחמת דבר חכ' וטעם שיסביר לתינוק הקטן עד שיחשוק וירצה בדבר זה, ולפי ששכל התינוק קטן ביותר לא יכיל הכלי שלו לטעם ושכל זה שאו[מר] לו הגדול ע\"כ הגם שיולד הרצון בתינוק מצד השכל וטעם הזה אבל מצד קוצר דעתו ושכלו יהיה הרצון הזה אצלו בהתפעלות גדולה למעלה מן הטעם ושכל שלו כידוע וד\"ל (אך באמת גם הרצון שנולד מטעם ושכל הרחב בגדול בחכ' גם הוא נק' רצה\"ת, מאחר שמורכב בהגבלת אור זה השכל והטעם עכ\"פ וכשיופסק ויבוטל הטעם הזה יבוטל הרצון הזה הנעלם<sup data-n=\"8767\">1737</sup> ממנו כאהבה התלוי' בדבר<sup data-n=\"8768\">1738</sup> שבטל דבר בטל אהבה כידוע, ובאמת שעיקר ועצם מהות הרצון הוא בלתי מוגבל כלל שאין דבר שיגבילנו כשכל וטעם, [ו]אף שיבוטל [הטעם] לא יבוטל הרצון לעולם לפי שאין טעם לרצון<sup data-n=\"8769\">1739</sup> כלל אפי' טעם כמוס ונעלם כידוע. ונמצא שיגיע הרצון העצמי למהו\"ע נפשו עד שתכלה נפש[ו] ברצון זה העצמי', והוא שנק' התפעלות עצמיות הנפש ממש עד כלותה כמו נכספה וגם כלתה נפשי<sup data-n=\"8770\">1740</sup> ממש כו'. וזהו עיקר ענין מס\"נ באה\"ר וברצון, שא\"א שיהי' זה ברצון הנולד ומורכב בשכל וטעם אף בעומק הדעת והחכ' שרצון זה לא יכלה הנפש, רק ברצון העצמי שלמעלה מן הטעם לגמרי אפי' מטעם כמוס ביחו\"ע בעומק ההשגה בגדולת ה', כי התפעלות העצמיות בכלות הנפש אינו רק למהו\"ע ית' כמ\"ש אליך הוי' כו' שלמעלה מטעם והשגה דסובב כו' דלמתב\"כ אפי' למחה\"ק כו' כידוע. וא\"כ יפלא מאין יבא בחינת מס\"נ באה\"ר שברצון הנולד מן השכל בהגיעו ללב ששם יתפעל למעלה מן השכל והשגה לגמרי רק בתשוקה עצמיות בכל לבו ונפשו כו' עד כלותה ממש וזהו פלא, מאחר שזהו שהרצון למעלה מן השכל וטעם במדות שבלב אינו רק מחמת בחי' קטנות המדות שבלב כמשל הנ\"ל בהתפעלות התינוק, ושרש רצון זה הרי הוא עכ\"פ מורכב ומוגבל בגדלות השכל שבמוחין דחו\"ב שלא יגיע מזה למס\"נ כי מס\"נ זהו למעלה מן הטעם דוקא, וז\"ש ואהבת בכל לבבך אחר שמע ישראל בהשגה וטעם בה' א[חד] כו', אך גם בשמע ישראל כו' הוא למס\"נ באחד בנשמתו ואיך יוכל להיות ע\"י השגה וטעם לבד מאחר שנק' רצה\"ת לבד, אלא צ\"ל דיש בזה ב' מדריגות א' בבחי' אוי\"ר<sup data-n=\"8771\">1741</sup> והב' בבחי' או\"ח.\n<b>והענין</b> הוא דבאמת גם בחי' רצה\"ת הזה הוא נמשך מרצה\"ע<sup data-n=\"8772\">1742</sup> שלמעלה מן השכל והשגה וטעם והוא",[["8767","1737","<b>הנעלם</b>: טזיט: הנולד. יז: כבפנים."],["8768","1738","<b>כאהבה התלוי' בדבר</b>: אבות פ\"ה, מט\"ז."],["8769","1739","<b>שאין טעם לרצון</b>: נסמן לעיל פ' תצוה שעה, ד."],["8770","1740","<b>נכספה וגם כלתה נפשי</b>: תהלים פד, ג."],["8771","1741","<b>אוי\"ר</b>: טזיזיט: או\"י."],["8772","1742","<b>מרצה\"ע</b>: תוקן ע\"פ טזיזיט."]]],[2300550872,"בחי' התפעלות העצמיות דנש\"י כמו כל עצמותי תאמרנה<sup data-n=\"8773\">1743</sup> כו', רק שצריך שיומשך אותו בהתפעלות עצמות הרצון שנקרא רצה\"ע (כמשי\"ת) ושיבא בהרכבה והגבלה דוקא בשכל והשגה<sup data-n=\"8774\">1744</sup> ודעת האלקי בשמע ישראל שמדבר לנשמ' האלקית<sup data-n=\"8775\">1745</sup> שנקרא ישראל לי ראש<sup data-n=\"8776\">1746</sup> שתשמע ותבין בבינה וחכ' איך שהוי' אלקינו הוי' א[חד]. ובאמת מצוה זו דאורייתא שתעמיק הנפש בדעת והשגה זו איך שה' אלקינו כו' ולכאו' מה צריך לזה הלא מס\"נ בעצם למעלה מן [ה]השגה לגמרי והוא עיקר המצוה, אלא צ\"ל שאדרבה שמס\"נ בעצמות הנשמות יומשך ויתלבש דוקא בדעת והשגה זו, כמו שהזהיר כמה פעמים וידעת היום כו' אתה הראת לדעת כו' ודעת זו זהו שא' ה' אלקינו דוקא ה' אחד (ובאמת כפי' הפשוט דקדק במ\"ש אלקינו דוקא ולא בזולת זה וזה פלא, כמו מי כה' אלקינו<sup data-n=\"8777\">1747</sup> כו' וכן מי כמוך באלים<sup data-n=\"8778\">1748</sup> כו' דזהו פלא מאין יהיה עולה על הדעת שיש אלקים זולתו, וכן א' ראו כי אני כו' ואין אלקי' כו' וכן אין קדוש כה'<sup data-n=\"8779\">1749</sup> וכה\"ג. אלא השלילה בזה הוא ליחד יחוד פנימי בהוי' שהוא אלקינו דוקא שהוא הוי' א' ולא זולתו דהכוונה הוא כמו שא' אטו האידנא לאו א' הוא<sup data-n=\"8780\">1750</sup> כו'. אלא שהשתלשלות דסובב וממלא לבריאת העולמות אינו רק בחי' חיצוניות השפע האלקי' שנבדל בערך מפנימיות ועצמי' דאור א\"ס שבאצי' שלמעלה לגמרי מהשפעת דאו\"כ דאצי' במל', וזהו בחי' פנימי' דאו\"א וזו\"נ שזהו בחי' יחו\"ע ויח\"ת בכלל ששרשן בפנימי' ועצמיות דא\"ס ממש קודם הצמצום בקו\"ח כו' שאין העולם מקומו כלל, ומה שנמשך להיות אלופו ש\"ע זהו ע\"י ישראל ששרשם ע\"י תו\"מ בפנימיות ועצמיות בחכמה ומדות דא\"ס בבחי' לבוש מל' הפנימי' ועצמיות ממש כנ\"ל. ולכך הוא עיקר המ\"ע דק\"ש ליחד יח\"ע זה הפנימי' ועצמי' דוקא שז\"ש שמע ישראל דוקא הוי' אלקינו דוקא המיוחד אלינו בפנימיות שלו שנבדל בערך גם ממל' דא\"ס בקו\"ח להיות אור ושפע דמקיף ופנימיות לעולמות רק בעוה\"ב וגעה\"ע מאיר אפס קציהו כו') הוא<sup data-n=\"8781\">1751</sup> הוי' אחד באח\"פ ממש שאין זה בכל ההשתל' גם בסובב וממלא הכללי כו', לזאת יכול להיות שגם שהנשמה תבין ותשכיל בשכל והשגה בטוב טעם בענין זה דהוי' אלקינו דוקא ה' אח\"פ<sup data-n=\"8782\">1752</sup> ממש כנ\"ל תוכל לבא למס\"נ בא' זה ממש והוא עיקר ענין האריכות בד' דאחד כידוע. ואין שכל והגבלה<sup data-n=\"8783\">1753</sup> זו נקרא הגבלה לרצון זה שנולד מחמתה למס\"נ באח\"פ<sup data-n=\"8784\">1754</sup>, לפי שאין השגה זו שייך רק לפנימי' ועצמי' דנשמ' ששרשה בבחי' פנימי' ועצמיות דא\"ס שע\"ז א' ישראל עבמ\"ח כו' והוא לי רא\"ש כו'. ואין שכל וטעם זה כשאר שכל וטעם הבא בהשגה בסומ\"מ<sup data-n=\"8785\">1755</sup> ששייך להשתלשלות העולמות שמגביל לרצון העצמות שלמעלה מן הטעם לגמרי כנ\"ל, אבל שכל והשגה זו דנשמות בהוי' אלקינו כו' זהו רק מצד שכל ניצוץ",[["8773","1743","<b>כל עצמותי תאמרנה</b>: תהלים לה, י."],["8774","1744","<b>והשגה</b>: טזיט: ליתא. יז: כבפנים."],["8775","1745","<b>בשמע. . לנשמ' האלקית</b>: ראה גם לעיל פ' תצוה שמו, ג. וש\"נ."],["8776","1746","<b>ישראל לי ראש</b>: נסמן לעיל פ' משפטים רפח, ד."],["8777","1747","<b>מי כה' אלקינו</b>: תהלים קיג, ה."],["8778","1748","<b>מי כמוך באלים</b>: בשלח טו, יא."],["8779","1749","<b>אין קדוש כה'</b>: שמו\"א ב, ב."],["8780","1750","<b>אטו האידנא לאו א' הוא</b>: פסחים נ, א. ראה גם מאמרי אדה\"א בראשית ע' שפד."],["8781","1751","<b>הוא</b>: טזיט: ליתא. יז: כבפנים."],["8782","1752","<b>אח\"פ</b>: טז: אחד באח\"פ. יז: אחד. יט: כבפנים."],["8783","1753","<b>והגבלה</b>: שם: והשגה."],["8784","1754","<b>באח\"פ</b>: טזיט: בא' הפשוט."],["8785","1755","<b>בסומ\"מ</b>: בסובב וממלא."]]],[2300550873,"נמשך לשרשו העצמי כי נר הוי' נשמת אדם כו' ולכך או' שמע ישראל דוקא שהנשמה אלקי' דוקא תשיג בפנימיות ועצמיות דשם הוי' כמו שהוא בבחי' אח\"פ ממש גם [דלמת\"ב] כו' וד\"ל. וא\"כ גם בבחי' רצה\"ת הזה שבא במורכב בהשגה דיח\"ע הזה הפנימי' הוא עצמו הרצה\"ע שלמעלה מן הטעם לגמרי ויש בו ג\"כ כח דמס\"נ בא[חד] כו'.\n<b>וזהו</b> בחי' ירידה דאו\"י דכתר בחו\"ב שבבחי' הפנימיות דוקא, ואח\"כ נמשך ויורד עוד למטה במדות שבלב. וזהו ואהבת בה\"א דאהבה שבא [ב]גילוי רצון זה שנולד בשכל והשגה זו העצמיות באח\"פ בלב ג\"כ, ואף שמצומצם יותר מן השכל זה עצמו כמו שהוא בגדלות והרחבה, מ\"מ לא נתמעט אורו כלל וכלל, לפי שכל בחי' פנימי' ועצמיות אינה משתנה ומתמעט אורו אף בהגיעו למ[ח]דו\"מ בא' והיו הדברים<sup data-n=\"8786\">1756</sup> כו' ודברת בם<sup data-n=\"8787\">1757</sup> וקשרתם כו' למעשה בפו\"מ זהו אותו הכח עצמו שהיה בשכל והשגה באח\"פ במס\"נ. אך בהגיע רצה\"ת הזה למטה ביותר והוא בהבל הלב בשר בקטנות מאוד שם תקצר הכלי להכיל האור ויבא לכלל התפעלות בנקודת הרצון שבלב בעומקא דעומקא כמו כמה לך בשרי<sup data-n=\"8788\">1758</sup> כלה שארי ולבבי כו', והוא שנקרא בחי' או\"ח שחוזר האור מרצון הזה באה\"ר למעלה מן הטעם ושכל לגמרי אף לא יגבילנו השגה ושכל ביח\"ע הפנימי הנ\"ל רק למהו\"ע ית' שזהו שנק' רצה\"ע ממש. וזהו ענין עלי[ו]ת דרצה\"ת לרצה\"ע בבחי' או\"ח דוקא אז יאיר ויומשך בחי' רצה\"ע ברצה\"ת (כמשי\"ת), ועליי' זה זהו מנקוד' הלב דוקא שמחמת קטנות שלו לא יוכל להכיל ויוצא מן הגבלת השכל ודעת לגמרי רק בבחי' עצמי' דבחי' יחידה שבנפש במס\"נ דפשוטי' וע\"ה כו' (והוא משום דשרש המדות הטבעיות שבלב בשר בעצמות דיחידה שלמעלה ממדות דחו\"ב וכמ\"ש ואני בהמות הייתי עמך<sup data-n=\"8789\">1759</sup> כו' (וכמ\"ש במ\"א ענין המא' דז\"א בע\"י עצמו אחיד [ותלי']<sup data-n=\"8790\">1760</sup> כו' שזהו ענין ספירת העומר שעורים דבהמה שמזה דוקא הגיעו למ\"ת בגדלות דאבא כו'). וזהו שנק' רצה\"ת פי' הרצון הנולד ומתחדש מן השכל ודעת בהתבוננות כנ\"ל, והשכל והתבוננות הזאת שבק\"ש מתלבש ויורד עוד במדות א[ה]ו\"י שהן למטה גם מן השכל שבמוח שנק' רעותא דלבא כנ\"ל, וכ\"ז הטעם שנק' בחי' רצה\"ת דוקא כנ\"ל וד\"ל.\n<b>אך</b> הנה בחי' רצה\"ע זהו עליון ממש שאינו בא ומתגלה בגילוי ובמורגש למטה בתחתונים כלל, דהיינו שלא יוכל לבא בגילוי מן ההעלם העצמיות שלו אף בשכל והשגה דגדלות המוחין הפנימיות ועצמיות הנ\"ל אף שזהו המביא ג\"כ לבחי' התפעלות עצמי' הרצון כנ\"ל, שהרי יבא מזה לבחינת מס\"נ",[["8786","1756","<b>והיו הדברים</b>: ואתחנן ו, ו."],["8787","1757","<b>ודברת בם</b>: ואתחנן שם, ז."],["8788","1758","<b>כמה לך בשרי</b>: תהלים סג, ב."],["8789","1759","<b>ואני בהמות הייתי עמך</b>: נסמן לעיל פ' משפטים רפב, ב."],["8790","1760","<b>דז\"א בע\"י עצמו אחיד [ותלי']</b>: ראה זהר (אד\"ז) האזינו רצב, א. מאמרי אדה\"א במדבר ח\"ב ע' תצא ואילך. לעיל פ' בא קל, ב ובהערה 796."]]],[2300550874,"בא[חד] במח' והשגה זו דוקא כנ\"ל. וכש\"כ שלא יבא בגילוי למטה יותר והוא במדות שבלב כמו בבחי' אה\"ר שבמורגש בלב כנ\"ל, ואף [ש]גם [שם] יבא לבחינת מס\"נ בכל נפשיך אפי' נוטל את נפשיך ממש כנ\"ל. וביאור הענין שזה שנק' בשם רצה\"ע אינו רק מפני שאין רק<sup data-n=\"8791\">1761</sup> רצון הנולד שנק' מחודש כלל, אלא הוא בחינת מקור לכל התפעלות ותולדות הרצון אף ברצון הפשוט ועצמי והוא עצמו גם שאינו מוליד רצון כלל, ומה שיבא מכח[ו] העצמ[י]' בחי' רצון הנולד ומחודש שנקרא התפעלות רצון עצמי עד שיבא למס\"נ בכח בנשמה ובפועל בגוף כנ\"ל אינו רק חלק א' המאיר מכח העלם העצמות הרצון הזה. וזהו שנק' בחי' התקשרות העצמי' דיחידה (שנק' נקודת עצם יהדותו), שהוא בבחי' ההעלם לגמרי בין במוח בין בלב שלא יבא גם בתולדות רצון העצמי או התפעלות עצמיות, רק לפרקים כשבא לנסיון כאברהם שנק' רחימא דמלכא בעצם נקודה דיחידה שלו שמצאת לבבו נאמן שהיא בהעלם תמיד, וכאשר ניסה אותו בשחיטת בנו באה לגלוי מן ההעלם בתולדות רצון עצמי כמו למס\"נ עקה\"ש שנגלה בזה התקשרות העצמיות ממש. וכך בשרש נש\"י בכ\"א ביחידה שבו חבוקה ודבוקה בעצמיות אלקות בהתקשרות עצמי תמיד רק שהוא בהעלם גדול וכשאומר שמע ישראל הצווי הוא שיצא מן ההעלם לגלוי למס\"נ ברצון הנולד מן השכל והשגה זו באח\"פ כנ\"ל, וכן בירידת אור התקשרות העצמית הזאת [ה]נק' רצה\"ע ממש במדות שבלב יבא למס\"נ בלב בנקודת הרצון אפי' נוטל את נפשיך בפו\"מ כו', שעולה בבחינת או\"ח למעלה מן הטעם לגמרי כנ\"ל (כמשי\"ת).\n<b>וזהו</b> ואהבת גי' ב\"פ אור או\"י ואו\"ח דאה\"ר במס\"נ ממש בשכל ומדות שבלב כנ\"ל ושניהם ממקור א' נמצאו שזהו שנק' רצה\"ע, שהוא העלם עצמות מקור הרצון ש[ב]בחי' יחידה שבנפש שמושלל ונבדל בערך למעלה מעלה מכל בחי' רצון הנולד ונתפעל גם בחכמה ושכל העליון ופנימיות ביותר כו', לפי שהוא באמיתית התקשרות העצמיות שבלתי מורכב כלל אף ברצון ושכל הפנימי הנולדים אף שבא למס\"נ, כי הוא בחי' כח העצם<sup data-n=\"8792\">1762</sup> העצמות דיחידה שנקרא עליו\"ן ממש (ובמ\"א מבואר שזהו נק' בחי' אה\"ר המוסתרת ונעלמת בנפש בנקודת הלב בעצם ונתעוררה מן ההעלם<sup data-n=\"8793\">1763</sup> לפרקים כמו לנסיון למס\"נ עקה\"ש בפ\"מ, או בעת צרתו שנוגע עד הנפש ממש וכמו [ו]פרעה הקריב הקריב לבם לאביהם שבשמים<sup data-n=\"8794\">1764</sup>, וכמו בעשי\"ת שמתעורר נקודת יהדותו שממנה יומשך [ממילא] כל רצון הנולד באה\"ר במורגש במוח ולב<sup data-n=\"8795\">1765</sup> אם בבחי' או\"י או בבחי' או\"ח כנ\"ל וד\"ל). והטעם שנק' עליון ממש לפי שאין כח זה העצמי דמקור",[["8791","1761","<b>שאין רק</b>: טזיזיט: שאינו."],["8792","1762","<b>העצם</b>: טזיט: העלם. יז: כבפנים."],["8793","1763","<b>ההעלם</b>: טזיט: הלב. יז: כבפנים."],["8794","1764","<b>[ו]פרעה הקריב. . שבשמים</b>: בשלח יד, י. ראה שמו\"ר פכ\"א, ה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670125\" data-slug=\"torat-chaim\" data-id=\"2300670125\">תו\"ח נח ס, ב</a> הערה 24."],["8795","1765","<b>ולב</b>: טז: בלב בשר. יז: כבפנים. יט: ולב בשר."]]],[2300550875,"כל רצון טוב כו' מתלבש כמו שהוא בגלוי בדבר שלמטה מן העצמות דיחידה כמו השכל והמדות שהן נק' תחתונים שהן כחות מיוחדים ענפים פרטים מן העצמות דנפש, רק במה שהנפש עצמה תכלה והוא ברצון עצמי ופשוט בתכלית בלתי מורכב בדבר מה כלל. וזהו אה\"ר העצמי' שביחידה שלא נולדה מאיזה דבר מה כשכל ומדות אלא הוא בעצמות הנפש מצד התקשרות העצמיות במקורה כניצוץ הנמשך בשלהבת בלי בחירה ורצון כלל, ולכך ממילא ומאיליה באה אה\"ר זו למעלה מן השכל וטעם לגמרי (והיינו בהגלות נגלות האור האלקי מקור חוצבה אליה בקירוב כשלהבת הסמוכה לניצוץ שאז ממילא תומשך ותוכלל במרוצה גדולה כענין משכני אחריך נרוצה וכמו שהיה במ\"ת שבגלוי אור הוי' מקרוב עכ\"ד פרחה כו' וכן בעי\"ת בהיותו קרוב<sup data-n=\"8796\">1766</sup> כו' כמ\"ש במ\"א). וזהו שנק' אה\"ר העליונה שבאה מבחי' רצה\"ע, שכמו שבנשמה יש התקשרות רצון עצמי כך מלמעלה למטה כמים הפא\"פ יש בחי' רצה\"ע בעצמות אלקות בבחי' מקור כל רצון כו' שנק' חפץ, וכמו והנערה אשר חפץ בה המלך<sup data-n=\"8797\">1767</sup> וכמו כי חפץ בבת יעקב<sup data-n=\"8798\">1768</sup> כו' וכן נש\"י נק' ארץ חפץ<sup data-n=\"8799\">1769</sup> חפצי בה<sup data-n=\"8800\">1770</sup> ובחי' חפץ העליון הזה [היינו] שתמיד יחפוץ וירצה בה כמו כי רוצה ה' בעמו<sup data-n=\"8801\">1771</sup> כו', והוא עצמות הרצון שבלתי מורכב בדבר מה כלל לא בשכל ולא במדות רק התקשרות אה\"ר עצמיות ממש כאב את בן ירצה מצד שנמשך מפנימיות עצמותו, וכך נש\"י נק' בנים<sup data-n=\"8802\">1772</sup> הבן יקיר לי כו' ילד שעשועים ע\"כ המו מעי ל[ו] ממש כו'.\n<b>וז\"ש</b> אה\"ר ואה\"ע אהבתנו לפני ק\"ש שעי\"ז מושך לנש\"י שיוכלו לעלות בק\"ש באה\"ר העצמי' שלהם שהוא מקור הרצון הנולד בשכל ומדות כנ\"ל, וז\"ש בזוהר זכאה ב\"נ דקוב\"ה אתרעי בי' תדיר<sup data-n=\"8803\">1773</sup> כו' ולזאת מתעורר בנשמה כזאת ג\"כ בחי' אה\"ר העצמי' בבחי' יחידה שבנפש (וכמ\"ש רשב\"י בחד קטירא אתקטרנא בי' אחידא בי' להיט'<sup data-n=\"8804\">1774</sup> כו', וז\"ש בה' תתהלל נפשי<sup data-n=\"8805\">1775</sup> הללי נפשי את הוי'<sup data-n=\"8806\">1776</sup> ממש וא\"צ לבחי' מס\"נ<sup data-n=\"8807\">*1777</sup> כלל מאחר שכבר חבוקה ודבוקה למעלה באלקים חיים בלי פירוד וחציצה כלל בתכלית היחוד האמיתי כאלו הן מהות א', וא\"צ לבא לבחי' התפעלות רצון הנולד באמצעות השגה ומדות כלל לפי מה שנתעורר האדם באה\"ר ע\"י השכל או המדות שבלב שנקרא רעוד\"ל שזהו דבר מחודש לפי שעה ואינו עצמי'. ואעפ\"י שיכול למס\"נ<sup data-n=\"8808\">1777</sup> גם זה נק' ביטול היש לאין האלקי שעכ\"פ יש מי שבטל ונסיון יחשב לפי שנחשב בבחי' פירוד ליש בפ\"ע רק שמוסר נפשו בהפקירות כמו אפי' נוטל את נפשיך שבגוף שהוא נפרד ואין בכחו להפריד<sup data-n=\"8809\">1778</sup> גופו לה' אחד כ\"א מצד התגברות",[["8796","1766","<b>בעי\"ת בהיותו קרוב</b>: ר\"ה יח, א. ישעי' נה, ו."],["8797","1767","<b>והנערה אשר חפץ בה המלך</b>: ראה אסתר ב' יג-יד. לעיל פ' בא קכה, ד הערה 599."],["8798","1768","<b>כי חפץ בבת יעקב</b>: וישלח לד, יט."],["8799","1769","<b>נש\"י נק' ארץ חפץ</b>: מלאכי ג, יב."],["8800","1770","<b>חפצי בה</b>: ישעי' סב, ד. ראה שע\"ת ס, ד ואילך ובהערה 14."],["8801","1771","<b>כי רוצה ה' בעמו</b>: תהלים קמט, ד."],["8802","1772","<b>נש\"י נק' בנים</b>: שמות ד, כב. פ' ראה יד, א."],["8803","1773","<b>זכאה ב\"נ דקוב\"ה אתרעי בי' תדיר</b>: ראה זהר שלח קסא, א. ח\"ש קכט, א."],["8804","1774","<b>בחד קטירא. . להיט'</b>: נסמן לעיל פ' משפטים רפט, ב הערה 131."],["8805","1775","<b>בה' תתהלל נפשי</b>: תהלים לד, ג."],["8806","1776","<b>הללי נפשי את הוי'</b>: תהלים קמו, א."],["8807","*1777","<b>מס\"נ</b>: יז ניתוסף: באחד."],["8808","1777","<b>למס\"נ</b>: טזיט: לבא למס\"נ."],["8809","1778","<b>להפריד</b>: טזיזיט: להפקיר."]]],[2300550876,"ההתקשרות הנפש ברוחניות באה\"ר לבלתי יפרד שנקרא מס\"נ בכח בנשמה אז יגבר גם בנה\"ט להפקיר עצמו ממש כמפקיר עצמו למות במלחמה וסכנה עבור אהובו [כ]נפשו כו' וכן לקדש השם הנכבד שנתקשר אליו בנפשו. אך כ\"ז יקרא נסיון וכח זה שעומד בנסיון אינו בא רק מכח התקשרות העצמיות בבחי' יחידה שבנפש כנ\"ל שחבוקה ודבוקה למעלה בעצמי' (והוא מ\"ם דצל\"ם) (שע\"ז א' מיד כלב יחידת\"י<sup data-n=\"8810\">1779</sup> וכידוע במ\"ש [ו]נפש כי תחטא תווהא<sup data-n=\"8811\">1780</sup> הוא כו') שעליה לא שייך ענין נסיון כלל. ולכך אין עיקר הציווי על מס\"נ רק כשבא לנסיון בגופו שבזה צריך לעמוד על נפשו כו', וכמו ר\"ע שא' כל ימי הייתי מצטער<sup data-n=\"8812\">1781</sup> ע\"פ<sup data-n=\"8813\">1782</sup> זה ואהבת<sup data-n=\"8814\">1783</sup> בכל נפשך אפי' נוטל את כו' מתי יבא לידי ואקיימנ[ה] דגם שבכח נשמתו הי' לו מס\"נ באחד בכל יום, אבל בפועל<sup data-n=\"8815\">1784</sup> יהיה הדבר לאמיתתו יותר והיינו מה שמגלה בפועל זה כל אמיתית נקודת יהדותו שבהתקשרות העצמיות דיחידה דוקא, וז\"ש ואקיימנ\"ה כו' שעד שבא לפ\"מ לא קיים בנפשו אמיתי' הדבר דאפי' נוטל כו' אעפ\"י שאמיתי<sup data-n=\"8816\">*1785</sup> הוא בהעלם העצמות דיחידה שממנה הכח ועוז לבא למס\"נ בפ\"מ אבל אינו בא בגלוי כלל והעיקר הוא שיבא בגלוי בנסיון בגוף שזהו עולה למעלה יותר מעצם ההתקשרות דיחידה. וראי' מאברהם אוהבי<sup data-n=\"8817\">1785</sup> אעפ\"י שידע ה' בלבבו הנאמן בהתקשרות העצמיות שלו מ\"מ ע\"י נסיון נתעלה עוז האה\"ר וחיבה יתירה מודעת אליו, אעפ\"י שאין כל חדש בנסיונות אלה אחר שכבר הוכן בכח העצמי, מ\"מ העיקר הוא בגלוי הדבר הזה דבחי'<sup data-n=\"8818\">*1786</sup> התקשרות העצמי' בפ\"מ דוקא דנתב\"ס דוקא לפי שבסוף מעשה בפו\"מ גדול כחו יותר מצד בחינת או\"ח למקורו שעולה למעלה יותר (וזהו הטעם לכל הנסיונות שמנסים לנש\"י בצרות רבות כמ\"ש כי מנסה ה' אלקיכם אתכם לדעת את אשר בלבבו כו' כו' היש לכם<sup data-n=\"8819\">1786</sup> כו', ואעפ\"י שאין כל חדש בנסיונות אלה שמראי' ודאי על עצמות נקוד' יהדותם בפועל כמו שיש בכח בעצמות, אך התענוג הנפלא לאב כראותו התקשרות עוז דבנו אליו בעמדו בנסיונות גדולות עד למס\"נ בפ\"מ וד\"ל.\n<b>אך</b> הנה אין האה\"ר העליונה שבאה מבחי' רצה\"ע שלמעלה מן הדעת לגמרי שזהו בבחי' פנימיות דכת\"ר עליו\"ן באה מלמעלה למטה (בגילוי גמור שזהו במס\"נ בפ\"מ בכל נפשיך אפי' נוטל את כו' כנ\"ל) כ\"א אחרי שיש בחי' כלי למטה דוקא שבה תאחז ותשכ[ו]ן ותתחבר בה, והיינו בחי' האה\"ר שבאה במורכב בשכל והשגה ביח\"ע הפנימי' דוקא שעי\"ז יומשך הניצוץ לשרשו למעלה בפנימיות כנ\"ל ואז יהי' בחי' כלי לאור דאה\"ר דרצה\"ע הנ\"ל שבבחי' יחידה שתומשך למטה ויתחבר רצה\"ע ברצה\"ת עד שיומשך ויתחבר גם במדות שבלב בואהבת בכל לבבך כו' להאיר",[["8810","1779","<b>מיד כלב יחידת\"י</b>: תהלים כב, כא."],["8811","1780","<b>[ו]נפש כי תחטא תווהא</b>: ויקרא [ד, ב] ה, א. ראה זהר ויקרא יג, ב. טז, א. מאמרי אדמו\"ר האמצעי הנחות תקע\"ז ע' שב. וש\"נ."],["8812","1781","<b>כל ימי הייתי מצטער</b>: ראה ברכות סא, ב."],["8813","1782","<b>ע\"פ</b>: יז: ע\"ד."],["8814","1783","<b>ואהבת</b>: טז: ליתא. יז: כבפנים. יט: ואמ'."],["8815","1784","<b>דגם שבכח. . אבל בפועל</b>: ראה שערי תשובה מה, ב ואילך ובהערה 25."],["8816","*1785","<b>שאמיתי</b>: טז: שאמיתתו. יז: שאמיתי'."],["8817","1785","<b>מאברהם אוהבי</b>: ישעי' מא, ח."],["8818","*1786","<b>דבחי'</b>: טז: בכח."],["8819","1786","<b>כי מנסה. . בלבבו </b>[טזיזיט: בלבב(כ)ם]<b>. . כו' כו' </b>[טזיז: כו'. יט: ליתא]<b> היש לכם [טז: הישכם אוהב'. יז</b>: הישכם]: פ' ראה יג, ד [ושם: לדעת הישכם אוהבים. . בכל לבבכם]."]]],[2300550877,"אורו העצמית גם בבחי' רעוד\"ל דוקא, והוא מה שיוצא לאור מן ההעלם דכח התקשרות העצמי' דיחידה הנ\"ל שנק' רצה\"ע בכלל גם בלב בשר הטבעיות להיות מס\"נ בגוף אפי' נוטל כו' וכמו לבטל כל רצון זר הטבעי בתכלית [כ]ענין בטל רצונך<sup data-n=\"8820\">1787</sup> כו'. ואמנם אין בחי' רצה\"ע הזה יורד מהעלמו בבחי' עצמות להאיר ברעוד\"ל הנ\"ל שבא מן השכל שבמוח שנולד מחמתו הרצון הזה בתחלה שנק' רצה\"ת עד שיעלה תחלה הרצה\"ת הזה מלמטה למעלה בבחי' או\"ח להתחבר ברצה\"ע ואז דוקא ירד בחי'<sup data-n=\"8821\">*1788</sup> הרצה\"ע מלמעלה למטה להאיר ולהתחבר ברצה\"ת שבשכל ומדות שבלב הנק' רעוד\"ל שבלא העלאה זו דרצה\"ת למעלה להיות בחי' כלי לאור דרצה\"ע שביחידה אין על מה לשכון האור ומסתלק ומתעלם בהעלם העצמות ואינו מאיר בגלוי למטה כלל (והיינו כמו שע\"י בחי' המיצר ומרירות שבלב מצד המנגד לאלקות שאינו חפץ להיות נפרד לגמרי כמו בע\"ת או בצר לו ביותר בגשמיות או בנסיון כו' יתעורר לצאת מהגבלת הגוף וימאס בחייו ממש למעלה מן הטעם ודעת לגמרי שזהו בחי' או\"ח דרצה\"ת למעלה להתחבר ברצה\"ע הנ\"ל או מצד קוצר הכלי דלב להכיל האה\"ר כו' שעי\"ז יעלה ויצא מן הכלי המגביל ויבא לנקודת עצמות ההתקשרות דרצה\"ע הנ\"ל (והוא בחי' אה\"ר המוסתרת שבתעלומות הלב שיוצא בגלוי בנקודת הלב כפרעה הקריב כו') (ובאמת א\"ז מובן דהלא מבואר למעלה דגם כח ועוז דרצה\"ת שמורכב בשכל ומדות בא ג\"כ מכח העצמות דרצה\"ע<sup data-n=\"8822\">1788</sup> דהתקשרות העצמיות דיחידה הנ\"ל א\"כ למה צריך שיעלה רצה\"ת הזה למעלה להיות<sup data-n=\"8823\">1789</sup> בחינת כלי לאור דרצה\"ע דוקא כו', ועוד [ד]איך יהיה רצה\"ת הזה בחי' כלי לאור דרצה\"ע אחר שרצה\"ת הוא במורכב בשכל וטעם ומדות בלב ורצה\"ע הנ\"ל הוא אור פשוט ועצמי בלתי מוגבל ומתיישב בכלי כלל (והלכך נק' יחידה בבחי' יחידות דעצמות ממש).\n<b>אך</b> הענין הוא דמה שנמשך הרצון הנולד ומחודש בהרכבת השכל מלמעלה מן השכל מבחי' רצון העצמיות הנ\"ל זהו בא בבחי' העלם גדול וצמצום דעצמות הנפש ליתן כח ועוז גם ברצון שנולד מחמת השכל בגלוי ובהגבלה שיהי' גם הוא בלתי מוגבל, והוא מה שנמשך הניצוץ לשרשו למס\"נ באחד בשם הוי' הפנימיות עכ\"פ כמ\"ש אלי\"ך הוי' דוקא נפשי אשא כו' וכמ[ו]\"כ יורדת עוד גם באוי\"ר שבלב שיבא לבלתי הגבלה באה\"ר שבלב שנק' עומקא דלבא כו'. אך כ\"ז נקרא ביטול היש לאין שהוא השכל ומדות שיוצאים מכלי הגבלתם במס\"נ כנ\"ל, אבל בחי' רצה\"ע כמו שהוא בבחינת העצמי' ממש זהו למעלה מביטול היש לאין אלא הוא כלול ומתאחד ממש באין האלקי בלי מהות נפרד כלל כנ\"ל. אך ע\"י שרצה\"ת שבשכל ומדות שבלב יוצאים",[["8820","1787","<b>בטל רצונך</b>: אבות פ\"ב, מ\"ד."],["8821","*1788","<b>בחי'</b>: בכת\"י זה נכפלה תיבה זו."],["8822","1788","<b>דרצה\"ע</b>: טזיט: ליתא. יז: כבפנים."],["8823","1789","<b>למעלה להיות</b>: טזיט: ליתא. יז: כבפנים."]]],[2300550878,"מלמטלמ\"ע בבחי' או\"ח שלא יכ[י]ל הכלי לאה\"ר אם מצד תוקף וכח דאה\"ר בבחי' התקשרות העצמיות דיחידה שבהעלם בהם כנ\"ל או מצד שיצר לנפש מן המנגד שיעורר לבחי' התקשרות העצמיות כפרעה הקריב כו', אז נעשה רצה\"ת הזה בחי' כלי ממש לאור הפשוט ועצמי דרצה\"ע הנ\"ל שיאיר בו ויתחבר בו כא' ממש כי גם בחי' רצה\"ת הזה שהיה בהגבלה בשכל ומדות נעשה בלתי מוגבל בביטול היש לאין בפו\"מ (שגדול כחו יותר מבחי'<sup data-n=\"8824\">1790</sup> העצמיות דגם שאין כל חדש בזה מאחר שבא מבחי' התקשרות העצמי' כו', מ\"מ בהגלות כח העצמיות דיחידה בפ\"מ גם בנה\"ט בלב בשר כנ\"ל כמו בנסיונות וצרות אז יגדל בחי' הכלי הזה יותר להיות שורה בזה ממקור הראשון דעצמות דיחידה שהוא פנימיות ועצמיות אלקות שלמעלה גם מן הרצון הנק' כ\"ע<sup data-n=\"8825\">1791</sup> כנ\"ל וד\"ל). וזהו ואהבת ב\"פ אור או\"י ואו\"ח דבכללות שניהם יחד שבא מכח העצמות דיחידה זהו שלימות דאה\"ר העצמיות שבאה ממילא, וזהו ואהבת לשון צווי<sup data-n=\"8826\">1792</sup> שהוא על מס\"נ בפועל כמ\"ש ר\"ע מתי כו' ואקיימנ[ה] כנ\"ל וגם ואהבת ממילא<sup data-n=\"8827\">1793</sup> מצד הכח העצמיות דיחידה שנק' כח קדישא כמו [ה]עונה איש\"ר בכל כח\"ו<sup data-n=\"8828\">1794</sup> כו' וכמו כשל בעוני כוחי<sup data-n=\"8829\">1795</sup> כמ\"ש בזוהר, וכידוע דכח העצמי הזה נמשך בנשמה בעטיפת הטלית דוקא בבחי' מקיף בהעלם כמ\"ש חדשים לבקרים רב\"ה אמונת\"ך כידוע ובמס\"נ בק\"ש באה לגלוי בב' מדריגות באו\"י ואו\"ח כנ\"ל וד\"ל.\n<b>ובכ\"ז</b> יובן הדוגמא למעלה בענין השבת במה שנק' שבת שבתון דוקא כנ\"ל, דהנה אמרז\"ל אלמלא שמרו ישראל ב' שבתות כהלכתן<sup data-n=\"8830\">1796</sup> מיד היו נגאלין כו' וידוע דענין ב' שבתות הללו היינו שבת תתאה דמעלי שבתא ושבת עילאה דיומא שזהו ב' שבתות כהלכתן, בליל שבת זהו העלאה בבחינת או\"ח בהילוך מלמטלמ\"ע מכל ו' ימי החול ושבת עילאה ביום השבת זהו בחי' ההמשכה דאו\"י כמ\"ש וקראת לשבת עונג כו'. והענין הוא כידוע דו' ימי המעשה העליונים שהן ו' ימ\"ב ששרשן הוא במדות דאצילות שהן מקוריים לוא\"ש דהוי עלמא מאין ליש בזמן ומקום בג' עולמות דבי\"ע ברוחניות וגשמיות הכל הוא נמשך רק מאור הרצון המורכב ומלובש בחו\"ב דאצילות, והיינו מא' דבראשית בחוכמתא וגם בקדמין<sup data-n=\"8831\">1797</sup> שהוא ברצון הקדום שא' והי' העולם בכלל כמ\"ש כי אמרתי עולם כו' כידוע וכמ\"ש בזוהר דבראשית זהו בחינת אור אבא דא[מר] לאימ[א]<sup data-n=\"8832\">1798</sup> שזהו אלקי' עילאה<sup data-n=\"8833\">1799</sup> כו', וידוע דגם החכמה מאי\"ן תמצא שהוא מאי\"ן דכת\"ר<sup data-n=\"8834\">1800</sup> שהוא הרצון (בחי' מזל ונוצ\"ר כו' אותיות צינו\"ר<sup data-n=\"8835\">1801</sup> ורצו\"ן<sup data-n=\"8836\">1802</sup> כידוע), כמו שבאדם התחתון נמצא",[["8824","1790","<b>מבחי'</b>: טזיט: מכח. יז: כבפנים."],["8825","1791","<b>הרצון הנק' כ\"ע</b>: ראה אגה\"ק סכ\"ט. לעיל פ' וארא עט, א הערה 446."],["8826","1792","<b>ואהבת לשון צווי</b>: ראה גם לעיל פ' וארא נב, ג. וש\"נ."],["8827","1793","<b>ואהבת ממילא</b>: ראה גם לעיל פ' יתרו רנד, ב. וש\"נ."],["8828","1794","<b>[ה]עונה איש\"ר בכל כח\"ו</b>: ראה שבת קיט, ב. לעיל פ' וארא עד, ג. וש\"נ."],["8829","1795","<b>כשל בעוני כוחי</b>: תהלים לא, יא. ראה גם לעיל פ' יתרו רנג, ב. וש\"נ."],["8830","1796","<b>אלמלא שמרו ישראל ב' שבתות כהלכתן</b>: ראה שבת קיח, ב. לעיל פ' בשלח רח, ד. וש\"נ."],["8831","1797","<b>דבראשית בחוכמתא וגם בקדמין</b>: ראה תרגום ירושלמי ואונקלוס לבראשית א, א."],["8832","1798","<b>אבא דא[מר] לאימ[א]</b>: ראה זהר בראשית כב, א. הנסמן לעיל רסה, ב."],["8833","1799","<b>לאימ[א] אלקי' עילאה</b>: זהר שם."],["8834","1800","<b>החכמה מאי\"ן. . דכת\"ר</b>: ראה גם לעיל פ' בא קא, ג. וש\"נ."],["8835","1801","<b>ונוצ\"ר. . צינו\"ר</b>: ראה גם לעיל פ' שמות יב, ב הערה 544."],["8836","1802","<b>ונוצ\"ר. . ורצו\"ן</b>: ראה מאמרי אדה\"א דברים ח\"ג ע' א'כו. וש\"נ."]]],[2300550879,"הטעם ושכל מן הרצון דוקא כשירצה בדבר ימצא טעם ושכל לרצון וזהו שנק' בחי' רצה\"ת, כנ\"ל ברצה\"ת דנה\"א שמורכב בשכל והשגה אלקי' ביח\"ע דק\"ש כו' שנקרא רצון הנולד ומתחדש רק מן השכל וטעם, דאעפ\"י שעצם הרצון הוא למעלה מן הטעם לגמרי אפי' [מ]טעם כמוס רק מצד עצם הרצון הוא שבא למצוא מציאות שכל וטעם לרצון הרי הרצון מורכב בזה הטעם עכ\"פ (אך א\"כ אין זה רצון הנולד שנקרא [רצון] מחודש ממש רק מן השכל וטעם שהולידו, והרי הרצון זה הוא עצם הרצון שלמעלה מן הטעם לגמרי שבא במורכב והתלבשות בצמצום והעלם בשכל כו'. הענין הוא כנ\"ל [ש]מה שעצם הרצה\"פ מתלבש בחכ' וטעם זהו בא בצמצום והעלם גדול וע\"כ נראה כאלו רצון המתהוות מן השכל הוא הרצון נולד ומחודש מעיקרו ובאמת זהו עצם הרצון שלמעלה מן השכל כו'). ומבואר למעלה בענין התבוננות בבחי' יח\"ע הפנימי' ובשמע ישראל כו' שהוא בפנימיות ועצמיות דאור א\"ס שבכת\"ר שלמעלה גם מהיות מקור להשתל' דסומ\"מ כו', והוא במל' דא\"ס עצמו כמו שהוא [קודם ה]צמצום בקו\"ח כו' כנ\"ל שנק' לבוש מל' הפנימיות כו' וע\"י ישראל דוקא שנק' הוי' אלקינו הוא שנמשך להיות אלופו ש\"ע בא' דאח\"ד כו', וידוע דבכל ק\"ש מאיר מבחינת קדושה דשבת דוקא דק\"ש ושבת ענין א' הוא ממש.\n<b>והענין</b> הוא דעיקר ענין השבת זהו ענין השביתה מן המלאכה<sup data-n=\"8837\">1803</sup> שהוא בחי' או\"ח למקורו הראשון כו', כי יש כמה מדריגות זו למטה מזו כחכ' בבינה מאין ליש ומבינה למדות שבלב וממדות שבלב למח' ומח' מתלבש בדיבור ודיבור במעשה. וזהו בחי'<sup data-n=\"8838\">1804</sup> הירידה והצמצום דרצה\"ע בחכ' כשעלה ברצונו לברוא את העולם בכלל ירידת הרצון היה מורכב באור החכמה שהוא כמו השכל וטעם לרצה\"פ שבלתי מוגבל כלל בשכל וחכמה שזהו מא[מר] דבראשית נמי מא[מר] הוא<sup data-n=\"8839\">1805</sup>, שזהו התלבשות הרצון בחכ' וטעם לרצון ומח[כ]' נמשך לבינה ומבינה למדות שהן וימ\"ב יום א' יהי אור בחי' חסד דאצי' ומקור לאלף שנה הראשונים בזמן ומקום, וממדות למח' שהן אותיות שנבראו עלמין סתימין דלא אתגליין וממח' לבחי' אותיות הדבור שהן י\"מ שנבראו עלמא דאתגלייא<sup data-n=\"8840\">1806</sup> עד בי\"ע בסוף עולם העשיה. וזהו שנק' מלאכה בחי' התפשטות לחוץ ממנו מגבוה לנמוך כמו מרצון לשכל ומחכ'<sup data-n=\"8841\">1807</sup> למדות כו' עד סוף מעשה אבל בשביתה מן המלאכה הרי חוזר כל כח ואור מלמטלמ\"ע הימנו כמו בשביתה מכח הפועל בנפעל חוזר התפשטות הכח הזה למקורו בעצם כח הפעולה, וכן הדיבור עולה במח' ומח' במדות כו' עד שגם בחי' החכ' שנק' קד\"ש",[["8837","1803","<b>דעיקר ענין השבת. . השביתה מן המלאכה</b>: ראה שערי תשובה צז, א ובהנסמן במ\"מ לשם."],["8838","1804","<b>בחי'</b>: טזיט: ענין. יז: כבפנים."],["8839","1805","<b>דבראשית נמי מא[מר] הוא</b>: ר\"ה לב, א."],["8840","1806","<b>עלמין סתימין דלא אתגליין. . עלמא דאתגלייא</b>: ת\"ז בהקדמה (יז, א)."],["8841","1807","<b>ומחכ'</b>: טזיזיט: ומשכל."]]],[2300550880,"העליון<sup data-n=\"8842\">1808</sup> שהוא אי\"ן לי\"ש דבינה גם הוא עולה<sup data-n=\"8843\">1809</sup> למקורו בבחי' אי\"ן דכת\"ר שהחכמה מאין זה תמצא כנ\"ל. והוא קודם<sup data-n=\"8844\">1810</sup> שיומשך אור החכמה מאין והעלם דרצון לפי שגם בחי' אור הכת\"ר שהוא הרצון עולה מהתלבשות והתפשטות שלו בחכמה ומדות למקורו בבחינת רצה\"ע שהוא בחינת רצה\"פ כמו שהוא טרם שעלה ברצונו לברוא או להאציל כו' שהיה הוא ושמו בלבד (וכמ\"ש בזוהר בריש הורמנא<sup data-n=\"8845\">1811</sup> כו' גליף גליפו בטה\"ע כו' שזהו מה ששיער בעצמו בכח העלם העצמות מה שעתיד להיות ממנו בגלוי הרצון והחכ' לבנין העולמות כידוע), ובחי' העלם דעצמות הרצה\"פ כמו שהוא כלול במהו\"ע א\"ס והחכמה ומדות שבו נק' פנימיות ועצמיות שלמעלה מהיות מקור למקור לכל ההשתל' דאבי\"ע שמקבלים מבחי' רצה\"ת לבד הנ\"ל שאינו רק הרצון שנעשה מורכב בחו\"ב ומדות כמו רצון הנולד ומתחדש בשכל כנ\"ל. וזהו בחי' עליות העולמות בכלות ימי המעשה בליל שבת<sup data-n=\"8846\">1812</sup> דהיינו לפי שכל ההתלבשות דרצה\"ת בחכ' ומדות דאצי' עד מוד\"מ בבי\"ע נסתלק וחוזר (בחי' הפנימיות<sup data-n=\"8847\">1813</sup> שבהן ולא גם החיצונות, שא\"כ היה העולם חוזר למקורו כמ\"ש במ\"א והרי כל מע\"ב חיים וקיימים גם בשבת מי\"מ<sup data-n=\"8848\">1814</sup> כו') למקורא דכולא<sup data-n=\"8849\">1815</sup> באו\"ח מתחתון לעליון בעליות דמלאכים דעשיה ביצירה ויצירה בבריאה ובריאה באצי' כו' עד בחי' נייחא דנר\"ן דאצי' בכתר עליון שהוא הרצון הקדום שבקדמין ברא עולה גם הוא במנוחה ושביתה מהתפשטותו למטה ברצה\"ת הנ\"ל, והיינו בעצמות א\"ס ממש בבחי' מנוחה לחה\"ע שזהו שנקרא עולת שבת בשבתו שגם בחינת שבת עילאה דכתר וחכ' עולה בשבתו שנק' מנוחה עצמיות מנוחה שלימה<sup data-n=\"8850\">1816</sup> שלא מן המלאכה כלל והוא יום שכולו שבת דעוה\"ב שמאיר בכל שבת<sup data-n=\"8851\">1817</sup> כידוע. וא\"כ יובן מזה דעליי' רצה\"ת ברצה\"ע [ורצה\"ע] גם הוא בעצמות בעל הרצון בשבת זהו כמו באדם למטה בעליי' דאו\"ח דרצה\"ת שמורכב בחכ' והשגה בפנימיות יח\"ע דפנימי' הכת\"ר וחכמה בעצמות א\"ס בק\"ש בה' אחד ממש למעלה מן הטעם והשגה לגמרי רק במהו\"ע ית' שזהו בבחי' התקשרות עצמיות דיחידה שממנו מקור כל רצון הנולד ונתפעל כו' בעצמות דיחיד העליון שלמעלה מכל רצון בהעלם [ו]גילוי כו', ולכך ענין יח\"ע דנש\"י בק\"ש הוא ענין א' עם השבת שזהו רק בבחי' יחוד ועלי' באו\"ח בעצמות ממש וד\"ל.\n<b>וז\"ש</b> כאן ו' ימי\"ם תעשה מלאכה בירידה והתלבשות דרצה\"ת בחכ' ומדות דמע\"ב באבי\"ע בכלל וביום הז'",[["8842","1808","<b>החכ' שנק' קד\"ש העליון</b>: נסמן לעיל פ' תצוה שסב, ב."],["8843","1809","<b>עולה</b>: טזיט: חוזר. יז: כבפנים."],["8844","1810","<b>קודם</b>: טזיט: גורם. יז: כבפנים."],["8845","1811","<b>בריש הורמנא</b>: ראה זהר בראשית טו, א."],["8846","1812","<b>עליות העולמות. . בליל שבת</b>: ראה גם לעיל פ' בא צא, ב ובהערה 214."],["8847","1813","<b>עליות העולמות. . בחי' הפנימיות</b>: ראה גם לעיל פ' בשלח רי, א וש\"נ."],["8848","1814","<b>מי\"מ</b>: מיו\"ד מאמרות."],["8849","1815","<b>למקורא דכולא</b>: זהר בראשית לג, א."],["8850","1816","<b>מנוחה שלימה</b>: אתה אחד (מנחה לשבת). ראה מאמרי אדה\"א שמות ח\"א ע' רלו ואילך. קונטרסים ע' ד וע' י."],["8851","1817","<b>יום שכולו שבת. . בכל שבת</b>: ראה מכילתא תשא לא, יג. לעיל פ' שמות לג, ג. וש\"נ."]]],[2300550881,"יהיה לכם קדש שבת שבתון דוקא שזהו עליי' דרצה\"ת ברצה\"ע בבחי' או\"ח לקדמותו בעצמו' א\"ס שבבחי' מנוחה עצמי' שזהו שנקרא שבת שבתון, דכל השבתות נכללו בו כעוה\"ב שנק' מנוחה גם לחה\"ע כו' ([ו]לכך נק' יו\"כ שבת שבתון להיותו מבחי' יובל הכללי<sup data-n=\"8852\">1819</sup> דעולם החירות<sup data-n=\"8853\">1818</sup> כו'). אך כ\"ז הוא<sup data-n=\"8854\">*1820</sup> הוא בחינת עליות דרצה\"ת לרצה\"ע (כמ\"ש וירא אלקים את כל אשר עשה והנה טוב מאוד כו' שעלה התענוג מן המלאכה באו\"ח לתחלת הרצון והחכ' שעלה ברצון עד עצמותו ממש ואז עולה בעלוי המדריגה יותר והוא בשביתה גם מעונג זה דטוב מאוד כו' וזהו ויכולו השמים<sup data-n=\"8855\">1820</sup> כו' כמ\"ש במ\"א), ואמנם אחר שעולה רצה\"ת לרצה\"ע אזי נעשה בחי' כלי לאור להיות חיבור דרצה\"ע ברצה\"ת (והוא כמ\"ש בפ' שמע והיו הדברים כו' בגלוי או\"י דתו\"מ למטה מפנימיות ועצמיות דא\"ס שיבא בכלים דוקא כו' כנ\"ל). וכך הוא בשבת במדריגה הב' דשבת עילאה ביום השבת שא' וקראת לשבת עונג שנמשך בחי' עונג דעצמות א\"ס שלמעלה מן עונג שברצה\"ע לרצה\"ע ו[מ]רצה\"ע לרצה\"ת להתחבר בו מחדש להיות התחדשות האור ושפע מאין דחכמה שבכת\"ר לחכ' ומחכמה למדות עד מחדו\"מ כו' בשביל ו' ימי החול שלאחריו כידוע דיום השבת נק' ברכתא דכל ו' יומין<sup data-n=\"8856\">1821</sup> כמ\"ש ויברך<sup data-n=\"8857\">1822</sup> כו', וזהו כמבואר למעלה בחיבור לאור דרצה\"ע ברצה\"ת אחר שעולה להיות בבחי' כלי לאור שמתחבר בו כאור הנאחז בפתילה וכה\"ג וד\"ל.\n<b>וז\"ש</b> אלמלי שמרו ישראל ב' שבתות כו' א' שבת תתאה דמע\"ש שהילוך שלו הוא מלמטה למעלה בבחי' או\"ח עד שעולה בחי' רצה\"ת ברצה\"ע שזהו בחי' עולת שבת כו' וזהו ויכולו השמים כו' ויכל אלקים<sup data-n=\"8858\">1823</sup> כו' כנ\"ל, ולאחר ההעלאה דאו\"ח זה בליל שבת חוזר ויורד בחי' המשכה דאו\"י דכל העלאה גורם המשכה<sup data-n=\"8859\">1824</sup> לפ\"ע כידוע, וזהו המשכת רצה\"ע שכבר עלה בעצמות וממקום שעלה דוקא משם הוא חוזר ויורד למטה כמו השביתה שהיא מגעת לעצמות ממש משם יחזור ויאיר. אך הארה זו ה\"ז מעונג העצמות דמנוחה העצמיות דעוה\"ב כנ\"ל, והוא בחי' עונג הנעלם שבהעלם העצמיות דא\"ס שלמעלה מכל עונג שברצון כו' כנ\"ל שזהו העוה\"ב וז\"ש שמיד היו נגאלין וד\"ל (והוא יום שכולו שבת שמאיר בכל שבת אחר העליה דיום השבת עצמו כמ\"ש מזמור שיר ליום השבת<sup data-n=\"8860\">1825</sup> כו' כידוע וכמ\"ש וקראת לשבת עונג העליון לקדוש הוי' כו' שמעונג<sup data-n=\"8861\">1826</sup> הנעלם הוא עצמו שבא בעונג מורגש בעוה\"ב<sup data-n=\"8862\">1827</sup> כנ\"ל).",[["8852","1819","<b>הכללי</b>: טזיזיט: ליתא."],["8853","1818","<b>יו\"כ. . יובל. . דעולם החירות</b>: ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' שנט."],["8854","*1820","<b>הוא</b>: תיבה זו נכפלה בכת\"י זה."],["8855","1820","<b>ויכולו השמים</b>: בראשית ב, א. ראה גם לעיל פ' בשלח רכ, ב. וש\"נ."],["8856","1821","<b>השבת נק' ברכתא דכל ו' יומין</b>: ראה זהר בשלח סג, ב."],["8857","1822","<b>ויברך</b>: בראשית ב, ג."],["8858","1823","<b>ויכל אלקים</b>: בראשית ב, ב."],["8859","1824","<b>דכל העלאה גורם המשכה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680362\" data-slug=\"torat-chaim\" data-id=\"2300680362\">תו\"ח וישלח קצד, ב</a> ובהערה 35. לעיל פ' בשלח ריט, א."],["8860","1825","<b>מזמור שיר ליום השבת</b>: תהלים צב, א."],["8861","1826","<b>שמעונג</b>: טז: וכמו מענגי' כו' שעונג. יז: שעונג. יט: וכמו מענגו כו' שעונג."],["8862","1827","<b>בעוה\"ב</b>: טזיט: כעוה\"ב."]]],[2300550882,"<b>אך</b> הנה עדיין אין ענין השבת דומה לענין ק\"ש, דבק\"ש תחלה נמשך מרצה\"ע באו\"י להיות מורכב בשכל והשגה שנק' רצה\"ת וגם במדות שבלב בפסוק ואהבת בכל נפשיך אפי' נוטל כו' שאז עולה אח\"כ באו\"ח) [ש]זהו ענין מס\"נ בביטול והפקירות מיש לאין שהוא כפי ערך הכח ו[ה]עוז דאו\"י מבחי' התקשרות העצמות דיחידה דוקא כנ\"ל. ובענין השבת נהפוך הוא שתחלה עולה באו\"ח מרצה\"ת לרצה\"ע בליל שבת כנ\"ל ואח\"כ נמשך מרצה\"ע לרצה\"ת בעונג דשבת דיומא כו'. אמנם הנה מבואר למעלה דמה שעולה באו\"ח בביטול היש לאין במס\"נ בלב ומוח (אחר המשכה הנעלמת דיחידה כו') [ו]עי\"ז דוקא נעשה רצה\"ת בחי' כלי לאור רצה\"ע העצמיות שיומשך ויתחבר ברצה\"ת בשכל ומדות כו', והמשכה הזאת זהו בהמשכות גילוי אלקות להמשיך אורות בכלים דוקא בבחי' שוב כו', וזהו והיו הדברים כו' אשר אנכי מצוך כו' ודברת בם כו' בתו\"מ למעשה שהן ו' ימי המעשה הפנימי' לברר בירורים ברפ\"ח כו' (שהן ל\"ט מלאכות בפרט כנ\"ל). ואמנם דרך כלל כל ימות החול הוא בחי' הכנה לשבת דמי שטרח בע\"ש כו' וגם מצות ק\"ש שבכל יום במס\"נ בא[חד] הוא [רק הכנה לשבת דוקא]. והענין הוא כידוע ההפרש בין תפלת החול לתפלת השבת<sup data-n=\"8863\">1828</sup>, דתפלת החול הוא בא בדרך עבודה לברר ולתקן לעה\"ד כו' לאכפייא לס\"א לבער הרע, וע\"י ההתבוננות ביח\"ע בק\"ש והתפעלות המדות דאוי\"ר בלב [בשר דוקא באהבה דבכל לבבך] שהוא בשני יצריך דוקא אזי מבטל כל רצון זר ורע להיות רק לב א' לאבשב\"ש הנק' בר לבב כמו במס\"נ אפי' נוטל כו' כנ\"ל. והעלאת מ\"נ זו עולה מכל ימי החול בק\"ש ותפילה שבכל יום [ב]שבת [והיינו בליל שבת דווקא] שהוא ג\"כ בבחי' ההעלאה דאו\"ח דוקא כנ\"ל שרצה\"ת דמע\"ב עולה בעצמו' רצה\"ע כו'. וזהו תפלה דליל שבת שעולה בהעלאה דעונג האלקי דוקא כמ\"ש בזוהר אז תתענג על הוי' דא צלותא דמע\"ש דוקא שזהו ההעלאה בבחי' או\"ח מלמטלמ\"ע לצאת מכלי ההגבלה דשכל ומדות שבמוח ולב כו', אבל אין זה רק בהעלאה דעונג העצמי' דנשמה האלקי' שתתענג על ה' בעונג נפלא שהוא בכלות הנפש וכמו נכספה וגם כלתה נפשי מצד התגברות העלאה דעונג, והוא למעלה מבחי' עבודה בב[י]רורים דעה\"ד בתפלה וק\"ש דחול רק שבחי' העלאה דאו\"ח במס\"נ בהפקירות בביטול היש לאין (אפי' ביצה\"ר כנ\"ל) בק\"ש דכל יום הוא הכנה להעלאת התענוג האלקי דנשמה בצלותא דמע\"ש כו' וד\"ל. וכמ\"כ בחינת השוב דימות החול בהמשכה וירידה דאו\"י ממקום שעלה לשם במס\"נ ברץ לבך בואהבת כו' להמשיך בתו\"מ גלוי אלקות בכלים מכלים שונים כמו במ\"ש והי' הדברים כו' כנ\"ל ובעסק התו\"מ וצדקה כל היום זהו שנקרא הכנה רבה לבחי' הירידה והמשכות דעונג העצמיות דא\"ס בכתר וחכ' במדות ביום השבת כנ\"ל במ\"ש וקראת לשבת עונג כו')",[["8863","1828","<b>ההפרש בין תפלת החול לתפלת השבת</b>: ראה גם לעיל פ' תרומה שו, א. וש\"נ."]]],[2300550883,"(וכסעודת דשבת דא היא סעודתא דע\"י ממש בעוה\"ב שהוא [שכר] התו\"מ בפ\"מ דוקא כידוע), ואם לא בחי' המשכות אלקות באו\"י אחר העלאה דאו\"ח בק\"ש בכל יום לא הי' נמשך מעונג העצמי' דאור חדש בשבת מעין העוה\"ב בשביל ימות החול שלאחריו כנ\"ל וד\"ל (וא\"כ יובן מזה עכ\"פ דק\"ש ותפלה דכל יום הגם שנקרא פנימיות לחיצוניות הבירורים דכל יום שעולה מכל מה שעוסק כל יום באוי\"ר במס\"נ כו', אבל לגבי בחי' השבת נק' רק חיצוניות העולה ליכלל בקדש העליון דשבת בב' מדריגות הנ\"ל דש\"ת וש\"ע שהוא ליל שבת ויום השבת, שזהו ענין ב' שבתות כהלכתן הנ\"ל שע\"ז אמר את שבתותי תשמרו כו' והוא שא' ו' ימים דוקא תעשה מלאכה באו\"ח ואו\"י בק\"ש ואז וביום הז' כו' שבת שבתון כעוה\"ב כנ\"ל וד\"ל).\nוהנה להבין כ\"ז בתוס' ביאור יש להקדים ענין א' הידוע ומבואר במ\"א ע\"פ כי אל דעות הוי' כו' שיש ב' מיני דיעות בחי' ד\"ע ובחי' ד\"ת והוא כמו ענין הנ\"ל בב' מיני רצון רצה\"ע ורצה\"ת כך יש ד\"ע וד\"ת, דברצה\"ע יש בחי' ד\"ע שהוא המביא לידי גלוי רצה\"ע להיות נמשך ומתחבר למטה וד\"ת זהו שמביא לרצה\"ת להיות [נמשך] ומתחבר למעלה, כי הכלל הוא שהדעת הוא בחי' ההתקשרות<sup data-n=\"8864\">1829</sup> בכל מקום שהוא, דהיינו בחי' כח המתקשר ומתחבר מעליון לתחתון ומדבר להיפוכו ובשכל וחכ' זהו שנקרא דעת נוטה<sup data-n=\"8865\">1830</sup> שמטה השכל וממשיכו כלפי חסד או שנוטה לשכל לדין כו' (כמ\"ש במ\"א). וגם כאן כשהדעת הוא בבחינת הרצון שלמעלה מן השכל יש ג\"כ בחינת דעת שהוא כח המטה וממשיך את הרצון לאופן כך וכך או לאופן אחר כמו שיהיה נמשך הרצון לחסד או שיטה הרצון לדין או לממוצע כו', ונמצא שהדעת הוא חיצוניות הרצון<sup data-n=\"8866\">1831</sup> אחר שמטהו להתפשט ולמשוך למטה כמו במדות לחסד או לדין. אבל מ\"מ מאחר שיש בכח הדעת הזה להטות לרצון לדבר או להיפוכו כפי שיורה הדעת לבד, מוכרח לומר שיש שרש בדעת למעלה מן הרצון דוקא ע\"כ יש בכחו להטותו לרצון שיומשך באופן כך ולא כך (כמו שהרצון להיותו למעלה מן השכל יטה לשכל לזכות או לחוב כפי הרצון רק שהטייה זו עפ\"י הדעת שבשכל שנקרא ד\"ת (כמשי\"ת), ומבואר במ\"א בביאור ענין זה (בפסוק ארדה נא<sup data-n=\"8867\">1832</sup> כו') שיש ב' מדריגות בבחינת הדעת הזה, א' כמו שהוא בבחי' הכת\"ר שהוא הרצון כידוע שמטה לרצון לחו\"ג כנ\"ל, וגם זה בב' מדריגות א' ברצון שנמשך בחכ' שבכת\"ר שנקרא טעם כמוס לרצון עכ\"פ שבו מתחלק הרצון לחו\"ג וממוצע כנ\"ל והתחלקות זו באה ע\"י הדעת דוקא שנק' ד\"ע שבכת\"ר שמטה<sup data-n=\"8868\">1833</sup> הרצון בטעם כמוס לחסד און לדין (כמו שד\"ת מטה השכל הגלוי להיות נוטה<sup data-n=\"8869\">1834</sup> לזכות או לחוב), והב' גם למעלה מטעם כמוס לרצון והוא גם בבחינת עצמיות כח הרצון ממש (שנק' רצה\"ע ממש",[["8864","1829","<b>שהדעת. . ההתקשרות</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא</a> פ\"ג. לעיל פ' בשלח קנה, ג. וש\"נ."],["8865","1830","<b>דעת נוטה</b>: ראה גם לעיל פ' שמות מב, א. וש\"נ."],["8866","1831","<b>שהדעת הוא חיצוניות הרצון</b>: ראה גם מאמרי אדמו\"ר הזקן תקס\"ה כאן ס\"ע שמא."],["8867","1832","<b>בפסוק אדרה נא</b>: וירא יח, כא. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670239\" data-slug=\"torat-chaim\" data-id=\"2300670239\">תורת חיים וירא קיב, א</a> ואילך."],["8868","1833","<b>שמטה</b>: טז: להיות נוטה ומטה. יז: כבפנים. יט: להיות מטה. וראה הערה הבאה."],["8869","1834","<b>להיות נוטה</b>: טזיט: ליתא. יז: כבפנים. וראה הערה שלפנ\"ז."]]],[2300550884,"כנ\"ל) שלמעלה מהתפשטות גלוי הרצון כלל. גם יש בו יכולת בבחי' הדעת עליון הזה להטות עצם כח הרצון כלפי טוב בכמה אופנים שונים עד שיבא לגלוי ממילא כך גם בטעם כמוס לרצון כו'.\n<b>ונמצא</b> מאחר שהרצון יש בו כח הטייה לחו\"ג בין בגלוי הרצון ובין בעצם הרצון שגם שאינו רק בהטי' חיצוניות של הרצון לבד, אבל שרש כח הטייה זו באה מלמעלה גם מעצם כח הרצון ג\"כ והוא בעצמות הנפש ממש שהוא בחי' כח ההתקשרות העצמיות שבנפש שהנפש בעצמ[ה ו]מהותה ממש מתקשרת לדבר מה (שנקרא הטיית המהות [ו]העצם ממש כמ\"ש במ\"א), ע\"כ יש כח גם להטות ולהמשיך עצם כח הרצון וגלוי הרצון לדבר זה, והוא שרש כח הדעת שבנפש עצמ' שמתקשר ומטה כל עצמות שלו מצד עוצם ההרגשה וההכרה שהכיר וידע לדבר זה כמו והאדם ידע את חוה אשתו<sup data-n=\"8870\">1835</sup>, פי' ידע זה היינו בחי' הכרה<sup data-n=\"8871\">1836</sup> וידיעה במורגש בעצמו ביותר והוא כח ההתקשרות שמתקשר כל עצמו להטות כל הנפש אליה מפני עוצם תוקף הכרתו וידיעתו אותה במהו\"ע נפשו ממש, וכמו רק אתכם ידעתי<sup data-n=\"8872\">1837</sup> מכל משפחות האדמה כו' פי' ידעתי הכרתי בהכרה וידיעה העצמית באה\"ר עד שנמשך ומתקשר בכל עצמו בהם. וכמו\"כ נש\"י נתקשרו בידיעה והכרה באלקות במהו\"ע שלהם כמו ב' או\"נ שתיכף שמכירים ויודעים זא\"ז בידיעה והכרה העצמיית נתקשרו נפשותם זע\"ז באה\"ר ונפלאה כדוד ויונתן כו' (כמו כי חפץ בבת יעקב חפץ זה בא מצד ההתקשרות שידע והכיר אותה ותדבק נפשו<sup data-n=\"8873\">1838</sup> ונתקשר בה ביותר וכמו ונפשו קשורה בנפשו<sup data-n=\"8874\">1839</sup> וכן ונפש י[ה]ונתן נקשרה<sup data-n=\"8875\">1840</sup> כו'), וכן הוא מ\"ש והאדם ידע את חוה כו'. שנמצא מובן מכל אלה עכ\"פ שבכח הדעת הוא המגיע בעצם פנימיות הנפש שלמעלה גם מעצם הרצון עד שממילא נמשך גם בחפץ ורצון העצמיות בתמידות (כמו מעשה בא' שהעלה בלבו<sup data-n=\"8876\">1841</sup> כו' לפי שנתקשרה נפשו בכח הדעת עד שנחלה כו') (וכן יש בחינת דעת כזה בהתקשרות העצמית מן המקבל למשפיע כמו ואל אישך תשוקתך<sup data-n=\"8877\">1842</sup> כו' כמו לע\"ל שא' כולם ידעו אותי בדעת המטה כל הנפש שהוא בחינת הכרה עצמית ע\"כ א' ידעו אותי ממש כו' וד\"ל) (ולכך בגלות א' סמכוני כו' כי חולת אהבה אני<sup data-n=\"8878\">1843</sup> כו' מצד עצם ההתקשרות עצמיות ושאין האשה כורתת ברית אלא למי שעשאה כלי [מביאה ראשונה] כו' כי בועלייך<sup data-n=\"8879\">1844</sup> כו' וכן נש\"י במ\"ת קבלו פב\"פ בכריתות ברית כו' והוא רוחא דשביק בגווה ), והעיקר היה מצד הראיה והכרה",[["8870","1835","<b>והאדם ידע את חוה אשתו</b>: בראשית ד, א."],["8871","1836","<b>ידע. . הכרה</b>: ראה גם לעיל פ' משפטים רפא, סע\"ד. וש\"נ."],["8872","1837","<b>רק אתכם ידעתי</b>: עמוס ג, ב. ראה גם לעיל פ' תצוה שעח, ג."],["8873","1838","<b>ותדבק נפשו</b>: וישלח לד, ג."],["8874","1839","<b>ונפשו קשורה בנפשו</b>: ויגש מד, ל."],["8875","1840","<b>ונפש י[ה]ונתן נקשרה</b>: שמו\"א יח, א."],["8876","1841","<b>מעשה בא' שהעלה בלבו</b>: סנהדרין עה, א."],["8877","1842","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["8878","1843","<b>סמכוני. . אהבה אני</b>: שה\"ש ב, ה."],["8879","1844","<b>כי בועלייך</b>: ישעי' נד, ה."]]],[2300550885,"פב\"פ והוא מה שראו את הנשמע<sup data-n=\"8880\">1845</sup> שהוא קול אלקים חיים מדבר מתוך האש<sup data-n=\"8881\">1846</sup> וכמ\"ש רצוננו לראות את מלכנו<sup data-n=\"8882\">1847</sup> וכשראו מיד נתקשרה נפשם ולבם בעצמות שזהו בבחינת כח הדעת עצמית מן המקבל למשפיע ע\"י ראי' והכרה כדוד ויונתן כו', כמו שמן המשפיע למקבל כמ\"ש רק אתכם ידעתי מכל כו' שזהו היה במ\"ת שאמר וזרח משעיר כו' ולכך מצות הראי' ברגל<sup data-n=\"8883\">1848</sup> כמ\"ש ג\"פ בשנה יראה<sup data-n=\"8884\">1849</sup> כו' לפי שבראי' זו את פני הוי' כו' יתקשרו בתמידות כו' וד\"ל.\n<b>והנה</b> כמו שד\"ע הוא כח של<sup data-n=\"8885\">1850</sup> ההתקשרות בעצם ע\"כ הוא המביא ומחבר לעצמות הנפש שיומשך לדבר מה בעצם וכמו<sup data-n=\"8886\">1851</sup> מביא ומחבר לרצון העצמי שירצה ויחפוץ בדבר למעלה מן הטעם תמיד וממילא יומשך לגילוי רצון [ורצון] לשכל וטעם כו', כך הוא בבחי' ד\"ת שזהו כח ההתקשרות דמקבל למשפיע כנ\"ל והוא שנק' רצה\"ת שמורכב בשכל ושכל במדות שבלב שנק' רעוד\"ל שבחינת דעת זה הוא המטה וממליך<sup data-n=\"8887\">1852</sup> את הרצון שבלב לצאת מכלי שלו וליכלל ולהתחבר למעלה. וכמו שרואים בחוש שמדות שבלב המקבלים מן הרצה\"ע שלמעלה מן השכל שהוא עובר דרך השכל שבמוח ללב שכפי שיתפעל ברצון שבשכל כך או כך כמ\"כ יתפעל בלב מלמטה למעלה כו', והוא לפי שבחינת ד\"ע הנ\"ל המטה הרצון בהעלם ובגלוי כך מטה השכל בגלוי עפ\"י בחינת ד\"ת ומן השכל מטה הדעת לחו\"ג שנק' דעת המתפשט במדות<sup data-n=\"8888\">1853</sup>, והוא בחי' כח ההתקשרות שבמדות שבלב שמטה לרצון בלב כו' (וכמו השוחד שיעור עיני חכמים<sup data-n=\"8889\">1854</sup> לפי שהשוחד חמד בלבו ונעשה בלב כח התקשרות בעצם הנפש להיות הרצון בגלוי גם בשכל להטות לזכות בכל יכולתו כמו שד\"ע מטה לעצם הרצון מלמעלה למטה כך בחי' ד\"ת שבלבו מטה לרצה\"ת שבלב מלמטה למעלה שיעשה<sup data-n=\"8890\">1855</sup> למעלה בעצם הרצון שבנפש ולהתחבר ברצה\"ע כו' כמקבל שמתקשר במשפיע כמו שהמשפיע מתקשר במקבל, וב' מיני התקשרות הללו הן בבחינת עצמיות רק זה מלמעלה למטה וזה מלמטלמ\"ע כו' וד\"ל) (ולפי\"ז הגם שד\"ת שבשכל ומדות שבלב נק' מקבל מד\"ת<sup data-n=\"8891\">1856</sup> שברצה\"ע ועצמות הנפש כו', מ\"מ אין חילוק כלל ביניהם דכח התקשרות העצמיות הנ\"ל (כיחידה שבנפש כנ\"ל) ישנו גם בד\"ת שבלב להיות גם המשכת עצם הרצון לדבר שחומד בלבו כמו מד\"ע ממש, וכמו השוחד שחמד בלבו בהתקשרות עצמיו' הנפש ע\"כ ממילא מטה לעצם הרצון רק שהוא מלמטה למעלה כו' שתכסוף נפשו לממון וכן בכוסף נפשו לחמוד בלבו אשת חן כמו בשמשון שא' כי היא ישרה בעיני<sup data-n=\"8892\">1857</sup> וכשכם שדבקה נפשו בדינה",[["8880","1845","<b>שראו את הנשמע</b>: נסמן לעיל פ' תצוה של, ד."],["8881","1846","<b>קול אלקים. . האש</b>: ואתחנן ה, כג."],["8882","1847","<b>רצוננו לראות את מלכנו</b>: מכילתא יתרו יט, ט (הובא ברש\"י שם)."],["8883","1848","<b>מצות הראי' ברגל</b>: ספר המצות להרמב\"ם מ\"ע נג."],["8884","1849","<b>ג\"פ בשנה יראה</b>: משפטים כג, יז. תשא לד, כג. פ' ראה טז, טז."],["8885","1850","<b>של</b>: טזיט: ליתא."],["8886","1851","<b>וכמו</b>: שם: וכן."],["8887","1852","<b>וממליך</b>: טזיזיט: וממשיך."],["8888","1853","<b>דעת המתפשט במדות</b>: ראה גם תו\"ח ויצא קע, ב. ובהערה 30. מאמרי אדה\"א הנחות תקע\"ז ע' שנד. לעיל פ' משפטים רפב, ג."],["8889","1854","<b>השוחד שיעור עיני חכמים</b>: פ' שופטים טז, כ. ראה גם לעיל פ' בשלח קצט, ג. וש\"נ."],["8890","1855","<b>שיעשה</b>: טזיט: שיעלה. יז: כבפנים."],["8891","1856","<b>מד\"ת</b>: שם: מד\"ע."],["8892","1857","<b>כי היא ישרה בעיני</b>: ס' שופטים יד, ג."]]],[2300550886,"כו' וזהו בלב דוקא דעין רואה והלב חומד<sup data-n=\"8893\">1858</sup> כידוע) וראי' מחולת אהבה שהיא בלב דוקא [ו]כמו מעשה בא' שהעלה בלבו טינא כו') ואין הפרש בין זל\"ז כלל רק במה שמבחי' ד\"ע נמשך ע\"י התקשרות העצמיות מלמעלמ\"ט וע\"י ד\"ת שבלב נמשך מלמטה למעלה כמו שהיה במ\"ת כנ\"ל וד\"ל).\n<b>ונמצא</b> מובן מכל הנ\"ל בשרש מהות ענין הדעת שהוא הידיעה וההכרה עצמיות המביא להיות בחינת ההתקשרות וההתחברות לזולתו הנפרד ממנו עד שידבקו והיה לאחדים ממש, והיינו ע\"י ההכרה והידיעה שמכירו ויודעו במהו\"ע שנקרא ידיעת והכרת המהות ולא במציאות לבד שעי\"ז נמשך רצונו אליו ולבו ונפשו מתמשך אליו בתמידות עד שלא יוכל לנטות ממנו כלל (וכמו ידע שור קונהו [כו'] ישראל לא ידע כו' שנמשך השור אחר קונהו לפי שי[ו]דע ומכיר אותו). ונמצא דהדעת ענין א' עם הרצון כי כמו שהרצון הוא המשכת והטיית הנפש לדבר מה שרוצה בו (כי רצון לשון מרוצ\"ה<sup data-n=\"8894\">1859</sup> שתרוץ הנפש כמו אחריך נרוצ\"ה) לחוץ ממנו להתחבר בו ולידבק נפשו בו ממש, [ו]כך הוא הדעת בידיעה והכרה שמכיר וי[ו]דע את הדבר הוא כח המביא לבחי' ההתקשרות וההתחברות לאותו הדבר להטות כל נפשו אליו כנ\"ל. רק שהרצון בא בהתפעלות [ו]חשק ותאותו בפנימיות ההתקשרות בדבר זה (כמו כי חפץ כו') והדעת בהכרה עצמית כנ\"ל מקשר עצמו בבחינת חיצוניות כמו לילך תמיד אחריו (כמשרת לאדון שעוזב כל אשר לו ונמשך בכל עצמו לשרשו, וכן תלמיד לרבו כאלישע לאליהו ויהושע למשה וכה\"ג). אבל באמת שרש הדעת למעלה מן הרצון שנמשך בפנימיות החשק, מאחר שע\"י הדעת הרי מטה עצמות נפשו להיות לו ממילא גם החפץ ורצון להתקשר בפנימיות (וא\"כ גם מה שד\"ת מטה לשכל זהו ג\"כ רק מצד הרצון שלמעלה מן השכל והוא שנקרא רצה\"ת כי הדעת שייך לרצון דוקא (ולכך הדעת עולה עד הכת\"ר<sup data-n=\"8895\">1860</sup> עצמו משא\"כ חו\"ב, וראיה לזה שבי\"ס אם הדעת נמנה אין הכתר נמנה<sup data-n=\"8896\">1861</sup> כו'), רק שד\"ת הוא שעולה בהתקשרות ורצון זה מלמטלמ\"ע דוקא כנ\"ל).\n<b>ובכל</b> הנ\"ל יובן ג\"כ בדוגמא למעלה בבחי' רצה\"ע ורצה\"ת [שלמעלה] שהוא בב' מדריגות דאו\"י ואו\"ח שהן ב' מיני דעות, בחי' ד\"ע זהו המביא לבחי' רצה\"ע להמש[י]ך ולהתחבר למטה ברצה\"ת [בבחי'] או\"י שהן בוי\"ו ימי המעשה העליונים ששרשם בחכמה, ורצה\"ת שזהו מה שהרצון מורכב בחכמה",[["8893","1858","<b>דעין רואה והלב חומד</b>: רש\"י שלח טו, לט. ראה הנסמן במאמרי אדה\"א דברים ח\"ב ע' תרפד־ שמות ח\"א ע' כ."],["8894","1859","<b>רצון לשון מרוצ\"ה</b>: ראה גם לעיל פ' תצוה שעח, א. וש\"נ."],["8895","1860","<b>הדעת עולה עד הכת\"ר</b>: ראה שערי אורה — לר\"י גיקטלייא — שער ה (ע' 126). מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תערב. מאמרי אדה\"א במדבר ח\"ד ע' א'שצז. וש\"נ."],["8896","1861","<b>אם הדעת נמנה אין הכתר נמנה</b>: ראה ע\"ח (שער מוחין דצלם) שכ\"ג, פ\"ה. לעיל פ' בא פט, ג הערה 138."]]],[2300550887,"וטעם ובמדות שלמעלה זהו<sup data-n=\"8897\">1862</sup> בראשית ברא אלקים כנ\"ל, והיינו כמו כשעלה ברצונו לברוא ולהאציל כו' שירד זה הרצון בגלוי בחכמה מאין ליש בבינה ומבינה למדות עד סומ\"ע כנ\"ל. אך באמת א\"א להיות גלוי רצון זה להשתל' מאחר שעצמות אא\"ס נבדל בערך כנ\"ל שזהו גם<sup data-n=\"8898\">1863</sup> מבחי' הרצון, וגם רצונו הוא [ג\"כ] בחי' רצה\"פ ועצמי' בעצמ[ו]' דא\"ס דאיהו ועצמ[ו]' רצונו חד<sup data-n=\"8899\">1864</sup> ממש, ואיך יוכל להיות גלוי אור דרצה\"פ [ה]זה שנקרא רצה\"ע ממש כנ\"ל [ל]בא ולהתחבר בערך הרצון הנבדל לחוץ מן העצמות שהוא רצה\"ת שמורכב בחכ' ומדות למע\"ב. אלא צ\"ל שיש בזה כח המביא לידי גלוי אור מרצה\"ע הפשוט (שהי' הוא ושמו גי' רצון<sup data-n=\"8900\">1865</sup> בלבד ממש) שממשיך גם זה הרצון העצמי (שלמעלה מרצון הנולד הנ\"ל) והוא ע\"י בחי' ד\"ע, שכח הד\"ע הזה הוא כמו כח המטה לנפש עצמ[ה] להיות נמשך ומתקשר בעצם לדבר מה שהוא הגורם הטיי' הרצון העצמי' ג\"כ (כמו שיש כח בד\"ע זה להטות מרצון לרצון היפוכו כנ\"ל גם ברצון שלמעלה מן הטעם שמוכרח לומר ששרשו בהתקשרות דעצמות כנ\"ל) עד שיבא לגלוי רצון בטעם כמוס ממילא כך א[ע\"]פ שאינו אלא הטיית חיצוניות הרצון כנ\"ל.\n<b>וז\"ש</b> כשעלה ברצה\"פ להאציל כו' [ש]עלי' ברצה\"פ זהו ע\"י בחי' ד\"ע (וזהו כמבואר במ\"א בביאור ב' דיעות<sup data-n=\"8901\">1866</sup>, ד\"ע מיש האמיתי לאי\"ן כמו היה הוא ושמו בלבד שזהו גלוי רצה\"פ ולא בא לכלל מקור עדיין, רק הוא גלוי אור העצמות לבד שנבדל בערך מבחי' מקור הרצון וחכ' למע\"ב. והב' אין של היש שנעשה הרצון בגלוי להיות מקור לחכ' ו[מ]חכ' לבינה שזהו ד\"ת (ויש ריחוק מקום בין אי\"ן הא' די\"ש האמיתי לאי\"ן דיש מוגבל כו' שנקרא פרס[א], וכמשלים הידועים<sup data-n=\"8902\">1867</sup> מן מעיינות תהום שהארץ עצמה מפסקת להיות מעיין לנהר שנק' אי\"ן ליש מוגבל, וכחיות הרוחניות דנפש בעצם שבכחו להחיות, או כח הצומח שבכחו להצמיח לאין שיעור באין דיש המקורי ונק' גשמיות שברוחניות, ומה שנעשה בחי' גלוי בא' ד\"ם<sup data-n=\"8903\">1868</sup> נק' אי\"ן לי\"ש המוגבל וכח הצמיחה מרוחניות לגשמיות כו'. ואמנם ע\"י ביטול הי\"ש לאי\"ן שלו (כמו עלי' דרצה\"ת המורכב בשכל הנ\"ל) גורם ירידת העולם<sup data-n=\"8904\">1869</sup> האי\"ן הא' דיש המקורי להיות אין לי\"ש כו') (או בדרך אחרת והכל א', דד\"ע זהו ידיעה כללי'<sup data-n=\"8905\">1870</sup> דמח' א' שעלה ברצה\"ע<sup data-n=\"8906\">1871</sup> הפשוט הנ\"ל (כאי\"ן די\"ש האמית\"י כנ\"ל) וכמו בידיע[ת] עצמו יודע את אור הכללי מראש לרגל כו', וד\"ת ידיעה פרטי'<sup data-n=\"8907\">1872</sup> שמתחלק מאין הב' ליש בחו\"ב<sup data-n=\"8908\">1873</sup> ) ובחי' ד\"ת",[["8897","1862","<b>שלמעלה זהו</b>: טזיט: כנ\"ל שזהו. יז: כבפנים. וראה גם הערה הבאה."],["8898","1863","<b>כנ\"ל שזהו גם</b>: טזיט: גם. יז: כנ\"ל שגם. וראה גם הערה שלפנ\"ז."],["8899","1864","<b>דאיהו ועצמ[ו]' רצונו חד</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310043\" data-slug=\"tanya\" data-id=\"3401310043\">תניא פל\"ח (נ, ב</a>). <a class=\"ft-cite\" href=\"#/read/tanya/3401310045\" data-slug=\"tanya\" data-id=\"3401310045\">פ\"מ (נד, ב</a>. <a class=\"ft-cite\" href=\"#/read/tanya/3401310043\" data-slug=\"tanya\" data-id=\"3401310043\">נה, סע\"א</a>)."],["8900","1865","<b>ושמו גי' רצון</b>: ראה מאמרי אדה\"ז תקס\"ד ע' רלו בשם הפרדס. פע\"ח (שער הק\"ש) ש\"ח, ספכ\"ח. מאמרי אדה\"א דברים ח\"ב ע' שסח. וש\"נ."],["8901","1866","<b>בביאור ב' דיעות</b>: ראה שערי אורה שער הפורים ע' 124 ואילך. לעיל פ' וארא נ, ד הערה 69."],["8902","1867","<b>וכמשלים הידועים</b>: ראה גם לעיל פ' בשלח קפו, ד ואילך."],["8903","1868","<b>בא' ד\"ם</b>: טזיט: באדם. יז: כבפנים."],["8904","1869","<b>העולם</b>: טזיט: העלם. יט: ליתא."],["8905","1870","<b>כללי'</b>: תוקן ע\"פ הנ\"ל. ובכת\"י זה: כללים. ראה הערה 1872."],["8906","1871","<b>ברצה\"ע</b>: תוקן ע\"פ הנ\"ל. ובכת\"י זה: ברצה\"פ."],["8907","1872","<b>פרטי'</b>: תוקן ע\"פ הנ\"ל. ובכת\"י זה: פרטים. ראה הערה 1870."],["8908","1873","<b>בחו\"ב</b>: טזיט: ליתא. יז: כבפנים."]]],[2300550888,"הוא ג\"כ<sup data-n=\"8909\">1874</sup> כח המביא לגלוי רצה\"ת שמורכב בחכמה ומדות במע\"ב שמקבל מד\"ע שברצה\"ע כמובן ממשל הנ\"ל ברצה\"ת שבמוח ולב האדם. אך ברצה\"ת ובד\"ת כנ\"ל ה\"ז בבחי' העלאה דאו\"ח בבחי' ביטול היש לאי\"ן<sup data-n=\"8910\">1875</sup> ממדות לשכל ושכל לרצון עד רצה\"ע כנ\"ל, וכך הוא ברצון וחכ' דמע\"ב בבחי' דע\"ת עולה מלמטה למעלה עד שיעלה לרצה\"ע הפשוט במקבל שמעורר בהתקשרות שלו למשפיע בעצמיות הרצון כנ\"ל וד\"ל. וזהו ענין ו' ימי<sup data-n=\"8911\">1876</sup> החול שבא האור [ד]רצה\"ע בירידה והתחברות ברצה\"ת וחוזר ועולה בליל שבת לעורר האור העצמיות ברצה\"ע ע\"י ד\"ע בין בהשבת<sup data-n=\"8912\">1877</sup> לחדש האור ושפע מעליון לתחתון בכלל ובפרט כו' וד\"ל. וזהו כי אל דעות הוי' שסובל ב' דעות ד\"ע וד\"ת שהוא רצה\"ע ורצה\"ת דאו\"י דמשפיע ואו\"ח דמקבל, דהיינו שיהיה התחברות דרצה\"ע ברצה\"ת מלמעלה למטה כנ\"ל (מד\"ע לד\"ת שהוא מאי\"ן הא' לאי\"ן העוה\"ב<sup data-n=\"8913\">1878</sup> הנ\"ל) וע\"י ד\"ת יהיה התחברות דרצה\"ע<sup data-n=\"8914\">1879</sup> לרצה\"ע מלמטה למעלה, ואעפ\"י שד\"ע ודע\"ת שניהם מטים לחיצוניות דרצה\"ע ורצה\"ת לבד, מ\"מ שרשם למעלה בהתקשרות העצמיות שלמעלה גם מעיקר הרצון העצמי בין מלמעלה למטה ובין מלמטה למעלה (דשניהם א' כנ\"ל וד\"ל).\n<b>ועם</b> כל הנ\"ל יובן בתוס' ביאור במ\"ש כאן אלה הדברים אשר צוה ה' כו' ו' ימים תעשה מלאכה וביום הז' יהיה לכם קדש שבת שבתון כו' דאלה הדברים הן ל\"ט מלאכות שנעשים לברר ב[י]רורים כנ\"ל, והוא ירידת האור דרצה\"ע שלמעלה ממקור העולמות להיות נמשך ברצה\"ת להיות מקור ההשתל' מאי\"ן דחכ' ליש במא' דבראשית כו', וכתיב אשר ברא אלקים לעשות דכל מה שברא אלקים ברצון וחכ' ומדות ומחדו\"מ הכל רק לעשות לתקן שהוא הבירור בהעלאה דרפ\"ח ניצוצים שנפלו בק\"נ בעה\"ד טו\"ר במ\"ע ול\"ת כנ\"ל במ\"ש לעבד[ה] ולשמר[ה] שזהו ע\"י תו\"מ, וזהו חיבור הפנימי' דרצה\"ע בתו\"מ להיות בהתלבשות בחכ' ומדות ואותיות דתו' ומעשה המצות שנק' רצה\"ת. וזהו והיו הדברים האלה אשר אנכי כו' והוא מ\"ש אלה הדברים אשר צווה [ה'] כו' שהן רמ\"ח מ\"ע (שבזה יהי' עיקר המשכת הקדושה דעונג העליון בשבת<sup data-n=\"8915\">1880</sup>, כי מצות השבת בכלל כולל הוא רמ\"ח מ\"ע דימות החול בשמירה דקדש ועונג דשבת כשמור וזכור לקדשו<sup data-n=\"8916\">1881</sup> כו' ובמניעה וחיבור<sup data-n=\"8917\">1882</sup> המלאכה בשב ואל תעשה זהו שרש שס\"ה ל\"ת דחול כו' כמ\"ש במ\"א) וזהו ע\"י בחי' ד\"ע (ואין זה רק ע\"י העלאה דאו\"ח שזהו במס\"נ דק\"ש בחכ' ומדות עד בכל לבבך בשני יצרי\"ך ואח\"כ והי[ו] הדברים כו') (וכמ\"כ בחיצוניות השפע",[["8909","1874","<b>ובחי'. . ג\"כ</b>: ניתוסף ע\"פ הנ\"ל ובכת\"י זה הניח מקום פנוי."],["8910","1875","<b>ביטול היש לאי\"ן</b>: ניתוסף ע\"פ הנ\"ל ובכת\"י זה הניח מקום פנוי."],["8911","1876","<b>וזהו ענין ו' ימי</b>: ניתוסף ע\"פ הנ\"ל ובכת\"י זה הניח מקום פנוי."],["8912","1877","<b>בין בהשבת</b>: טזיט: ביום השבת. יז: כבפנים."],["8913","1878","<b>העוה\"ב</b>: שם: הב'."],["8914","1879","<b>דרצה\"ע</b>: שם: דרצה\"ת."],["8915","1880","<b>בשבת</b>: טזיט: ליתא."],["8916","1881","<b>כשמור וזכור לקדשו</b>: ואתחנן ה, יב. יתרו כ, ח."],["8917","1882","<b>וחיבור</b>: טזיזיט: ואיסור."]]],[2300550889,"בחסד שברצה\"ע לבריא[ת] העולמות כתיב ויהי ערב ואח\"כ [ויהי] בקר<sup data-n=\"8918\">1883</sup> בהעלאה דאו\"ח תחלה ואח\"כ המשכה דחסד אל כל היום, דבמע\"ב הלילה אחר היום הבא<sup data-n=\"8919\">1884</sup> כו'. ואעפ\"י שבתחלת הרצון בהשתל' היה רק מצד כי חפץ חסד הוא<sup data-n=\"8920\">1885</sup> מעצמו כטבע הטוב להטיב שלא ע\"י העלאה כו', מ\"מ ברישא חשוכא<sup data-n=\"8921\">1886</sup> כו' לפי שסומ\"ע עבמ\"ת וכענין שאמר במי נמלך<sup data-n=\"8922\">1887</sup> כו' ובראשית בשביל כו' כידוע, ו' ימים תעשה מלאכה בירידה והמשכה מלמעלה למטה מרצה\"ע לרצה\"ת לברר ולתקן לעה\"ד כו' וביום הז' יהיה לכם קדש כו' שזהו לאחר הבירור דו' ימי החול עולה בהעלאה דאו\"ח בליל שבת מרצה\"ת שהוא ד\"ת לד\"ע כמ\"ש ויכולו כו' כנ\"ל (והיינו מהעלאה דמס\"נ בק\"ש כנ\"ל וביום הז' קד\"ש שב\"ת שבתו\"ן בעוה\"ב בירידת דעונג העליון ברצה\"ע למטה (כשכר המצות בעוה\"ב שבא בירידה למטה כו'. וזהו כי אל דעות הוי' ד\"ע וד\"ת שווין ממש כמו בעוה\"ב שיתגלה למטה כמו למעלה ממש ולא שייך עליה וירידה כלל, דאין עליה וירידה שייך רק בבחינת מעלה ומטה או משפיע ומקבל כמו המגביהי לשבת<sup data-n=\"8923\">1888</sup> כו' (וזהו בבחי' מנוחה העצמית שלמעלה מחול ושבת (וכידוע דגם העוה\"ב נחלק לב' מדריגות עליה וירידה כמו ילכו מחיל כו' שאין להם מנוחה כו' וירידה ביום השבת ולמעלה משניהם כשמעלה ומטה שווין<sup data-n=\"8924\">1889</sup> כו' (ובאמת אינו מובן דלפי כל הנ\"ל בחול [בחי'] או\"י קודם לאו\"ח ובשבת [בחי'] או\"ח קודם לאו\"י (ואף בק\"ש או' שמע ישראל שהוא חיבור רצה\"ע ברצה\"ת כו' כנ\"ל), אך במ\"א (בפ' בשלח<sup data-n=\"8925\">1890</sup> ) מבואר דשבת הוא בחינת המל' שמקבל מו' ימים דחול שהן הו' מדות שמשפיעים כצדיקים שנקראו משפיעים בתו\"מ למל' כנ\"ל) ונקרא שב\"ת מלכת\"א<sup data-n=\"8926\">1891</sup> כו' ובעוה\"ב יהיה עלי' המל' למעלה ממדות כו' ולכך בשבת או\"ח קודם לאו\"י וד\"ל.\n<b>והנה</b> אחר כל הנ\"ל יובן ג\"כ ענין סמיכות פ' שבת לפ' מלאכת המשכן בתוס' ביאור, להיות דמ\"ש אלה הדברים כו' והן ל\"ט מלאכות שהיו במשכן שנאסרו בשבת כידוע ומשמע מזה דענין המשכן שייך לענין השבת, והיינו במה שנאסרו ל\"ט מלאכות הללו בשבת שזהו בבחי' העלאה דאו\"ח שעולה רצה\"ת לרצה\"ע וכמ\"ש כי בו שבת מכל מלאכתו<sup data-n=\"8927\">1892</sup> כו' אף ברצון שבח\"ע ומדות כו' ולכך [אמ'] קדש יהיה לכם שבת שבתון<sup data-n=\"8928\">1893</sup> כל העושה בו מלאכה יומת כו' ע\"כ יכול להיות אח\"כ בחי' ירידה והמשכה דוקא. והוא ענין המשכן וכלים שהן בכלל [בחי'] מקיפים וכלים, וכמבואר למעלה דהיריעות שבמשכן הן כמו בחי' לבושים דמעשה המצות שהן בחי' מקיפים דנר\"ן כו' להיות שרש של המצות הוא בפנימיות הרצה\"ע ופנימי' העונג שבהעלם",[["8918","1883","<b>ויהי ערב. . [ויהי] בקר</b>: בראשית א, ה."],["8919","1884","<b>הלילה אחר היום הבא</b>: ראה גם לעיל פ' תצוה שיח, ג. וש\"נ."],["8920","1885","<b>כי חפץ חסד הוא</b>: מיכה ז, יח."],["8921","1886","<b>ברישא חשוכא</b>: שבת עז, ב (כגי' רש\"י). ראה גם לעיל פ' וארא מט, ג."],["8922","1887","<b>במי נמלך</b>: ראה ב\"ר פ\"ח, ז. רו\"ר פ\"ב, ג."],["8923","1888","<b>המגביהי לשבת</b>: תהלים קיג, ה."],["8924","1889","<b>כשמעלה ומטה שווין</b>: ראה גם לעיל פ' בשלח קנט, ג ובהערה 501."],["8925","1890","<b>בפ' בשלח</b>: ראה לעיל פ' בשלח רכ, ד ואילך."],["8926","1891","<b>שב\"ת מלכת\"א</b>: ראה זהר (רע\"מ) צו כט, א. לעיל שם הערה 542."],["8927","1892","<b>כי בו שבת מכל מלאכתו</b>: בראשית ב, ג."],["8928","1893","<b>קדש יהיה. . שבתון</b>: ויקהל לה, ב [ושם: יהי' לכם קדש שבת שבתון לה']."]]]]});
